create   function [dbo].[FN_DCS_10_GetOfficerUserNameTH]
(
    @UserId nvarchar(150) = N''
)
returns nvarchar(200)
as
begin
    return (
        select top (1)
            N'คุณ' + p.FirstName + ' ' + p.LastName
        from dbo.DataPersonalInfo p
        where p.UserId = @UserId
    );
end

create   function [dbo].[FN_DCS_10_GetOfficerUserNameTH_backup]
(
    @UserId nvarchar(150) = N''
)
returns nvarchar(200)
as
begin
    return (
        select top (1)
            N'คุณ' + p.FirstName + ' ' + p.LastName
        from dbo.DataPersonalInfo p
        left join dbo.SystemTitleMaster t on t.TitleId = p.TitleId
        where p.UserId = @UserId
    );
end

CREATE   function [dbo].[FN_DCS_16_GetDebtorName]
(
    @DebtorId nvarchar(150) = N''
)
returns nvarchar(200)
as
begin
    return (
        select top (1)
            case
                when d.PersonGroupId = 117 then t.TitleName + d.FirstName + ' ' + isnull(d.LastName, '')
                else isnull(t.TitleShortName,'') + d.FirstName + ' ' + isnull(d.LastName,'')
            end
        from dbo.DataDebtor d
        left join dbo.SystemTitleMaster t on t.TitleId = d.TitleId
        where d.DebtorId = @DebtorId
    );
end

CREATE FUNCTION [dbo].[Fn_FormatDateMonth] (
  @Date date

)
RETURNS nvarchar(100)
AS
BEGIN


	return FORMAT(@Date, 'MMM', 'th-TH')  
	
	
	
	
	
	+ '' + 
    RIGHT(CONVERT(VARCHAR(4), YEAR(@Date) + 543), 2)
	
	
 
END

CREATE  FUNCTION [dbo].[Fn_FormatDateNCB] (
  @Date date

)
RETURNS nvarchar(100)
AS
BEGIN


	return format(dateadd(year, 543, @Date),'yyyyMMdd') 
	
	
 
END

CREATE   FUNCTION dbo.FN_FormatMillionBaht
(
    @Amount DECIMAL(20,4)
)
RETURNS NVARCHAR(50)
AS
BEGIN
    DECLARE @Result NVARCHAR(50);
    DECLARE @AmountNoDecimal DECIMAL(20,0);
    DECLARE @Million DECIMAL(20,2);

    IF @Amount IS NULL
        RETURN NULL;

    -- ตัดเศษทศนิยมของจำนวนเงินออก เช่น 1,500,000.89 => 1,500,000
    SET @AmountNoDecimal = FLOOR(@Amount);

    -- แปลงเป็นหน่วยล้านบาท และให้มีทศนิยม 2 ตำแหน่ง
    SET @Million = CAST(@AmountNoDecimal / 1000000.0 AS DECIMAL(20,2));

    SET @Result = FORMAT(@Million, 'N2') + N' ลบ';

    RETURN @Result;
END;

CREATE FUNCTION [dbo].[Fn_GetClaimType] (
  @LGNo NVARCHAR(50)
)
RETURNS [BIT]
AS
BEGIN
  DECLARE @Result BIT = 0;
  IF EXISTS(
      SELECT 1 FROM DataLG a
      INNER JOIN SystemClaimTypeMaster b on a.ClaimTypeId = b.ClaimTypeId
      WHERE a.LGNo = @LGNo AND a.Grade = 'F1' AND b.ClaimTypeName IS NOT NULL AND b.ClaimTypeName LIKE N'%พ.ร.ก%'
  )
  BEGIN
      SET @Result = 1;
  END
  RETURN @Result;
END

CREATE FUNCTION [dbo].[FN_GetDistrictName] (@DistrictId INT)
