CREATE FUNCTION dbo.fn_GetPaidInstallmentCount
(
    @DebtorRelateId NVARCHAR(450)
)
RETURNS INT
AS
BEGIN
    DECLARE @PaidInstallmentCount INT;

    SELECT
        @PaidInstallmentCount = COUNT(*)
    FROM dbo.TDRDataCompromiseContractInstallmentPlanPayment AS Payment
    INNER JOIN dbo.TDRDataCompromiseContractLG AS ContractLG
        ON ContractLG.CompromiseContractId =
           Payment.CompromiseContractId
    WHERE ContractLG.DebtorRelateId = @DebtorRelateId
      AND Payment.IsPayment = 1
      AND Payment.IsActive = 1
      AND Payment.IsUpfront = 0;

    RETURN ISNULL(@PaidInstallmentCount, 0);
END;

CREATE FUNCTION [dbo].FN_GetPrincipalBalance (
  @DebtorRelateId NVARCHAR(100)
)
RETURNS DECIMAL(18,2)
AS
BEGIN

    DECLARE @PrincipalTotal DECIMAL(18,2) = 0;
    SELECT TOP (1) @PrincipalTotal = ISNULL(a.PrincipalTotal, 0)
    FROM DataDebtorCard AS a
    WHERE a.DebtorRelateId = @DebtorRelateId

    RETURN ISNULL(@PrincipalTotal, 0);

END

CREATE FUNCTION [dbo].[Fn_GetPrincipalTotal]
(
    @LGNo NVARCHAR(100),
    @CompromiseContractId NVARCHAR(100),
    @DebtorTypeId INT
)
RETURNS DECIMAL(18,2)
AS
BEGIN
    DECLARE @PrincipalTotal DECIMAL(18,2) = 0;

    IF @DebtorTypeId = 1
    BEGIN
        SELECT TOP (1)
            @PrincipalTotal = ISNULL(a.PrincipalTotal, 0)
        FROM TDRDataCompromiseContractLG AS a
        INNER JOIN DataLG AS b
            ON a.LGNo = b.LGNo
        WHERE a.LGNo = @LGNo
          AND b.Grade = 'F1'
          AND a.CompromiseContractId = @CompromiseContractId;
    END
    ELSE
    BEGIN
        SELECT TOP (1)
            @PrincipalTotal = ISNULL(a.PrincipalTotal, 0)
        FROM DataDebtorCard AS a
        WHERE a.LGNo = @LGNo
          AND a.DebtorRelateTypeId = 1;
    END;

    RETURN ISNULL(@PrincipalTotal, 0);
END;

