CREATE   FUNCTION [dbo].[Fn_TDR_001_CountTDR]
(
    @DebtorId NVARCHAR(150),
    @CompromiseContractId NVARCHAR(150)
)
RETURNS INT
AS
BEGIN
    DECLARE @CountTDR INT = 0;

    SELECT @CountTDR = ISNULL(MAX(b.SeqNo), 0)
    FROM dbo.TDRDataCompromiseContractDebtor a
    INNER JOIN dbo.TDRDataCompromiseContract b
        ON a.CompromiseContractId = b.CompromiseContractId
    WHERE a.DebtorId = @DebtorId  AND a.CompromiseContractId = @CompromiseContractId
      AND a.IsMain = 1;

    RETURN @CountTDR;
END;

