create   FUNCTION [dbo].[FN_TDR_08_CheckIsHaircut]
(
    @LG nvarchar(150),
    @CompromiseContractId nvarchar(150),
    @DebtorTypeId int
)
RETURNS bit
AS
BEGIN
    DECLARE @IsHaircut bit;

    SELECT @IsHaircut = measure.[IsHaircut]
    FROM [dbo].[TDRDataCompromiseContract] AS contract
    INNER JOIN [dbo].[SystemMeasureMaster] AS measure
        ON measure.[MeasureId] = contract.[MeasureId]
    WHERE contract.[CompromiseContractId] = @CompromiseContractId;

    RETURN ISNULL(@IsHaircut, 0);
END;

