-- ============================================================
-- SP_ACC_003_eStatementReceipt
-- รับข้อมูลใบเสร็จจาก DCS แล้ว UPSERT เข้า Output_eStatementReceipt
-- เรียกได้จาก SendEStatementReceiptTrigger (JobService) หรือจาก
-- SP_DCS_039_InsertReceipt หลังจากสร้างใบเสร็จสำเร็จ
-- ============================================================
CREATE PROCEDURE [dbo].[SP_ACC_003_eStatementReceipt]
    @MappingReceiptId   nvarchar(150) = '',
    @BillPaymentNo      nvarchar(150) = '',
    @ReceiptNo          nvarchar(150) = '',
    @RequestNo          nvarchar(150) = '',
    @LGNo               nvarchar(150) = '',
    @ReceiptAmount      decimal(18,2) = 0,
    @ReceiptDate        datetime      = NULL,
    @ReceiptType        nvarchar(50)  = '',
    @StatusReceipt      nvarchar(50)  = '',
    @PaymentDes2        nvarchar(500) = '',
    @CreateUser         nvarchar(150) = '',
    @BankCode           nvarchar(50)  = '',
    @TanReceiptNo       nvarchar(150) = '',
    @StatusES           nvarchar(50)  = '',
    @TransStatus        nvarchar(10)  = '01',
    @CreateDate         datetime      = NULL,
    @UpdateDate         datetime      = NULL,
    @InputEStatementId  nvarchar(150) = ''
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NULLIF(LTRIM(RTRIM(@ReceiptNo)), '') IS NULL
        THROW 50001, 'SP_ACC_003_eStatementReceipt requires @ReceiptNo.', 1;

    DECLARE @EStatementId nvarchar(150) = NULL;
    DECLARE @ResolvedMappingReceiptId nvarchar(150) = NULL;
    DECLARE @ResolvedBillPaymentNo nvarchar(150) = NULL;
    DECLARE @ResolvedLGNo nvarchar(150) = NULL;
    DECLARE @ResolvedReceiptAmount decimal(18,2) = @ReceiptAmount;
    DECLARE @ResolvedReceiptDate datetime = @ReceiptDate;
    DECLARE @ResolvedBankCode nvarchar(50) = NULL;
    DECLARE @ResolvedReceiptType nvarchar(50) = COALESCE(NULLIF(LTRIM(RTRIM(@ReceiptType)), ''), '');
    DECLARE @ResolvedStatusReceipt nvarchar(50) = COALESCE(NULLIF(LTRIM(RTRIM(@StatusReceipt)), ''), '1');
    DECLARE @ResolvedStatusES nvarchar(50) = COALESCE(NULLIF(LTRIM(RTRIM(@StatusES)), ''), '1');
    DECLARE @ResolvedTransStatus nvarchar(10) = COALESCE(NULLIF(LTRIM(RTRIM(@TransStatus)), ''), '01');

    -- When called from SP_DCS_039, EStatementId is the most reliable key.
    -- It avoids depending on ReceiptNo, which may not exist on DataEStatement
    -- yet when the DCS receipt is first created.
    SELECT TOP (1)
        @EStatementId = d.EStatementId,
        @ResolvedMappingReceiptId = d.ReceiptId,
        @ResolvedBillPaymentNo = COALESCE(NULLIF(@BillPaymentNo, ''), d.StatementNo),
        @ResolvedLGNo = COALESCE(NULLIF(@LGNo, ''), d.LGNo),
        @ResolvedReceiptAmount = CASE WHEN @ReceiptAmount = 0 THEN d.Amount ELSE @ReceiptAmount END,
        @ResolvedReceiptDate = COALESCE(@ReceiptDate, d.PaymentDate),
        @ResolvedBankCode = COALESCE(NULLIF(@BankCode, ''), d.BankCode)
    FROM [dbo].[DataEStatement] d
    WHERE NULLIF(LTRIM(RTRIM(@InputEStatementId)), '') IS NOT NULL
      AND d.EStatementId = @InputEStatementId
      AND ISNULL(d.IsDelete, 0) = 0;

    -- Prefer the stable mapping id passed by the caller.  SP_INTERFACE_015
    -- stores this value in DataEStatement.ReceiptId.
    IF @EStatementId IS NULL
    BEGIN
        SELECT TOP (1)
            @EStatementId = d.EStatementId,
            @ResolvedMappingReceiptId = d.ReceiptId,
            @ResolvedBillPaymentNo = COALESCE(NULLIF(@BillPaymentNo, ''), d.StatementNo),
            @ResolvedLGNo = COALESCE(NULLIF(@LGNo, ''), d.LGNo),
            @ResolvedReceiptAmount = CASE WHEN @ReceiptAmount = 0 THEN d.Amount ELSE @ReceiptAmount END,
            @ResolvedReceiptDate = COALESCE(@ReceiptDate, d.PaymentDate),
            @ResolvedBankCode = COALESCE(NULLIF(@BankCode, ''), d.BankCode)
        FROM [dbo].[DataEStatement] d
        WHERE NULLIF(LTRIM(RTRIM(@MappingReceiptId)), '') IS NOT NULL
          AND d.ReceiptId = @MappingReceiptId
          AND ISNULL(d.IsDelete, 0) = 0
        ORDER BY d.UpdateDate DESC, d.CreateDate DESC;
    END;

    -- Fallback for callers that send only ReceiptNo: match the same receipt,
    -- amount and payment date in DataEStatement.
    IF @EStatementId IS NULL
    BEGIN
        SELECT TOP (1)
            @EStatementId = d.EStatementId,
            @ResolvedMappingReceiptId = d.ReceiptId,
            @ResolvedBillPaymentNo = COALESCE(NULLIF(@BillPaymentNo, ''), d.StatementNo),
            @ResolvedLGNo = COALESCE(NULLIF(@LGNo, ''), d.LGNo),
            @ResolvedReceiptAmount = CASE WHEN @ReceiptAmount = 0 THEN d.Amount ELSE @ReceiptAmount END,
            @ResolvedReceiptDate = COALESCE(@ReceiptDate, d.PaymentDate),
            @ResolvedBankCode = COALESCE(NULLIF(@BankCode, ''), d.BankCode)
        FROM [dbo].[DataEStatement] d
        WHERE d.ReceiptNo = @ReceiptNo
          AND (@ReceiptAmount = 0 OR d.Amount = @ReceiptAmount)
          AND (@ReceiptDate IS NULL
               OR CAST(d.PaymentDate AS date) = CAST(@ReceiptDate AS date))
          AND ISNULL(d.IsDelete, 0) = 0
        ORDER BY
            CASE WHEN d.StatusEStatement = 1 THEN 0 ELSE 1 END,
            d.UpdateDate DESC,
            d.CreateDate DESC;
    END;

    -- This endpoint is specifically the E-Statement receipt return leg.
    -- Do not silently create an unlinked output row when its source statement
    -- cannot be found; surface the data/mapping problem to the caller.
    IF @EStatementId IS NULL
        THROW 50002, 'Cannot resolve EStatementId for the supplied ReceiptNo.', 1;

    SET @ResolvedMappingReceiptId =
        COALESCE(@ResolvedMappingReceiptId,
                 NULLIF(LTRIM(RTRIM(@MappingReceiptId)), ''));

    SET @ResolvedBillPaymentNo = COALESCE(@ResolvedBillPaymentNo, @BillPaymentNo);
    SET @ResolvedLGNo = COALESCE(@ResolvedLGNo, @LGNo);
    SET @ResolvedBankCode = COALESCE(@ResolvedBankCode, @BankCode);

    BEGIN TRAN;

    -- Idempotent retry: update the existing receipt row (including the old
    -- unlinked row) instead of inserting another duplicate.
    ;WITH ExistingReceipt AS
    (
        SELECT TOP (1) *
        FROM [dbo].[Output_eStatementReceipt]
        WHERE ReceiptNo = @ReceiptNo
          AND ISNULL([Status], '1') <> '2'
          AND (NULLIF(LTRIM(RTRIM(ISNULL(StatusES, ''))), '') IS NULL
               OR StatusES = @ResolvedStatusES)
          AND (NULLIF(LTRIM(RTRIM(ISNULL(TransStatus, ''))), '') IS NULL
               OR TransStatus = @ResolvedTransStatus)
        ORDER BY UpdateDate DESC, CreateDate DESC
    )
    UPDATE ExistingReceipt
    SET MappingReceiptId = @ResolvedMappingReceiptId,
        BillPaymentNo = @ResolvedBillPaymentNo,
        [No] = '',
        ReceiptNo = @ReceiptNo,
        RequestNo = @RequestNo,
        LGNo = @ResolvedLGNo,
        ReceiptAmount = @ResolvedReceiptAmount,
        ReceiptDate = @ResolvedReceiptDate,
        ReceiptType = @ResolvedReceiptType,
        StatusReceipt = @ResolvedStatusReceipt,
        CheckDate = DATEADD(YEAR, 543, @ResolvedReceiptDate),
        PaymentDes2 = DATEADD(YEAR, 543, @ResolvedReceiptDate),
        StatusES = @ResolvedStatusES,
        CreateUser = @CreateUser,
        BankCode = @ResolvedBankCode,
        TanReceiptNo = @TanReceiptNo,
        [Status] = '1',
        TransStatus = @ResolvedTransStatus,
        UpdateDate = ISNULL(@UpdateDate, GETDATE()),
        IsUpdateCard = 0,
        InformPaymentNo = '',
        EStatementId = @EStatementId;

    IF @@ROWCOUNT = 0
    BEGIN
        INSERT INTO [dbo].[Output_eStatementReceipt]
        (
            eStatementReceiptId,
            MappingReceiptId,
            BillPaymentNo,
            No,
            ReceiptNo,
            RequestNo,
            LGNo,
            ReceiptAmount,
            ReceiptDate,
            ReceiptType,
            StatusReceipt,
            CheckDate,
            PaymentDes2,
            StatusES,
            CreateUser,
            Type1,
            Type2,
            BankCode,
            TanReceiptNo,
            Status,
            TransStatus,
            CreateDate,
            UpdateDate,
            IsUpdateCard,
            InformPaymentNo,
            EStatementId
        )
        VALUES
        (
            NEWID(),
            @ResolvedMappingReceiptId,
            @ResolvedBillPaymentNo,
            '',
            @ReceiptNo,
            @RequestNo,
            @ResolvedLGNo,
            @ResolvedReceiptAmount,
            @ResolvedReceiptDate,
            @ResolvedReceiptType,
            @ResolvedStatusReceipt,
            DATEADD(YEAR, 543, @ResolvedReceiptDate),
            DATEADD(YEAR, 543, @ResolvedReceiptDate),
            @ResolvedStatusES,
            @CreateUser,
            '',
            '',
            @ResolvedBankCode,
            @TanReceiptNo,
            '1',
            @ResolvedTransStatus,
            ISNULL(@CreateDate, GETDATE()),
            ISNULL(@UpdateDate, GETDATE()),
            0,
            '',
            @EStatementId
        );
    END;

    COMMIT;
END

CREATE   PROCEDURE dbo.SP_ACC_008_AssignRequestAdjustRoundRobin
(
    @DryRun BIT = 0
    -- 0 = จ่ายงานจริง
    -- 1 = ทดลองดูผู้ที่จะได้รับงาน โดยไม่ Update
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @LockResult      INT,
        @NextPos         INT,
        @NextPosAfter    INT,
        @UserCount       INT,
        @AssignedCount   INT = 0,
        @AssignedUserId  INT,
        @CurrentDate     DATETIME = GETDATE();

    BEGIN TRY
        BEGIN TRAN;

        /* =========================================================
           A) ป้องกันการรันซ้อนกัน
           ========================================================= */
        EXEC @LockResult = sys.sp_getapplock
             @Resource    = N'ACC_Request_Adjust_Round_Robin',
             @LockMode    = N'Exclusive',
             @LockOwner   = N'Transaction',
             @LockTimeout = 30000,
             @DbPrincipal = N'public';

        IF @LockResult < 0
        BEGIN
            THROW 50001,
                  N'ไม่สามารถล็อกการจ่ายงานบัญชีได้ เนื่องจากมีกระบวนการอื่นกำลังทำงานอยู่',
                  1;
        END;


        /* =========================================================
           B) เพิ่มเจ้าหน้าที่ใหม่เข้าตาราง Round Robin

           เงื่อนไข:
           OrgStructureId = 37
           OrgSectionId   = 44
           IsActive       = 1
           ========================================================= */
        ;WITH EligibleUser AS
        (
            SELECT DISTINCT
                dpi.UserId
            FROM dbo.DataPersonalInfo dpi WITH (READCOMMITTED)
            WHERE dpi.UserId IS NOT NULL
              AND dpi.UserId <> 0
              AND dpi.OrgStructureId = 37
              AND dpi.OrgSectionId = 44
              AND dpi.IsActive = 1
        ),
        MissingUser AS
        (
            SELECT
                eu.UserId
            FROM EligibleUser eu
            LEFT JOIN dbo.ACC_AccountAdjustRRUser rr
                   ON rr.UserId = eu.UserId
            WHERE rr.UserId IS NULL
        ),
        NewUserSeq AS
        (
            SELECT
                mu.UserId,
                ROW_NUMBER() OVER
                (
                    ORDER BY mu.UserId
                ) AS RowNo
            FROM MissingUser mu
        )
        INSERT INTO dbo.ACC_AccountAdjustRRUser
        (
            UserId,
            UserPos,
            IsActive,
            UpdateDate
        )
        SELECT
            nus.UserId,
            ISNULL
            (
                (
                    SELECT MAX(rr.UserPos)
                    FROM dbo.ACC_AccountAdjustRRUser rr
                ),
                0
            ) + nus.RowNo,
            1,
            @CurrentDate
        FROM NewUserSeq nus;


        /* =========================================================
           C) ปิดเจ้าหน้าที่ที่ไม่เข้าเงื่อนไขแล้ว
           ========================================================= */
        ;WITH EligibleUser AS
        (
            SELECT DISTINCT
                dpi.UserId
            FROM dbo.DataPersonalInfo dpi WITH (READCOMMITTED)
            WHERE dpi.UserId IS NOT NULL
              AND dpi.UserId <> 0
              AND dpi.OrgStructureId = 37
              AND dpi.OrgSectionId = 44
              AND dpi.IsActive = 1
        )
        UPDATE rr
           SET rr.IsActive   = 0,
               rr.UpdateDate = @CurrentDate
        FROM dbo.ACC_AccountAdjustRRUser rr
        LEFT JOIN EligibleUser eu
               ON eu.UserId = rr.UserId
        WHERE rr.IsActive = 1
          AND eu.UserId IS NULL;


        /* =========================================================
           D) เปิดเจ้าหน้าที่กลับ หากกลับมาเข้าเงื่อนไข
           ========================================================= */
        ;WITH EligibleUser AS
        (
            SELECT DISTINCT
                dpi.UserId
            FROM dbo.DataPersonalInfo dpi WITH (READCOMMITTED)
            WHERE dpi.UserId IS NOT NULL
              AND dpi.UserId <> 0
              AND dpi.OrgStructureId = 37
              AND dpi.OrgSectionId = 44
              AND dpi.IsActive = 1
        )
        UPDATE rr
           SET rr.IsActive   = 1,
               rr.UpdateDate = @CurrentDate
        FROM dbo.ACC_AccountAdjustRRUser rr
        INNER JOIN EligibleUser eu
                ON eu.UserId = rr.UserId
        WHERE rr.IsActive = 0;


        /* =========================================================
           E) สร้างสถานะเริ่มต้น
           ========================================================= */
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.ACC_AccountAdjustRRState WITH (UPDLOCK, HOLDLOCK)
            WHERE StateKey = N'ACCOUNT_ADJUST'
        )
        BEGIN
            INSERT INTO dbo.ACC_AccountAdjustRRState
            (
                StateKey,
                NextUserPos,
                UpdateDate
            )
            VALUES
            (
                N'ACCOUNT_ADJUST',
                1,
                @CurrentDate
            );
        END;


        /* =========================================================
           F) สร้างรายชื่อเจ้าหน้าที่ที่พร้อมรับงาน
           ========================================================= */
        IF OBJECT_ID(N'tempdb..#ActiveUser', N'U') IS NOT NULL
            DROP TABLE #ActiveUser;

        SELECT
            rr.UserId,
            rr.UserPos,
            ROW_NUMBER() OVER
            (
                ORDER BY rr.UserPos, rr.UserId
            ) AS ActiveSeq
        INTO #ActiveUser
        FROM dbo.ACC_AccountAdjustRRUser rr WITH (READCOMMITTED)
        INNER JOIN dbo.DataPersonalInfo dpi WITH (READCOMMITTED)
                ON dpi.UserId = rr.UserId
        WHERE rr.IsActive = 1
          AND dpi.OrgStructureId = 37
          AND dpi.OrgSectionId = 44
          AND dpi.IsActive = 1;


        SELECT
            @UserCount = COUNT(*)
        FROM #ActiveUser;

        IF ISNULL(@UserCount, 0) = 0
        BEGIN
            THROW 50002,
                  N'ไม่พบเจ้าหน้าที่บัญชีที่เข้าเงื่อนไข OrgStructureId = 37 และ OrgSectionId = 44',
                  1;
        END;


        /* =========================================================
           G) อ่านลำดับเจ้าหน้าที่คนถัดไป
           ========================================================= */
        SELECT
            @NextPos = NextUserPos
        FROM dbo.ACC_AccountAdjustRRState WITH (UPDLOCK, HOLDLOCK)
        WHERE StateKey = N'ACCOUNT_ADJUST';

        IF @NextPos IS NULL OR @NextPos < 1
            SET @NextPos = 1;

        SET @NextPos = ((@NextPos - 1) % @UserCount) + 1;


        SELECT
            @AssignedUserId = au.UserId
        FROM #ActiveUser au
        WHERE au.ActiveSeq = @NextPos;


        /* =========================================================
           H) ตรวจสอบว่ามีงานที่ AccountUserId เป็น NULL หรือ 0
           ========================================================= */
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.ACCDataRequestAdjust a WITH (READPAST)
            WHERE a.AccountUserId IS NULL
               OR a.AccountUserId = 0
        )
        BEGIN
            SELECT
                CAST(0 AS INT) AS TotalQueued,
                CAST(0 AS INT) AS Assigned,
                @DryRun AS IsDryRun,
                @NextPos AS NextUserPos_Before,
                @NextPos AS NextUserPos_After,
                CAST(NULL AS INT) AS AccountUserId;

            COMMIT;
            RETURN;
        END;


        /* =========================================================
           I) จ่ายงานครั้งละ 1 รายการ
           ========================================================= */
        IF @DryRun = 0
        BEGIN
            ;WITH Pending AS
            (
                SELECT TOP (1)
                    a.AccountUserId
                FROM dbo.ACCDataRequestAdjust a
                     WITH (UPDLOCK, READPAST, ROWLOCK)
                WHERE a.AccountUserId IS NULL
                   OR a.AccountUserId = 0
                ORDER BY
                    ISNULL
                    (
                        a.CreateDate,
                        CONVERT(DATETIME, '19000101', 112)
                    )
            )
            UPDATE Pending
               SET AccountUserId = @AssignedUserId;

            SET @AssignedCount = @@ROWCOUNT;
        END
        ELSE
        BEGIN
            SET @AssignedCount = 1;
        END;


        /* =========================================================
           J) ขยับไปยังเจ้าหน้าที่คนถัดไป
           ========================================================= */
        SET @NextPosAfter =
            ((@NextPos - 1 + @AssignedCount) % @UserCount) + 1;

        IF @DryRun = 0
           AND @AssignedCount > 0
        BEGIN
            UPDATE dbo.ACC_AccountAdjustRRState
               SET NextUserPos = @NextPosAfter,
                   UpdateDate  = @CurrentDate
            WHERE StateKey = N'ACCOUNT_ADJUST';
        END;


        /* =========================================================
           K) แสดงผล
           ========================================================= */
        SELECT
            CAST(1 AS INT) AS TotalQueued,
            @AssignedCount AS Assigned,
            @DryRun AS IsDryRun,
            @NextPos AS NextUserPos_Before,
            @NextPosAfter AS NextUserPos_After,
            @AssignedUserId AS AccountUserId;

        COMMIT;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK;

        DECLARE @ErrorMessage NVARCHAR(2048);

        SET @ErrorMessage =
            N'SP_ACC_008_AssignRequestAdjustRoundRobin failed: '
            + ERROR_MESSAGE();

        THROW 50003, @ErrorMessage, 1;
    END CATCH;
END

