    -- 1 = คนเรียกจะจัดการ transaction เอง (เช่น เรียกผ่าน INSERT...EXEC)
    @CallerHandlesTxn BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
