        @AccountUserSign NVARCHAR(400) = N'',
        @ReceiptId NVARCHAR(150),
        @ReceiptNo NVARCHAR(100),
        @BarcodeNo NVARCHAR(100),
        @Reference1 NVARCHAR(20),
        @Reference2 NVARCHAR(20),
