        @Moo NVARCHAR(20),
        @Soi NVARCHAR(20),
        @Road NVARCHAR(20),
        @ProvinceId int,
        @SubDistrictId int,
        @DistrictId int,
        @PostalCode NVARCHAR(20)
		
		
		
		;

    -- เตรียมข้อมูลประกอบ
    SELECT @Reference1 = Reference1, @Reference2 = Reference2
    FROM dbo.DataEStatement
    WHERE EStatementId = @EStatementId;
		
-- 		declare @DebtorId NVARCHAR(20) = SELECT DebtorId from DataDebtorCard where DataDebtorCardId = @DebtorCardId

		
		

    SELECT
