	SELECT top 1 @DebtorCardMovementId = DebtorCardMovementId
    FROM dbo.DataDebtorCardMovement
    WHERE DebtorCardId = @DebtorCardId
	and TypeId = 2
	and SeqNo = @SeqCurrent
	order by SeqNo desc;

    IF @ReceiptDate IS NULL SET @ReceiptDate = GETDATE();

    BEGIN TRY
        -- ถ้าคนเรียกไม่ได้บอกว่าจะจัดการ txn เอง เราจัดการให้
        IF (@CallerHandlesTxn = 0 AND @@TRANCOUNT = 0)
        BEGIN
            BEGIN TRAN;
            SET @StartedTran = 1;
        END

        ------------------------------------------------------------
        -- (A) ขอเลขใบเสร็จ
        ------------------------------------------------------------
        DECLARE @NextReceiptNo NVARCHAR(100);

        EXEC dbo.SP_DCS_040_ReserveReceiptNo
             @SystemId          = @SystemId,
             @DocumentId        = @DocumentId,
             @UserId            = @CreateBy,
             @NextReceiptNo     = @NextReceiptNo OUTPUT,
             @CallerHandlesTxn  = @CallerHandlesTxn;     -- ส่งแฟลกต่อไป

        SET @ReceiptNo = @NextReceiptNo;

        ------------------------------------------------------------
        -- (B) ขอ Barcode
        -- (ตัว SP_DCS_041_ReserveBarcodeNo เราแก้ให้ begin/commit เองแล้วถ้าไม่มี txn)
        ------------------------------------------------------------
        EXEC dbo.SP_DCS_041_ReserveBarcodeNo
             @SystemId   = @SystemId,
             @DocumentId = @DocumentId,
             @UserId     = @CreateBy,
             @BarcodeNo  = @BarcodeNo OUTPUT;

        ------------------------------------------------------------
        -- (C) ดึงข้อมูล DebtorCard
        ------------------------------------------------------------
        DECLARE
            @IDCard NVARCHAR(30),
            @LGNo NVARCHAR(20),
            @DebtorId NVARCHAR(150),
            @DebtorCode NVARCHAR(50),
            @DebtorRelateId NVARCHAR(150),
            @AddressDebtor NVARCHAR(MAX),
            @MeasureId INT,
            @DebtBalance decimal(20,2),
            @PrincipalTotal decimal(20,2),
						@ContactNo NVARCHAR(150);

        SELECT TOP 1
            @IDCard        = d.IDCard,
            @LGNo          = cd.LGNo,
            @DebtorId      = cd.DebtorId,
            @DebtorCode    = cd.DebtorCode,
            @DebtorRelateId= cd.DebtorRelateId,
            @AddressDebtor = dbo.[FN_DCS_12_GetDebtorAddress](cd.DebtorId, 2),
            @MeasureId     = cd.MeasureId,
			@DebtBalance   = cd.DebtBalance,
			@PrincipalTotal  = cd.PrincipalTotal,
			@AccruedInterestTotal = cd.AccruedInterestTotal,
			@SuspendIntTotal = cd.SuspendIntTotal,
			@ContactNo = cd.RequestNoTDR
        FROM dbo.DataDebtorCard cd
        LEFT JOIN dbo.DataDebtor d ON d.DebtorId = cd.DebtorId
        WHERE cd.DataDebtorCardId = @DebtorCardId;

        ------------------------------------------------------------
        -- (D) Insert ใบเสร็จ
        ------------------------------------------------------------
        SET @ReceiptId = CONVERT(NVARCHAR(150), NEWID());
				
						select top 1 @AddressNumber =  a.AddressNumber
		,  @PlaceName = a.PlaceName
     ,   @Moo = Moo
     ,   @Soi = Soi
      ,  @Road = Road
      ,  @ProvinceId = ProvinceId
      ,  @SubDistrictId = SubDistrictId
       , @DistrictId = DistrictId
      ,  @PostalCode = PostalCode
		from DataDebtorAddress a
		where a.DebtorId = @DebtorId
		and a.DebtorAddressTypeId = 1

        INSERT INTO dbo.ACCDataReceipt
        (
            ReceiptId, ReceiptNo, ReceiptDate, URL, PeriodMonth, PaymentAmount, IsPrint,
            AccountUserId, PaymentTypeId, AddressDebtor, DueDate,
            CreateDate, CreateBy, UpdateDate, UpdateBy, DataBillPaymentId,
            PrincipalPay, AccruedInterestPay, IDCard, LGNo, DebtorId, DebtorCode, DebtorCardId,
            ReceiptNoOld, DebtorRelateId, BarcodeNo, PathBarcode, IsGenBarcode,
            DebtBalance, PrincipalTotal, AccruedInterestTotal,
            CourtFeePay, LawyerFeePay, OtherExpensePay, InitialMarginPay, IsCancel,
            AccountUser, AccountUserSign, DebtorPaymentName,
            CourtFeeTotal, LawyerFeeTotal, OtherExpenseTotal, InitialMarginTotal,
            SuspendIntTotal, DeferredInterestTotal, SuspendedDefaultInterestTotal,
            PlannedInterestTotal, DefaultInterestTotal, eStatementId,
-- 						OverdueAmount
-- , SectionName
-- , CollectorUserId
AddressNumber
, PlaceName
, Moo
, Soi
, Road
, ProvinceId
, SubDistrictId
, DistrictId
, PostalCode
, ContactNo
, MeasureId
-- , DescriptionName
-- , PeriodYear
-- , DefaultInterestPay
-- , InstallmentAmount

        )
        SELECT
            @ReceiptId,
            @ReceiptNo,
            @ReceiptDate,
            N'',
            N'',
            @PaymentAmount as PaymentAmount,
            0 as IsPrint,
            @AccountUserId as AccountUserId,
            NULL as PaymentTypeId,
            @AddressDebtor as AddressDebtor,
            NULL as DueDate,
            GETDATE() as CreateDate,
            @CreateBy as CreateBy,
            GETDATE() as UpdateDate,
            @CreateBy as UpdateBy,
            N'' as DataBillPaymentId,
            @PrincipalPay as PrincipalPay,
            @AccruedInterestPay as AccruedInterestPay,
            @IDCard as IDCard,
            @LGNo as LGNo,
            @DebtorId as DebtorId,
            @DebtorCode as DebtorCode,
            @DebtorCardId as DebtorCardId,
            N'' as ReceiptNoOld,
            @DebtorRelateId as DebtorRelateId,
            @BarcodeNo as BarcodeNo,
            NULL as PathBarcode,
            0 as IsGenBarcode, 
            @DebtBalance as DebtBalance,
            @PrincipalTotal as PrincipalTotal,
            @AccruedInterestTotal as AccruedInterestTotal,
            @CourtFeePay,
            @LawyerFeePay,
            @OtherExpensePay,
            @InitialMarginPay,
            0 as IsCancel,
            @AccountUser,
            @AccountUserSign,
            @DebtorPaymentName,
            @CourtFeeTotal,
            @LawyerFeeTotal,
            @OtherExpenseTotal,
            @InitialMarginTotal,
            @SuspendIntTotal,
            @DeferredInterestTotal,
            @SuspendedDefaultInterestTotal,
            @PlannedInterestTotal,
            @DefaultInterestTotal,
			@EStatementId,
-- 			SectionName
-- , CollectorUserId
 @AddressNumber
, @PlaceName
, @Moo
, @Soi
, @Road
, @ProvinceId
, @SubDistrictId
, @DistrictId
, @PostalCode
, @ContactNo
, @MeasureId
-- , DescriptionName
-- , PeriodYear
-- , DefaultInterestPay
-- , InstallmentAmount
-- 
			  --อัปเดตเลขใบเสร็จ ในการ์ด
		UPDATE dbo.DataDebtorCardMovement
		set ReceiptId = @ReceiptId
		, ReceiptNo = @ReceiptNo
		where DebtorCardMovementId = @DebtorCardMovementId;

        ------------------------------------------------------------
        -- (E) อัพเดตเลขเอกสารล่าสุด
        ------------------------------------------------------------
        UPDATE dbo.SystemFormatDocumentMaster
           SET UpdateRunning = @ReceiptNo,
               UpdateDate    = GETDATE(),
               UpdateBy      = @CreateBy
        WHERE SystemId  = @SystemId
          AND DocumentId = @DocumentId;

		

        ------------------------------------------------------------
        -- (F) Insert Receive
        ------------------------------------------------------------
        INSERT INTO dbo.DataDebtorCardReceive
        (
            DebtorCardReceiveId, DataDebtorCardId, Reference1, Reference2, PayDate,
            TotalPay, MeasureId, CreateDate, CreateBy, UpdateDate, UpdateBy, EStatementId, ReceiptNo
        )
        SELECT
            NEWID(),
            @DebtorCardId,
            @Reference1,
            @Reference2,
            @ReceiptDate,
            @PaymentAmount,
            @MeasureId,
            GETDATE(),
            @CreateBy,
            GETDATE(),
            @CreateBy,
            @EStatementId,
            @ReceiptNo;

        ------------------------------------------------------------
        -- (G) ส่งใบเสร็จกลับไปยัง E-Statement
        --
        -- SP_DCS_039 เป็นจุดที่ได้ ReceiptNo จริงแล้ว แต่เดิมไม่ได้เรียก
        -- SP_ACC_003 ทำให้ Output_eStatementReceipt ไม่ถูกสร้างอัตโนมัติ
        -- สำหรับ receipt ที่ผูกกับ DataEStatement เท่านั้น
        ------------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.DataEStatement
            WHERE EStatementId = @EStatementId
              AND ISNULL(IsDelete, 0) = 0
        )
        BEGIN
            DECLARE @EStatementMappingReceiptId NVARCHAR(150);
            DECLARE @EStatementCreateUser NVARCHAR(150);

            SELECT TOP (1)
                @EStatementMappingReceiptId = NULLIF(LTRIM(RTRIM(ReceiptId)), '')
            FROM dbo.DataEStatement
            WHERE EStatementId = @EStatementId
              AND ISNULL(IsDelete, 0) = 0;

            SET @EStatementMappingReceiptId = COALESCE(@EStatementMappingReceiptId, @ReceiptId);
            SET @EStatementCreateUser = CONVERT(NVARCHAR(150), @CreateBy);

            EXEC dbo.SP_ACC_003_eStatementReceipt
                 @MappingReceiptId = @EStatementMappingReceiptId,
                 @BillPaymentNo    = N'',
                 @ReceiptNo        = @ReceiptNo,
                 @RequestNo        = N'',
                 @LGNo             = @LGNo,
                 @ReceiptAmount    = @PaymentAmount,
                 @ReceiptDate      = @ReceiptDate,
                 @ReceiptType      = N'',
                 @StatusReceipt    = N'1',
                 @PaymentDes2      = N'',
                 @CreateUser       = @EStatementCreateUser,
                 @BankCode         = N'',
                 @TanReceiptNo     = N'',
                 @StatusES         = N'1',
                 @TransStatus      = N'01',
                 @CreateDate       = NULL,
                 @UpdateDate       = NULL,
                 @InputEStatementId = @EStatementId;
        END;

		
        -- ถ้าเราเป็นคนเริ่ม txn เองให้ commit เอง
        IF (@StartedTran = 1 AND @@TRANCOUNT > 0)
            COMMIT;

        -- ให้ผลลัพธ์ออกไปเพื่อรองรับ INSERT ... EXEC
      --  SELECT @ReceiptId AS ReceiptId,
      --         @ReceiptNo AS ReceiptNo,
      --         @BarcodeNo AS BarcodeNo,
			   --@DebtorCardMovementId as DebtorCardMovementId,
			   --@SeqCurrent as SeqCurrent;

		

    END TRY
    BEGIN CATCH
        -- rollback เฉพาะที่เราเริ่มเอง
        IF (@CallerHandlesTxn = 0 AND @StartedTran = 1 AND XACT_STATE() <> 0)
            ROLLBACK;

        -- ส่ง error กลับ
        DECLARE
            @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE(),
            @ErrNum INT = ERROR_NUMBER(),
            @ErrState INT = ERROR_STATE();

        RAISERROR(
            N'Error in SP_DCS_039_InsertReceipt (%d): %s',
            16,
            1,
            @ErrNum,
            @ErrMsg
        );
        RETURN;
    END CATCH
END

CREATE PROCEDURE [dbo].[SP_DCS_040_ReserveReceiptNo]
    @SystemId INT,
    @DocumentId INT,
    @UserId INT = NULL,
    @NextReceiptNo NVARCHAR(100) OUTPUT,       -- เพิ่ม OUTPUT parameter
    @CallerHandlesTxn BIT = 0                  -- ถ้าคนเรียกควบคุม Transaction เอง (เช่น ถูกเรียกผ่าน SP_DCS_039)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
         @Now DATETIME2 = SYSDATETIME(),
         @YearAD INT,
         @MonthInt INT,
         @CurYearStr NVARCHAR(10),
         @CurMonthStr NVARCHAR(2),
         @RowYear NVARCHAR(10),
         @RowMonth NVARCHAR(10),
         @Running NVARCHAR(50),
         @DocumentName NVARCHAR(50),
         @LastInt INT,
         @NewInt INT,
         @Run6 NVARCHAR(6),
         @YY NVARCHAR(2),
         @StartedTran BIT = 0;

    SET @YearAD = YEAR(@Now);
    SET @MonthInt = MONTH(@Now);
    SET @CurYearStr = CONVERT(NVARCHAR(10), @YearAD);      -- เก็บปี ค.ศ.
    SET @CurMonthStr = RIGHT('00' + CAST(@MonthInt AS VARCHAR(2)), 2);
    SET @YY = RIGHT(CONVERT(VARCHAR(4), @YearAD + 543), 2); -- พ.ศ. 2 หลัก

    BEGIN TRY
        -- ✅ เริ่ม Transaction เฉพาะกรณีที่ Caller ไม่ได้ควบคุมเอง
        IF (@CallerHandlesTxn = 0)
        BEGIN
            BEGIN TRAN;
            SET @StartedTran = 1;
        END

        -- 1) สร้างแถวถ้ายังไม่มี
        IF NOT EXISTS (
            SELECT 1
            FROM dbo.SystemFormatDocumentMaster WITH (UPDLOCK, HOLDLOCK)
            WHERE SystemId = @SystemId AND DocumentId = @DocumentId
        )
        BEGIN
            INSERT INTO dbo.SystemFormatDocumentMaster
            (
                 SystemId,
                 DocumentId,
                 SystemName,
                 SystemDCS,
                 DocumentName,
                 Year,
                 Months,
                 Running,
                 CreateDate,
                 CreateBy,
                 UpdateDate,
                 UpdateBy,
                 UpdateRunning
            )
            VALUES
            (
                 @SystemId,
                 @DocumentId,
                 NULL,
                 NULL,
                 NULL,
                 @CurYearStr,
                 @CurMonthStr,
                 N'000000',
                 @Now,
                 @UserId,
                 @Now,
                 @UserId,
                 NULL
            );
        END

        -- 2) โหลดค่าปัจจุบัน (อิง Running)
        SELECT TOP (1)
             @RowYear = ISNULL(Year, N''),
             @RowMonth = ISNULL(Months, N''),
             @Running = ISNULL(Running, N'000000'),
             @DocumentName = ISNULL(DocumentName, N'')
        FROM dbo.SystemFormatDocumentMaster WITH (UPDLOCK, HOLDLOCK)
        WHERE SystemId = @SystemId AND DocumentId = @DocumentId;

        -- 3) ถ้าเปลี่ยนปี/เดือน ให้รีเซ็ต Running
        IF (@RowYear <> @CurYearStr OR @RowMonth <> @CurMonthStr)
        BEGIN
            UPDATE dbo.SystemFormatDocumentMaster
            SET Year = @CurYearStr,
                Months = @CurMonthStr,
                Running = N'000000',
                UpdateDate = @Now,
                UpdateBy = @UserId
            WHERE SystemId = @SystemId AND DocumentId = @DocumentId;

            SET @Running = N'000000';
        END

        -- 4) คำนวณรันใหม่
        SET @LastInt = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@Running)), N''));
        IF @LastInt IS NULL SET @LastInt = 0;

        SET @NewInt = @LastInt + 1;
        SET @Run6 = RIGHT('000000' + CAST(@NewInt AS VARCHAR(20)), 6);

        -- 5) ประกอบเลขเต็ม
        SET @NextReceiptNo = ISNULL(@DocumentName, N'') + @YY + @CurMonthStr + @Run6;

        -- 6) อัปเดต Running กลับ
        UPDATE dbo.SystemFormatDocumentMaster
        SET Running = @Run6,
            UpdateDate = @Now,
            UpdateBy = @UserId,
            Year = @CurYearStr,
            Months = @CurMonthStr,
            UpdateRunning = @NextReceiptNo
        WHERE SystemId = @SystemId AND DocumentId = @DocumentId;

        -- ✅ ปิด Transaction ถ้าเราเป็นผู้เริ่มเอง
        IF (@StartedTran = 1) COMMIT;
    END TRY
    BEGIN CATCH
        -- ✅ Rollback เฉพาะถ้าเราเริ่มเอง
        IF (@CallerHandlesTxn = 0 AND XACT_STATE() <> 0 AND @StartedTran = 1)
            ROLLBACK;

        THROW;
    END CATCH
END

CREATE PROCEDURE [dbo].[SP_DCS_041_ReserveBarcodeNo]
    @SystemId INT=1,
    @DocumentId INT=1,
    @UserId INT = NULL,
    @BarcodeNo NVARCHAR(100) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    -- อย่า SET XACT_ABORT ON ถ้าจะรองรับ INSERT...EXEC + TRY/CATCH แบบนี้

    DECLARE
         @Now DATETIME2 = SYSDATETIME()
        ,@YearAD INT
        ,@MonthInt INT
        ,@CurYearStr NVARCHAR(10)
        ,@CurMonthStr NVARCHAR(2)
        ,@RowYear NVARCHAR(10)
        ,@RowMonth NVARCHAR(10)
        ,@Running NVARCHAR(50)
        ,@DocumentCode NVARCHAR(50)
        ,@LastInt INT
        ,@NewInt INT
        ,@Run6 NVARCHAR(6)
        ,@YY NVARCHAR(2)
        ,@StartedTran BIT = 0;

    SET @YearAD = YEAR(@Now);
    SET @MonthInt = MONTH(@Now);
    SET @CurYearStr = CONVERT(NVARCHAR(10), @YearAD);
    SET @CurMonthStr = RIGHT('00' + CAST(@MonthInt AS VARCHAR(2)), 2);
    SET @YY = RIGHT(CONVERT(VARCHAR(4), @YearAD + 543), 2);

    BEGIN TRY
        -- ถ้ายังไม่มีทรานแซกชัน ให้เราเริ่มเอง
        IF @@TRANCOUNT = 0
        BEGIN
            SET @StartedTran = 1;
            BEGIN TRAN;
        END

        -- ต้องมีแถวอยู่ก่อน
        IF NOT EXISTS (
            SELECT 1
            FROM dbo.SystemFormatBarcodeMaster WITH (UPDLOCK, HOLDLOCK)
            WHERE SystemId = @SystemId AND DocumentId = @DocumentId
        )
        BEGIN
            ;THROW 51011, 'SystemFormatBarcodeMaster: row not found for this SystemId/DocumentId.', 1;
        END

        -- ล็อกแถวแล้วอ่าน
        SELECT TOP (1)
             @RowYear     = ISNULL([Year], N'')
            ,@RowMonth    = ISNULL([Months], N'')
            ,@Running     = ISNULL([Running], N'000000')
            ,@DocumentCode= ISNULL([DocumentCode], N'')
        FROM dbo.SystemFormatBarcodeMaster WITH (UPDLOCK, HOLDLOCK)
        WHERE SystemId = @SystemId AND DocumentId = @DocumentId;

        -- ถ้าปี/เดือนเปลี่ยนให้รีเซ็ต
        IF (@RowYear <> @CurYearStr OR @RowMonth <> @CurMonthStr)
        BEGIN
            UPDATE dbo.SystemFormatBarcodeMaster
            SET [Year]     = @CurYearStr,
                [Months]   = @CurMonthStr,
                [Running]  = N'000000',
                UpdateDate = @Now,
                UpdateBy   = @UserId
            WHERE SystemId = @SystemId AND DocumentId = @DocumentId;

            SET @Running = N'000000';
        END

        -- คำนวณ running
        SET @LastInt = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@Running)), N''));
        IF @LastInt IS NULL SET @LastInt = 0;

        SET @NewInt = @LastInt + 1;
        SET @Run6 = RIGHT('000000' + CAST(@NewInt AS VARCHAR(20)), 6);

        -- ประกอบบาร์โค้ด
        SET @BarcodeNo = @DocumentCode + @YY + @CurMonthStr + @Run6;

        -- อัปเดต running กลับ
        UPDATE dbo.SystemFormatBarcodeMaster
        SET [Running]  = @Run6,
            UpdateDate = @Now,
            UpdateBy   = @UserId,
            [Year]     = @CurYearStr,
            [Months]   = @CurMonthStr
        WHERE SystemId = @SystemId AND DocumentId = @DocumentId;

        -- ถ้าเราเป็นคนเริ่มเอง ให้คอมมิตเอง
        IF @StartedTran = 1 AND @@TRANCOUNT > 0
            COMMIT;

        -- ส่งออกเพื่อให้ SELECT ... INSERT ได้
        --SELECT @BarcodeNo AS NextBarcodeNo;
    END TRY
    BEGIN CATCH
        -- ถ้าเราเริ่มทรานแซกชันเองเท่านั้น ค่อย rollback
        IF @StartedTran = 1 AND XACT_STATE() <> 0
            ROLLBACK;

        DECLARE
            @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE(),
            @ErrNum INT = ERROR_NUMBER(),
            @ErrState INT = ERROR_STATE();

        RAISERROR(
            N'Error in SP_DCS_041_ReserveBarcodeNo (%d): %s',
            16,
            1,
            @ErrNum,
            @ErrMsg
        );
        RETURN;
    END CATCH
END

-- Optimized: daily interest calculation, one movement update and one card update.
-- Existing unused parameters retained for caller compatibility.
CREATE PROCEDURE [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal]
    @CurrentDate DATETIME = '2026-05-31',
    @DataDebtorCardId NVARCHAR(150) = '053143CD-8393-4ACB-9F19-60BF9288A546',
    @IsAdjust INT = 0,
    @AdjustDate DATE = '2025-12-01'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @SeqCurrent INT = 0,
        @InterestPlannedRate DECIMAL(20,2) = 0,
        @InterestDefaultRate DECIMAL(20,2) = 0,
        @ClaimDate DATE,
        @DPDDate DATE,
        @DPDAccumulate INT = 0,
        @MovementDPD INT = 0,
        @MovementStartDate DATE,
        @MovementEndDate DATE,
        @MovementCalculateStartDate DATE,
        @SuspendDays INT = 0,
        @MovementSuspendDays INT = 0,
        @CalculateDPD BIT = 0,
        @DFDDate DATE, -- Not assigned in original procedure; preserve original behavior.
        @PrincipalTotal DECIMAL(20,2) = 0,
        @InstallmentPrincipal DECIMAL(20,2) = 0,
        @DeferredInterestTotal DECIMAL(20,2) = 0,
        @InterestStartDate DATE,
        @PreviousSuspendIntTotal DECIMAL(20,2) = 0,
        @PreviousDefaultInterestTotal DECIMAL(20,2) = 0,
        @InterestQuantity INT = 0,
        @DaysInYear INT,
        @EndDayOfMonth DATE,
        @DueDate DATE,
        @CheckId INT,
        @TypeId INT,
        @TypeCode NVARCHAR(2),
        @TypeName NVARCHAR(100),
        @NewInterimInterest DECIMAL(20,2),
        @NewDefaultInterest DECIMAL(20,2),
        @NewSuspendIntTotal DECIMAL(20,2),
        @NewDefaultInterestTotal DECIMAL(20,2),
        @NewAccruedInterest DECIMAL(20,2),
        @NewAccruedInterestTotal DECIMAL(20,2),
        @NewDebtBalance DECIMAL(20,2),
        @CurrentDateOnly DATE = CAST(@CurrentDate AS DATE);

    -- Single indexed lookup for card; measure flags were not used in original.
    SELECT
        @SeqCurrent = ISNULL(C.SeqCurrent, 0),
        @InterestPlannedRate = ISNULL(C.InterestPlannedRate, 0),
        @InterestDefaultRate = ISNULL(C.InterestDefaultRate, 0),
        @ClaimDate = C.ClaimPayDate,
        @DPDDate = CAST(C.DFDDate AS DATE)
    FROM dbo.DataDebtorCard AS C
    WHERE C.DataDebtorCardId = @DataDebtorCardId;

    SET @DaysInYear = DATEDIFF(DAY, DATEFROMPARTS(YEAR(@CurrentDate), 1, 1), DATEFROMPARTS(YEAR(@CurrentDate) + 1, 1, 1));
    SET @EndDayOfMonth = EOMONTH(@CurrentDate);
    SET @DueDate = DATEADD(DAY, 29, @ClaimDate);

    -- Preserve original priority: month-end before due-date.
    IF @CurrentDateOnly = @EndDayOfMonth
    BEGIN
        SET @CheckId = CASE WHEN DATEADD(DAY, -1, @DFDDate) = @CurrentDateOnly THEN 9 ELSE 3 END;
        SELECT @TypeId = P.PaymentTypeId,
               @TypeCode = P.PaymentTypeCode,
               @TypeName = P.PaymentTypeName
        FROM dbo.SystemPaymentType AS P
        WHERE P.PaymentTypeId = @CheckId;
    END;

    -- Read current and previous movement in one statement, without converting SeqNo.
    SELECT
        @PrincipalTotal = ISNULL(M.PrincipalTotal, 0),
        @InstallmentPrincipal = ISNULL(M.InstallmentPrincipal, 0),
        @DeferredInterestTotal = ISNULL(M.DeferredInterestTotal, 0),
        @InterestStartDate = M.InterestStartDate,
        @MovementStartDate = CAST(M.DFDStartDate AS DATE),
        @MovementEndDate = CASE WHEN M.DFDEndDate IS NULL OR CAST(M.DFDEndDate AS DATE) > @CurrentDateOnly THEN @CurrentDateOnly ELSE CAST(M.DFDEndDate AS DATE) END,
        @InterestQuantity = DATEDIFF(DAY, M.InterestStartDate, @CurrentDate) + 1,
        @PreviousSuspendIntTotal = ISNULL(P.SuspendIntTotal, 0),
        @PreviousDefaultInterestTotal = ISNULL(P.DefaultInterestTotal, 0)
    FROM dbo.DataDebtorCardMovement AS M
    LEFT JOIN dbo.DataDebtorCardMovement AS P
        ON P.DebtorCardId = M.DebtorCardId
       AND P.SeqNo = @SeqCurrent - 1
    WHERE M.DebtorCardId = @DataDebtorCardId
      AND M.SeqNo = @SeqCurrent;

    SET @NewInterimInterest = CAST(ROUND(@PrincipalTotal * (@InterestPlannedRate / 100.0) * @InterestQuantity / @DaysInYear, 2) AS DECIMAL(20,2));
    SET @NewDefaultInterest = CAST(ROUND(@InstallmentPrincipal * (@InterestDefaultRate / 100.0) * @InterestQuantity / @DaysInYear, 2) AS DECIMAL(20,2));
    SET @NewSuspendIntTotal = CAST(ROUND(@PreviousSuspendIntTotal + @NewInterimInterest, 2) AS DECIMAL(20,2));
    SET @NewDefaultInterestTotal = CAST(ROUND(@PreviousDefaultInterestTotal + @NewDefaultInterest, 2) AS DECIMAL(20,2));
    SET @NewAccruedInterest = CAST(ROUND(@NewInterimInterest + @NewDefaultInterest, 2) AS DECIMAL(20,2));
    SET @NewAccruedInterestTotal = CAST(ROUND(@NewSuspendIntTotal + @NewDefaultInterestTotal + @DeferredInterestTotal, 2) AS DECIMAL(20,2));
    SET @NewDebtBalance = CAST(ROUND(@PrincipalTotal + @NewAccruedInterestTotal, 2) AS DECIMAL(20,2));

    -- DPD logic merged from SP_DCS_022; only active when DFD is valid.
    -- No suspended-day deduction when DFD has not been reached.
    IF @DPDDate IS NOT NULL AND @DPDDate <> '19000101' AND @CurrentDateOnly >= @DPDDate
    BEGIN
        IF @MovementStartDate IS NULL
            THROW 50002, N'ไม่พบ DFDStartDate ของ Movement สำหรับคำนวณ DPD', 1;

        SET @CalculateDPD = 1;
        SET @MovementCalculateStartDate = CASE WHEN @MovementStartDate < @DPDDate THEN @DPDDate ELSE @MovementStartDate END;

        CREATE TABLE #SuspendPeriods (StartDate DATE NOT NULL, EndDate DATE NOT NULL);

        ;WITH SuspendRaw AS
        (
            SELECT CAST(P.StartDate AS DATE) AS StartDate, CAST(P.EndDate AS DATE) AS EndDate
            FROM dbo.TDRDataCompromiseContractInstallmentPlanPayment AS P
            WHERE P.DataDebtorCardId = @DataDebtorCardId
              AND P.IsSuspend = 1
              AND (P.IsActive = 1 OR P.IsActive IS NULL)
              AND P.StartDate IS NOT NULL AND P.EndDate IS NOT NULL
              AND P.StartDate <= P.EndDate
              AND P.StartDate < DATEADD(DAY, 1, CAST(@CurrentDateOnly AS DATETIME))
              AND P.EndDate >= @DPDDate
        ), Ordered AS
        (
            SELECT StartDate, EndDate,
                   MAX(EndDate) OVER (ORDER BY StartDate, EndDate ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS PrevMaxEnd
            FROM SuspendRaw
        ), Grouped AS
        (
            SELECT StartDate, EndDate,
                   SUM(CASE WHEN PrevMaxEnd IS NULL OR StartDate > PrevMaxEnd THEN 1 ELSE 0 END)
                   OVER (ORDER BY StartDate, EndDate ROWS UNBOUNDED PRECEDING) AS GroupNo
            FROM Ordered
        )
        INSERT INTO #SuspendPeriods (StartDate, EndDate)
        SELECT MIN(StartDate), MAX(EndDate) FROM Grouped GROUP BY GroupNo;

        SELECT @SuspendDays = COALESCE(SUM(DATEDIFF(DAY,
                       CASE WHEN StartDate < @DPDDate THEN @DPDDate ELSE StartDate END,
                       CASE WHEN EndDate > @CurrentDateOnly THEN @CurrentDateOnly ELSE EndDate END) + 1), 0)
        FROM #SuspendPeriods
        WHERE StartDate <= @CurrentDateOnly AND EndDate >= @DPDDate;

        SET @DPDAccumulate = CASE WHEN DATEDIFF(DAY, @DPDDate, @CurrentDateOnly) + 1 - @SuspendDays < 0
                                 THEN 0 ELSE DATEDIFF(DAY, @DPDDate, @CurrentDateOnly) + 1 - @SuspendDays END;

        IF @MovementEndDate >= @MovementCalculateStartDate
        BEGIN
            SELECT @MovementSuspendDays = COALESCE(SUM(DATEDIFF(DAY,
                           CASE WHEN StartDate < @MovementCalculateStartDate THEN @MovementCalculateStartDate ELSE StartDate END,
                           CASE WHEN EndDate > @MovementEndDate THEN @MovementEndDate ELSE EndDate END) + 1), 0)
            FROM #SuspendPeriods
            WHERE StartDate <= @MovementEndDate AND EndDate >= @MovementCalculateStartDate;

            SET @MovementDPD = CASE WHEN DATEDIFF(DAY, @MovementCalculateStartDate, @MovementEndDate) + 1 - @MovementSuspendDays < 0
                                    THEN 0 ELSE DATEDIFF(DAY, @MovementCalculateStartDate, @MovementEndDate) + 1 - @MovementSuspendDays END;
        END;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

    UPDATE M
    SET M.InterestQuantity = @InterestQuantity,
        M.InterimInterest = @NewInterimInterest,
        M.DefaultInterest = @NewDefaultInterest,
        M.InterestEndDate = @CurrentDate,
        M.SuspendInt = @NewInterimInterest,
        M.SuspendIntTotal = @NewSuspendIntTotal,
        M.DefaultInterestTotal = @NewDefaultInterestTotal,
        M.AccruedInterest = @NewAccruedInterest,
        M.AccruedInterestTotal = @NewAccruedInterestTotal,
        M.DebtBalance = @NewDebtBalance,
        M.DFDEndDate = @CurrentDate,
        M.TypeId = CASE WHEN @CurrentDateOnly = @EndDayOfMonth THEN @TypeId WHEN @CurrentDateOnly = @DueDate THEN 8 ELSE M.TypeId END,
        M.TypeCode = CASE WHEN @CurrentDateOnly = @EndDayOfMonth THEN @TypeCode WHEN @CurrentDateOnly = @DueDate THEN N'08' ELSE M.TypeCode END,
        M.TypeName = CASE WHEN @CurrentDateOnly = @EndDayOfMonth THEN @TypeName WHEN @CurrentDateOnly = @DueDate THEN N'ครบกำหนดชำระ' ELSE M.TypeName END,
        M.DocDate = @CurrentDate,
        M.IsUpdateHistory = 0,
        M.DPD = CASE WHEN @CalculateDPD = 1 THEN @MovementDPD ELSE M.DPD END,
        M.DPDAccumulate = CASE WHEN @CalculateDPD = 1 THEN @DPDAccumulate ELSE M.DPDAccumulate END
    FROM dbo.DataDebtorCardMovement AS M
    WHERE M.DebtorCardId = @DataDebtorCardId
      AND M.SeqNo = @SeqCurrent;

    UPDATE C
    SET C.SuspendIntTotal = @NewSuspendIntTotal,
        C.DefaultInterestTotal = @NewDefaultInterestTotal,
        C.AccruedInterestTotal = @NewAccruedInterestTotal,
        C.InterestStartDate = @InterestStartDate,
        C.InterestEndDate = @CurrentDate,
        C.DebtBalance = CAST(ROUND(ISNULL(C.PrincipalTotal, 0) + @NewAccruedInterestTotal, 2) AS DECIMAL(20,2)),
        C.DPD = CASE WHEN @CalculateDPD = 1 THEN @DPDAccumulate ELSE C.DPD END
    FROM dbo.DataDebtorCard AS C
    WHERE C.DataDebtorCardId = @DataDebtorCardId;

    COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

/* New procedure. Original SP_DCS_Card_002 remains unchanged.
   Processes one set-based LOT per call; caller controls pagination via @AfterCardId.
   @NextCardId output: last selected ID; @SelectedCount=0 means no more cards.
   NOTE: batch updates are NOT safe to repeat for same processing date if movements changed.
*/
CREATE   PROCEDURE dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Lot
    @CurrentDate DATE = NULL,
    @BatchSize INT = 5000,
    @AfterCardId NVARCHAR(150) = NULL,
    @NextCardId NVARCHAR(150) OUTPUT,
    @SelectedCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @CurrentDate IS NULL SET @CurrentDate = CONVERT(date, GETDATE());
    IF @BatchSize NOT BETWEEN 1 AND 5000 THROW 51010, N'BatchSize ต้องอยู่ระหว่าง 1 ถึง 5000', 1;

    DECLARE @DaysInYear INT = DATEDIFF(DAY, DATEFROMPARTS(YEAR(@CurrentDate),1,1),DATEFROMPARTS(YEAR(@CurrentDate)+1,1,1));
    DECLARE @IsMonthEnd BIT = IIF(@CurrentDate = EOMONTH(@CurrentDate),1,0);
    DECLARE @TypeId INT, @TypeCode NVARCHAR(2), @TypeName NVARCHAR(100);
    IF @IsMonthEnd = 1
        SELECT @TypeId = PaymentTypeId, @TypeCode = PaymentTypeCode, @TypeName = PaymentTypeName
        FROM dbo.SystemPaymentType WHERE PaymentTypeId = 3;

    CREATE TABLE #Batch (DataDebtorCardId NVARCHAR(150) COLLATE Thai_CI_AI NOT NULL PRIMARY KEY);
    INSERT #Batch(DataDebtorCardId)
    SELECT TOP (@BatchSize) C.DataDebtorCardId
    FROM dbo.DataDebtorCard C
    INNER JOIN dbo.SystemMeasureMaster S ON S.MeasureId = C.MeasureId AND S.IsDefault = 1
    WHERE C.IsActive = 1 AND C.CardStatusId <> 135
      AND (@AfterCardId IS NULL OR C.DataDebtorCardId > @AfterCardId COLLATE Thai_CI_AI)
    ORDER BY C.DataDebtorCardId;
    SET @SelectedCount = @@ROWCOUNT;
    SELECT @NextCardId = MAX(DataDebtorCardId) FROM #Batch;
    IF @SelectedCount = 0 RETURN;

    /* Materialize current and preceding movement exactly once per account. */
    SELECT C.DataDebtorCardId, C.SeqCurrent, C.ClaimPayDate,
           CONVERT(date,C.DFDDate) AS DFDDate,
           C.InterestPlannedRate, C.InterestDefaultRate,
           M.PrincipalTotal, M.InstallmentPrincipal, M.DeferredInterestTotal,
           M.InterestStartDate, CONVERT(date,M.DFDStartDate) AS DFDStartDate,
           ISNULL(P.SuspendIntTotal,0) AS PreviousSuspendIntTotal,
           ISNULL(P.DefaultInterestTotal,0) AS PreviousDefaultInterestTotal,
           DATEDIFF(DAY,M.InterestStartDate,@CurrentDate)+1 AS InterestQuantity,
           CONVERT(bit, CASE WHEN C.DFDDate IS NOT NULL AND CONVERT(date,C.DFDDate) <> '19000101'
                               AND CONVERT(date,C.DFDDate) <= @CurrentDate THEN 1 ELSE 0 END) AS HasDPD
    INTO #Source
    FROM #Batch B
    JOIN dbo.DataDebtorCard C ON C.DataDebtorCardId = B.DataDebtorCardId
    JOIN dbo.DataDebtorCardMovement M ON M.DebtorCardId = C.DataDebtorCardId AND M.SeqNo = C.SeqCurrent
    LEFT JOIN dbo.DataDebtorCardMovement P ON P.DebtorCardId = M.DebtorCardId AND P.SeqNo = C.SeqCurrent-1;
    CREATE UNIQUE CLUSTERED INDEX IX_Source ON #Source(DataDebtorCardId);

    IF EXISTS (SELECT 1 FROM #Source WHERE InterestStartDate IS NULL OR InterestQuantity < 0)
        THROW 51011, N'พบ InterestStartDate ไม่ถูกต้องใน Lot; ไม่ได้ UPDATE ข้อมูล', 1;
    IF EXISTS (SELECT 1 FROM #Source WHERE HasDPD=1 AND DFDStartDate IS NULL)
        THROW 51012, N'พบ DFDStartDate เป็น NULL ใน Lot; ไม่ได้ UPDATE ข้อมูล', 1;
    IF (SELECT COUNT(*) FROM #Source) <> @SelectedCount
        THROW 51013, N'มี Card ที่ไม่พบ Movement ปัจจุบันใน Lot; ไม่ได้ UPDATE ข้อมูล', 1;

    /* Merge overlapping suspension intervals separately per debtor card. */
    ;WITH RawPeriods AS
    (
        SELECT S.DataDebtorCardId, CONVERT(date,P.StartDate) AS StartDate, CONVERT(date,P.EndDate) AS EndDate
        FROM #Source S
        JOIN dbo.TDRDataCompromiseContractInstallmentPlanPayment P
          ON P.DataDebtorCardId = S.DataDebtorCardId
        WHERE S.HasDPD=1 AND P.IsSuspend=1 AND (P.IsActive=1 OR P.IsActive IS NULL)
          AND P.StartDate IS NOT NULL AND P.EndDate IS NOT NULL AND P.StartDate <= P.EndDate
          AND P.StartDate < DATEADD(DAY,1,CONVERT(datetime,@CurrentDate)) AND P.EndDate >= S.DFDDate
    ), Ordered AS
    (
        SELECT *, MAX(EndDate) OVER(PARTITION BY DataDebtorCardId ORDER BY StartDate,EndDate
                 ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS PrevEnd
        FROM RawPeriods
    ), Islands AS
    (
        SELECT *, SUM(CASE WHEN PrevEnd IS NULL OR StartDate > PrevEnd THEN 1 ELSE 0 END)
          OVER(PARTITION BY DataDebtorCardId ORDER BY StartDate,EndDate ROWS UNBOUNDED PRECEDING) AS GroupNo
        FROM Ordered
    )
    SELECT DataDebtorCardId, MIN(StartDate) AS StartDate, MAX(EndDate) AS EndDate
    INTO #Periods FROM Islands GROUP BY DataDebtorCardId, GroupNo;
    CREATE CLUSTERED INDEX IX_Periods ON #Periods(DataDebtorCardId,StartDate);

    /* DPD calculation: DFDEndDate becomes @CurrentDate in the same update. */
    SELECT S.DataDebtorCardId,
           CASE WHEN S.HasDPD=1 THEN
                CASE WHEN DATEDIFF(DAY,S.DFDDate,@CurrentDate)+1 - ISNULL(A.SuspendDays,0) < 0 THEN 0
                     ELSE DATEDIFF(DAY,S.DFDDate,@CurrentDate)+1 - ISNULL(A.SuspendDays,0) END
           END AS DPDAccumulate,
           CASE WHEN S.HasDPD=1 THEN
                CASE WHEN DATEDIFF(DAY,CASE WHEN S.DFDStartDate < S.DFDDate THEN S.DFDDate ELSE S.DFDStartDate END,@CurrentDate)+1 - ISNULL(B.SuspendDays,0) < 0 THEN 0
                     ELSE DATEDIFF(DAY,CASE WHEN S.DFDStartDate < S.DFDDate THEN S.DFDDate ELSE S.DFDStartDate END,@CurrentDate)+1 - ISNULL(B.SuspendDays,0) END
           END AS DPD
    INTO #DPD
    FROM #Source S
    OUTER APPLY
    (SELECT SUM(DATEDIFF(DAY,CASE WHEN P.StartDate < S.DFDDate THEN S.DFDDate ELSE P.StartDate END,
                   CASE WHEN P.EndDate > @CurrentDate THEN @CurrentDate ELSE P.EndDate END)+1) AS SuspendDays
     FROM #Periods P WHERE P.DataDebtorCardId=S.DataDebtorCardId AND P.StartDate<=@CurrentDate AND P.EndDate>=S.DFDDate) A
    OUTER APPLY
    (SELECT SUM(DATEDIFF(DAY,
                   CASE WHEN P.StartDate < (CASE WHEN S.DFDStartDate < S.DFDDate THEN S.DFDDate ELSE S.DFDStartDate END)
                        THEN (CASE WHEN S.DFDStartDate < S.DFDDate THEN S.DFDDate ELSE S.DFDStartDate END) ELSE P.StartDate END,
                   CASE WHEN P.EndDate > @CurrentDate THEN @CurrentDate ELSE P.EndDate END)+1) AS SuspendDays
     FROM #Periods P WHERE P.DataDebtorCardId=S.DataDebtorCardId AND P.StartDate<=@CurrentDate
       AND P.EndDate >= (CASE WHEN S.DFDStartDate < S.DFDDate THEN S.DFDDate ELSE S.DFDStartDate END)) B;
    CREATE UNIQUE CLUSTERED INDEX IX_DPD ON #DPD(DataDebtorCardId);

    SELECT S.DataDebtorCardId,S.SeqCurrent,S.InterestStartDate,S.ClaimPayDate,S.InterestQuantity,
           CAST(ROUND(ISNULL(S.PrincipalTotal,0)*(ISNULL(S.InterestPlannedRate,0)/100.0)*S.InterestQuantity/@DaysInYear,2) AS DECIMAL(20,2)) AS InterimInterest,
           CAST(ROUND(ISNULL(S.InstallmentPrincipal,0)*(ISNULL(S.InterestDefaultRate,0)/100.0)*S.InterestQuantity/@DaysInYear,2) AS DECIMAL(20,2)) AS DefaultInterest,
           S.PreviousSuspendIntTotal,S.PreviousDefaultInterestTotal,ISNULL(S.DeferredInterestTotal,0) AS DeferredInterestTotal,
           ISNULL(S.PrincipalTotal,0) AS PrincipalTotal,D.DPD,D.DPDAccumulate
    INTO #Base FROM #Source S JOIN #DPD D ON D.DataDebtorCardId=S.DataDebtorCardId;

    SELECT B.*,
           CAST(ROUND(B.PreviousSuspendIntTotal+B.InterimInterest,2) AS DECIMAL(20,2)) AS SuspendIntTotal,
           CAST(ROUND(B.PreviousDefaultInterestTotal+B.DefaultInterest,2) AS DECIMAL(20,2)) AS DefaultInterestTotal,
           CAST(ROUND(B.InterimInterest+B.DefaultInterest,2) AS DECIMAL(20,2)) AS AccruedInterest
    INTO #Totals FROM #Base B;

    SELECT T.*,
           CAST(ROUND(T.SuspendIntTotal+T.DefaultInterestTotal+T.DeferredInterestTotal,2) AS DECIMAL(20,2)) AS AccruedInterestTotal
    INTO #Result FROM #Totals T;
    CREATE UNIQUE CLUSTERED INDEX IX_Result ON #Result(DataDebtorCardId);

    BEGIN TRY
        BEGIN TRANSACTION;
        UPDATE M SET
            M.InterestQuantity=R.InterestQuantity, M.InterimInterest=R.InterimInterest,
            M.DefaultInterest=R.DefaultInterest, M.InterestEndDate=@CurrentDate,
            M.SuspendInt=R.InterimInterest, M.SuspendIntTotal=R.SuspendIntTotal,
            M.DefaultInterestTotal=R.DefaultInterestTotal, M.AccruedInterest=R.AccruedInterest,
            M.AccruedInterestTotal=R.AccruedInterestTotal,
            M.DebtBalance=CAST(ROUND(R.PrincipalTotal+R.AccruedInterestTotal,2) AS DECIMAL(20,2)),
            M.DFDEndDate=@CurrentDate,
            M.TypeId=CASE WHEN @IsMonthEnd=1 THEN @TypeId WHEN @CurrentDate=DATEADD(DAY,29,R.ClaimPayDate) THEN 8 ELSE M.TypeId END,
            M.TypeCode=CASE WHEN @IsMonthEnd=1 THEN @TypeCode WHEN @CurrentDate=DATEADD(DAY,29,R.ClaimPayDate) THEN N'08' ELSE M.TypeCode END,
            M.TypeName=CASE WHEN @IsMonthEnd=1 THEN @TypeName WHEN @CurrentDate=DATEADD(DAY,29,R.ClaimPayDate) THEN N'ครบกำหนดชำระ' ELSE M.TypeName END,
            M.DocDate=@CurrentDate, M.IsUpdateHistory=0,
            M.DPD=COALESCE(R.DPD,M.DPD),M.DPDAccumulate=COALESCE(R.DPDAccumulate,M.DPDAccumulate)
        FROM dbo.DataDebtorCardMovement M
        JOIN #Result R ON R.DataDebtorCardId=M.DebtorCardId AND R.SeqCurrent=M.SeqNo;

        UPDATE C SET C.SuspendIntTotal=R.SuspendIntTotal,C.DefaultInterestTotal=R.DefaultInterestTotal,
            C.AccruedInterestTotal=R.AccruedInterestTotal,C.InterestStartDate=R.InterestStartDate,
            C.InterestEndDate=@CurrentDate,
            C.DebtBalance=CAST(ROUND(ISNULL(C.PrincipalTotal,0)+R.AccruedInterestTotal,2) AS DECIMAL(20,2)),
            C.DPD=COALESCE(R.DPDAccumulate,C.DPD)
        FROM dbo.DataDebtorCard C JOIN #Result R ON R.DataDebtorCardId=C.DataDebtorCardId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

CREATE PROCEDURE [dbo].[SP_DCS_Card_003_InsertBalance]
    @CurrentDate DATE = '2026-05-01',
    @DataDebtorCardId NVARCHAR(150) = 'B99D4612-7CD4-448B-ACB5-BCE932D008EF',
    @IsAdjust INT = 0,
    @AdjustDate DATE = '2025-12-01'
AS
BEGIN
    DECLARE @EStatementId NVARCHAR(150) = '8ee79f11-5eee-4014-b1fc-b74585ff1ee5';
    DECLARE @SeqCurrent INT = (SELECT SeqCurrent FROM DataDebtorCard WHERE DataDebtorCardId = @DataDebtorCardId);
    DECLARE @EndDate DATETIME = (SELECT InterestEndDate + 1 FROM DataDebtorCardMovement WHERE DebtorCardId = @DataDebtorCardId AND SeqNo = @SeqCurrent);
    DECLARE @DaysInYear INT = DATEDIFF(DAY, CAST(YEAR(GETDATE()) AS NVARCHAR) + '-01-01', CAST(YEAR(GETDATE()) AS NVARCHAR) + '-12-31') + 1;

    DECLARE @TypeId INT = (SELECT PaymentTypeId FROM SystemPaymentType WHERE PaymentTypeId = 8);
    DECLARE @TypeCode NVARCHAR(2) = (SELECT PaymentTypeCode FROM SystemPaymentType WHERE PaymentTypeId = @TypeId);
    DECLARE @TypeName NVARCHAR(100) = (SELECT PaymentTypeName FROM SystemPaymentType WHERE PaymentTypeId = @TypeId);

    DECLARE @InterestRate DECIMAL(20,4);
    DECLARE @InterestPlannedRate DECIMAL(20,4);
    DECLARE @InterestDefaultRate DECIMAL(20,4);
    DECLARE @ClaimPayDate DATE;
    DECLARE @Check INT = 0;
    DECLARE @MeasureId INT = 0;
    DECLARE @IsAuto INT = (SELECT TOP 1 IsAuto FROM SystemReceivePaymentMaster);

    SELECT @InterestRate = InterestRate,
           @InterestPlannedRate = InterestPlannedRate,
           @InterestDefaultRate = InterestDefaultRate,
           @ClaimPayDate = ClaimPayDate,
           @MeasureId = MeasureId
    FROM DataDebtorCard
    WHERE DataDebtorCardId = @DataDebtorCardId;

    SET @Check = (SELECT TOP 1 IsReceivership FROM SystemMeasureMaster WHERE MeasureId = @MeasureId);
    DECLARE @EndDayOfMonth DATETIME = EOMONTH(@CurrentDate);
    DECLARE @DocDate DATE = CASE WHEN @IsAdjust = 1 THEN @AdjustDate ELSE GETDATE() END;
    DECLARE @PayDate DATE = CASE WHEN @IsAdjust = 1 THEN @CurrentDate ELSE CAST('1900-01-01' AS DATETIME) END;

    -- ==============================================================
    -- NEW: DFD / DPD / DPDAccumulate after installment allocation
    -- ==============================================================
    DECLARE @OldDFDDate DATE = '1900-01-01';
    DECLARE @NewDFDDate DATE = '1900-01-01';
    DECLARE @DFDDate DATE = '1900-01-01';
    DECLARE @DPD INT = 0;
    DECLARE @DPDAccumulate INT = 0;
    DECLARE @DPDStartDate DATE;

    SELECT @OldDFDDate = ISNULL(CAST(DFDDate AS DATE), '1900-01-01')
    FROM dbo.DataDebtorCard
    WHERE DataDebtorCardId = @DataDebtorCardId;

    -- Oldest unpaid, non-suspended installment strictly before payment month.
    SELECT TOP (1)
           @NewDFDDate = DATEADD(DAY, 1, CAST(p.DueDate AS DATE))
    FROM dbo.TDRDataCompromiseContractInstallmentPlanPayment AS p
    WHERE p.DataDebtorCardId = @DataDebtorCardId
      AND ISNULL(p.IsActive, 1) = 1
      AND ISNULL(p.IsSuspend, 0) = 0
      AND p.DueDate < DATEFROMPARTS(YEAR(@CurrentDate), MONTH(@CurrentDate), 1)
      AND ISNULL(p.PrincipalPay, 0) + ISNULL(p.AccruedInterestPay, 0) < ISNULL(p.Total, 0)
    ORDER BY p.DueDate ASC, p.Seq ASC;

    -- Sentinel means no overdue installment. Preserve DataDebtorCard.DFDDate.
    IF @NewDFDDate <> '1900-01-01'
    BEGIN
        SET @DFDDate = CASE WHEN @NewDFDDate > @OldDFDDate
                            THEN @NewDFDDate ELSE @OldDFDDate END;

        IF @DFDDate <> '1900-01-01' AND @DFDDate <= @CurrentDate
        BEGIN
            SET @DPDStartDate = DATEFROMPARTS(YEAR(@CurrentDate), MONTH(@CurrentDate), 1);
            IF @DFDDate > @DPDStartDate SET @DPDStartDate = @DFDDate;
            SET @DPD = DATEDIFF(DAY, @DPDStartDate, @CurrentDate) + 1;
            SET @DPDAccumulate = DATEDIFF(DAY, @DFDDate, @CurrentDate) + 1;
        END;
    END;

    INSERT INTO [dbo].[DataDebtorCardMovement]
    (
        [DebtorCardMovementId], [DebtorCardId], [DocDate], [PayDate], [LGNo],
        [DebtorId], [DebtorCode], [DebtorCardCode], [DebtorCardName],
        [TypeId], [TypeCode], [TypeName], [FlagAutoPay],
        [DFDDate], [DFDStartDate], [DFDEndDate], [DPD],
        [TotalPay], [IsAdjust], [AdjustRefDocNo], [IsDelete],
        [MeasureId], [MeasureCode], [MeasureName],
        [InterestRate], [InterestPlannedRate], [InterestDefaultRate],
        [DebtBalance], [ReceivePayment],
        [Installment], [InstallmentPay], [InstallmentTotal],
        [Principal], [PrincipalPay], [PrincipalTotal], [InterimInterest],
        [AccruedInterest], [AccruedInterestPay], [AccruedInterestTotal],
        [CourtFee], [CourtFeePay], [CourtFeeTotal],
        [LawyerFee], [LawyerFeePay], [LawyerFeeTotal],
        [OtherExpense], [OtherExpensePay], [OtherExpenseTotal],
        [InitialMargin], [InitialMarginPay], [InitialMarginTotal],
        [SuspendInt], [SuspendIntPay], [SuspendIntTotal],
        [DeferredInterest], [DeferredInterestPay], [DeferredInterestTotal],
        [SuspendedDefaultInterest], [SuspendedDefaultInterestPay], [SuspendedDefaultInterestTotal],
        [PlannedInterest], [PlannedInterestPay], [PlannedInterestTotal],
        [DefaultInterest], [DefaultInterestPay], [DefaultInterestTotal],
        [CreateBy], [CreateDate], [UpdateBy], [UpdateDate],
        [ReceiptNo], [IsEstatement], [EStatementRef], [PaymentTypeId], [SeqNo],
        [DebtorPaymentId], [DebtorPaymentCode], [CompromiseContractGroup], [ReceiptId],
        [InstallmentPrincipal], [InstallmentPrincipalPay], [InstallmentPrincipalTotal],
        [InstallmentInterest], [InstallmentInterestPay], [InstallmentInterestTotal],
        [InterestStartDate], [InterestEndDate], [InterestQuantity],
        [IsUpdateHistory], [DPDAccumulate]
    )
    SELECT NEWID(), cm.[DebtorCardId], @DocDate, @PayDate, cm.[LGNo],
           cm.[DebtorId], cm.[DebtorCode], cm.[DebtorCardCode], cm.[DebtorCardName],
           @TypeId, @TypeCode, @TypeName, cm.[FlagAutoPay],
           @DFDDate, @CurrentDate, cm.[DFDEndDate], @DPD,
           0, 0, NULL, 0,
           c.[MeasureId], c.[MeasureCode], c.[MeasureName],
           @InterestRate, @InterestPlannedRate, @InterestDefaultRate,
           cm.[DebtBalance], 0,
           cm.[Installment], 0, cm.[InstallmentTotal],
           cm.[PrincipalTotal], 0, cm.[PrincipalTotal], cm.[InterimInterest],
           0, 0, cm.[AccruedInterestTotal],
           cm.[CourtFeeTotal], 0, cm.[CourtFeeTotal],
           cm.[LawyerFeeTotal], 0, cm.[LawyerFeeTotal],
           cm.[OtherExpenseTotal], 0, cm.[OtherExpenseTotal],
           cm.[InitialMarginTotal], 0, cm.[InitialMarginTotal],
           cm.[SuspendIntTotal], 0, cm.[SuspendIntTotal],
           0, 0, cm.[DeferredInterestTotal],
           cm.[SuspendedDefaultInterestTotal], 0, cm.[SuspendedDefaultInterestTotal],
           0, 0, cm.[PlannedInterestTotal],
           0, 0, cm.[DefaultInterestTotal],
           1, GETDATE(), 1, GETDATE(),
           NULL, 0, NULL, cm.[PaymentTypeId], cm.[SeqNo] + 1,
           cm.[DebtorPaymentId], cm.[DebtorPaymentCode], cm.[CompromiseContractGroup], cm.[ReceiptId],
           c.[InstallmentPrincipalTotal], 0, c.[InstallmentPrincipalTotal],
           c.[InstallmentInterestTotal], 0, c.[InstallmentInterestTotal],
           @CurrentDate, @CurrentDate, cm.[InterestQuantity],
           0, @DPDAccumulate
    FROM DataDebtorCardMovement AS cm
    LEFT JOIN DataDebtorCard AS c ON c.DataDebtorCardId = cm.DebtorCardId
    WHERE cm.DebtorCardId = @DataDebtorCardId
      AND cm.SeqNo = @SeqCurrent
      AND c.CardStatusId != 135;

    UPDATE DataDebtorCard
    SET SeqCurrent = SeqCurrent + 1,
        SeqNext = SeqNext + 1,
        InterestStartDate = @CurrentDate,
        InterestEndDate = @CurrentDate
    WHERE DataDebtorCardId = @DataDebtorCardId
      AND CardStatusId != 135;
END;

CREATE   PROCEDURE dbo.SP_DCS_Card_005_RunDailyBatch
 @ProcessDate date = NULL,
 @BatchSize int = 5000
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 IF @ProcessDate IS NULL SET @ProcessDate = CONVERT(date, GETDATE());
 IF @BatchSize NOT BETWEEN 1 AND 5000 THROW 51000, N'BatchSize ต้องอยู่ระหว่าง 1 ถึง 5000', 1;
 DECLARE @LockResult int, @RunId bigint, @Id nvarchar(150), @i int,
         @Total int = 0, @Success int = 0, @Error int = 0, @Message nvarchar(4000);
 EXEC @LockResult = sys.sp_getapplock @Resource=N'DCSCard002_DailyBatch', @LockMode='Exclusive', @LockOwner='Session', @LockTimeout=0;
 IF @LockResult < 0 THROW 51001, N'มี Job คำนวณดอกเบี้ยกำลังรันอยู่แล้ว', 1;
 BEGIN TRY
  INSERT dbo.DCSCard002JobRunLog(ProcessDate,StartDateTime,Status)
  VALUES(@ProcessDate,SYSDATETIME(),'Running');
  SET @RunId = SCOPE_IDENTITY();

  /* Snapshot of eligible cards is created only once for a given day. */
  IF NOT EXISTS (SELECT 1 FROM dbo.DCSCard002JobQueue WHERE ProcessDate=@ProcessDate)
  BEGIN
   INSERT dbo.DCSCard002JobQueue(ProcessDate,DataDebtorCardId)
   SELECT @ProcessDate, C.DataDebtorCardId
   FROM dbo.DataDebtorCard AS C
   INNER JOIN dbo.SystemMeasureMaster AS S ON S.MeasureId=C.MeasureId
   WHERE C.IsActive=1 AND C.CardStatusId<>135 AND S.IsDefault=1
     AND C.DataDebtorCardId IS NOT NULL;
  END;

  SELECT @Total=COUNT(*), @Success=COALESCE(SUM(CASE WHEN Status='Success' THEN 1 ELSE 0 END),0)
  FROM dbo.DCSCard002JobQueue WHERE ProcessDate=@ProcessDate;
  UPDATE dbo.DCSCard002JobRunLog SET TotalCount=@Total,SuccessCount=@Success WHERE RunId=@RunId;

  CREATE TABLE #Batch (RowNo int IDENTITY(1,1) PRIMARY KEY, DataDebtorCardId nvarchar(150) COLLATE Thai_CI_AI NOT NULL);
  WHILE 1=1
  BEGIN
   TRUNCATE TABLE #Batch;
   INSERT #Batch(DataDebtorCardId)
   SELECT TOP (@BatchSize) DataDebtorCardId
   FROM dbo.DCSCard002JobQueue
   WHERE ProcessDate=@ProcessDate AND Status='Pending'
   ORDER BY DataDebtorCardId;
   IF @@ROWCOUNT=0 BREAK;
   SET @i=1;
   WHILE @i <= (SELECT COUNT(*) FROM #Batch)
   BEGIN
    SELECT @Id=DataDebtorCardId FROM #Batch WHERE RowNo=@i;
    BEGIN TRY
     EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
          @CurrentDate=@ProcessDate, @DataDebtorCardId=@Id;
     UPDATE dbo.DCSCard002JobQueue
       SET Status='Success',AttemptCount=AttemptCount+1,CompletedAt=SYSDATETIME(),ErrorDetail=NULL
     WHERE ProcessDate=@ProcessDate AND DataDebtorCardId=@Id;
     SET @Success+=1;
    END TRY
    BEGIN CATCH
     SET @Message=CONCAT(N'CardId=',@Id,N'; ',ERROR_NUMBER(),N': ',ERROR_MESSAGE());
     UPDATE dbo.DCSCard002JobQueue
       SET Status='Error',AttemptCount=AttemptCount+1,ErrorDetail=@Message
     WHERE ProcessDate=@ProcessDate AND DataDebtorCardId=@Id;
     SET @Error+=1;
     /* Continue remaining cards; report job failure at the end. */
    END CATCH;
    SET @i+=1;
   END;
   UPDATE dbo.DCSCard002JobRunLog SET SuccessCount=@Success,ErrorCount=@Error WHERE RunId=@RunId;
  END;

  SELECT @Error=COUNT(*) FROM dbo.DCSCard002JobQueue WHERE ProcessDate=@ProcessDate AND Status='Error';
  UPDATE dbo.DCSCard002JobRunLog
   SET EndDateTime=SYSDATETIME(),SuccessCount=@Success,ErrorCount=@Error,
       Status=CASE WHEN @Error>0 THEN 'Error' ELSE 'Success' END,
       Detail=CONCAT(N'BatchSize=',@BatchSize,N'; Errors=',@Error)
  WHERE RunId=@RunId;
  IF @Error>0 THROW 51002, N'มีบัญชีประมวลผลผิดพลาด ตรวจสอบ DCSCard002JobQueue และแก้ไขก่อนรันใหม่', 1;
 END TRY
 BEGIN CATCH
  IF @RunId IS NOT NULL
   UPDATE dbo.DCSCard002JobRunLog
    SET EndDateTime=COALESCE(EndDateTime,SYSDATETIME()),Status='Error',Detail=CONCAT(N'Error ',ERROR_NUMBER(),N': ',ERROR_MESSAGE())
   WHERE RunId=@RunId AND Status='Running';
  EXEC sys.sp_releaseapplock @Resource=N'DCSCard002_DailyBatch',@LockOwner='Session';
  THROW;
 END CATCH;
 EXEC sys.sp_releaseapplock @Resource=N'DCSCard002_DailyBatch',@LockOwner='Session';
END;

CREATE   PROCEDURE dbo.SP_DCS_Card_005_RunDailyLot
 @ProcessDate date = NULL,
 @BatchSize int = 5000
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 IF @ProcessDate IS NULL SET @ProcessDate=CONVERT(date,GETDATE());
 IF @BatchSize NOT BETWEEN 1 AND 5000 THROW 51100,N'BatchSize ต้องอยู่ระหว่าง 1 ถึง 5000',1;
 IF OBJECT_ID(N'dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Lot',N'P') IS NULL
  THROW 51101,N'ไม่พบ SP_DCS_Card_002_UpdateInterestEveryDay_Lot',1;
 IF OBJECT_ID(N'dbo.DCSCard002JobRunLog',N'U') IS NULL
  THROW 51102,N'ไม่พบตาราง DCSCard002JobRunLog จาก Job เดิม',1;
 DECLARE @LockResult int,@RunId bigint=NULL,@AfterId nvarchar(150)=NULL,
         @NextId nvarchar(150),@Selected int,@Processed bigint=0,@Lots int=0,
         @Status varchar(12),@Err nvarchar(4000);
 EXEC @LockResult=sys.sp_getapplock @Resource=N'DCSCard002_DailyBatch',@LockMode='Exclusive',@LockOwner='Session',@LockTimeout=0;
 IF @LockResult<0 THROW 51103,N'มี Job ดอกเบี้ยกำลังทำงานอยู่',1;
 BEGIN TRY
  SELECT @AfterId=LastCardId,@Processed=ProcessedCount,@Status=Status
  FROM dbo.DCSCard002LotCheckpoint WHERE ProcessDate=@ProcessDate;
  IF @Status='Success'
  BEGIN
   PRINT N'วันที่นี้ประมวลผลสำเร็จแล้ว ไม่รันซ้ำ';
   EXEC sys.sp_releaseapplock @Resource=N'DCSCard002_DailyBatch',@LockOwner='Session';
   RETURN;
  END;
  IF @Status IS NULL
   INSERT dbo.DCSCard002LotCheckpoint(ProcessDate) VALUES(@ProcessDate);
  ELSE
   UPDATE dbo.DCSCard002LotCheckpoint SET Status='Running',ErrorDetail=NULL,LastUpdatedAt=SYSDATETIME()
   WHERE ProcessDate=@ProcessDate;
  INSERT dbo.DCSCard002JobRunLog(ProcessDate,StartDateTime,Status,TotalCount,SuccessCount,ErrorCount,Detail)
  VALUES(@ProcessDate,SYSDATETIME(),'Running',0,CONVERT(int,CASE WHEN @Processed>2147483647 THEN 2147483647 ELSE @Processed END),0,N'Lot set-based');
  SET @RunId=SCOPE_IDENTITY();
  WHILE 1=1
  BEGIN
   SET @NextId=NULL;
   SET @Selected=0;
   EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Lot
       @CurrentDate=@ProcessDate,@BatchSize=@BatchSize,@AfterCardId=@AfterId,
       @NextCardId=@NextId OUTPUT,@SelectedCount=@Selected OUTPUT;
   IF @Selected=0 BREAK;
   IF @NextId IS NULL OR (@AfterId IS NOT NULL AND @NextId<=@AfterId COLLATE Thai_CI_AI)
    THROW 51104,N'Lot ไม่เลื่อนตำแหน่งการอ่านข้อมูล',1;
   SET @Processed+=@Selected;
   SET @Lots+=1;
   /* The Lot SP commits before this checkpoint update. A crash in between
      can leave an updated lot without a checkpoint. Investigate before retry. */
   UPDATE dbo.DCSCard002LotCheckpoint
   SET LastCardId=@NextId,ProcessedCount=@Processed,Status='Running',LastUpdatedAt=SYSDATETIME()
   WHERE ProcessDate=@ProcessDate;
   UPDATE dbo.DCSCard002JobRunLog
   SET TotalCount=CONVERT(int,CASE WHEN @Processed>2147483647 THEN 2147483647 ELSE @Processed END),
       SuccessCount=CONVERT(int,CASE WHEN @Processed>2147483647 THEN 2147483647 ELSE @Processed END),
       Detail=CONCAT(N'Lots=',@Lots,N'; BatchSize=',@BatchSize,N'; LastCardId=',@NextId)
   WHERE RunId=@RunId;
   SET @AfterId=@NextId;
  END;
  UPDATE dbo.DCSCard002LotCheckpoint SET Status='Success',LastUpdatedAt=SYSDATETIME() WHERE ProcessDate=@ProcessDate;
  UPDATE dbo.DCSCard002JobRunLog SET EndDateTime=SYSDATETIME(),Status='Success',Detail=CONCAT(N'Lot complete; Lots=',@Lots,N'; Processed=',@Processed)
  WHERE RunId=@RunId;
 END TRY
 BEGIN CATCH
  SET @Err=CONCAT(N'Error ',ERROR_NUMBER(),N': ',ERROR_MESSAGE());
  UPDATE dbo.DCSCard002LotCheckpoint SET Status='Error',ErrorDetail=@Err,LastUpdatedAt=SYSDATETIME()
  WHERE ProcessDate=@ProcessDate;
  IF @RunId IS NOT NULL
   UPDATE dbo.DCSCard002JobRunLog SET EndDateTime=SYSDATETIME(),Status='Error',ErrorCount=1,Detail=@Err WHERE RunId=@RunId;
  EXEC sys.sp_releaseapplock @Resource=N'DCSCard002_DailyBatch',@LockOwner='Session';
  THROW;
 END CATCH;
 EXEC sys.sp_releaseapplock @Resource=N'DCSCard002_DailyBatch',@LockOwner='Session';
END;

CREATE PROCEDURE [dbo].[SP_DCS_Card_006_InsertDebtorCard]
	@DataDebtorCardId nvarchar(150) = '1D43D99B-B873-4EF2-8CD1-CEDB97AB89E2',
	-- @EStatementId nvarchar(150) = 'B11E471D-BB41-4CD8-B7DF-0F3DFE34B3AE',
	@EStatementId nvarchar(150) = '0000168F-156A-47CA-BEFF-792F79B7FC7F',
	@IsUpfront bit = 0, --0= มาตการทั่วไป, 1=Upfront
	@IsAdjust int = 0, --0 = รายการปกติ, 1=รายการที่ต้องปรับปรุง
	@AdjustDate date = '2025-12-01' --วันที่ปรับปรุง
,@UserId int = 1
AS
BEGIN
    --SET NOCOUNT ON;
SET NOCOUNT ON;
SET @UserId = ISNULL(@UserId, 1);
	DECLARE @Amount DECIMAL(20,6);
	DECLARE @GetDate datetime;
    DECLARE @SeqCurrent INT;
    DECLARE @IDCard NVARCHAR(20);
    DECLARE @LGNo NVARCHAR(20);
	DECLARE @AccruedInterestTotal DECIMAL(20,4) = (select AccruedInterestTotal from DataDebtorCardMovement where DebtorCardId = @DataDebtorCardId and SeqNo=@SeqCurrent-1)
	DECLARE @DebtorTypeId INT;
	DECLARE @DebtorId nvarchar(150);
	DECLARE @PaymentDate DATETIME;
	DECLARE @MeasureId INT;
	DECLARE @UpfrontPaymentSeq int = 737
	DECLARE @DebtorPaymentName NVARCHAR(200) = N''
	DECLARE @CompromiseContractId nvarchar(150) 
	DECLARE @Principal DECIMAL(20,6) = 0
    DECLARE @InterestRate DECIMAL(20,6) = 0

	DECLARE @AccruedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยค้างรับ งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendInt DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพักใหม่(แขวน) งวดปัจจุบัน + งวดค้าง
	DECLARE @DeferredInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพัก งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendedDefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยแขวนผิดนัด งวดปัจจุบัน + งวดค้าง
	DECLARE @PlannedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตามแผน งวดปัจจุบัน + งวดค้าง
	DECLARE @DefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยผิดนัด งวดปัจจุบัน + งวดค้าง
	DECLARE @CheckDefaultMeasureId int = 0 
	DECLARE @CheckClosedStatus int
	-- ✅ เพิ่ม: ตัวแปรเก็บเงินเกิน
	DECLARE @OverPayment DECIMAL(20,6) = 0;

	select 
@MeasureId= MeasureId
,@CheckClosedStatus = CardStatusId
--,@InterestRate = InterestRate
--,@InterestPlannedRate = InterestPlannedRate
--,@InterestDefaultRate = InterestDefaultRate
--,@ClaimDate = ClaimPayDate
--,@DFD = dateadd(day, 30, ClaimPayDate)
from DataDebtorCard where DataDebtorCardId = @DataDebtorCardId

	set @CheckDefaultMeasureId = (select top 1 IsDefault from SystemMeasureMaster where MeasureId = @MeasureId)

if(@CheckDefaultMeasureId = 1 and @CheckClosedStatus !=135)
begin
	--=====ดึงข้อมูลจาก DataEStatement
		SELECT
			@Amount = Amount,
			@GetDate = PaymentDate,
			@IDCard = Reference1,
			@LGNo = Reference2,
			@DebtorPaymentName = CustomerName
		FROM DataEStatement WHERE EStatementId = @EStatementId;


    

		--=====ดึงข้อมูลจาก DataDebtorCard
		SELECT
			@SeqCurrent = SeqCurrent
			,@DebtorTypeId = DebtorRelateTypeId
			,@DebtorId = DebtorId
			,@MeasureId = MeasureId --มาตรการ
			,@CompromiseContractId = CompromiseContractId
			,@Principal = PrincipalTotal 
		, @InterestRate = InterestRate / 100
		FROM DataDebtorCard WHERE DataDebtorCardId = @DataDebtorCardId;

		select top 1 Interest
		from TDRDataCompromiseContractInstallmentPlanPayment p
		where p.CompromiseContractId = @CompromiseContractId
		and IsPayment = 0
		order by Seq asc




		DECLARE @DebtorCardMovementIdMax nvarchar(150) = (
			SELECT TOP 1 DebtorCardMovementId
			FROM DataDebtorCardMovement
			WHERE DebtorId = @DebtorId
			ORDER BY SeqNo DESC
		);

		--=====ดึง ประเภทรายการรับชำระ
		DECLARE @TypeId INT = 2;
		DECLARE @TypeCode NVARCHAR(2);
		DECLARE @TypeName NVARCHAR(50);

		SELECT
			@TypeCode = PaymentTypeCode,
			@TypeName = PaymentTypeName
		FROM SystemPaymentType WHERE PaymentTypeId = @TypeId;

	   --=====ดึงลำดับการตัดชำระ

    
		--ลำดับตัดชำระ ของมาตรการในการ์ด
		DECLARE @PaymentSeq INT = 
		(case when @IsUpfront = 1 then @UpfrontPaymentSeq else 
		( SELECT TOP 1 m.ConditionItemMapingValue
			FROM SystemConditionItemMappingValueMaster m
			LEFT JOIN SystemConditionMaster c ON m.ConditionId = c.ConditionId
			LEFT JOIN SystemCampaignConditionMaster cc ON cc.ConditionId = c.ConditionId
			LEFT JOIN SystemMeasureCampaignMaster cm ON cm.CampaignId = cc.CampaignId
			LEFT JOIN SystemMeasureMaster mm ON mm.MeasureId = cm.MeasureId
			WHERE mm.IsDefault = 1 AND m.ConditionItemId = 20
		)
		end);
	   --ประเภทการรับชำระ 1=แนวตั้ง, 15=แนวนอน
		DECLARE @PaymentSeqType INT = (select top 1 PaymentMethodId from SystemPaymentSeqMaster where PaymentSeqId = @PaymentSeq)
  
	   --=====หาจำนวนวัน ในปีที่คิดดอกเบี้ย (365 วัน หรือ 366 วัน)
		DECLARE @InterestDate INT = DATEDIFF(
			DAY,
			(SELECT InterestStartDate FROM DataDebtorCardMovement WHERE DebtorCardMovementId = @DebtorCardMovementIdMax),
			DATEADD(DAY, -1, @PaymentDate)
		) + 1;
		DECLARE @DaysInYear INT = DATEDIFF(DAY, '2024-01-01', '2024-12-31') + 1;

		DECLARE @Interest DECIMAL(20,6) = @Principal * @InterestRate * @InterestDate / @DaysInYear;

		-- เตรียม temp table
		IF OBJECT_ID('tempdb..#tmp') IS NOT NULL DROP TABLE #tmp;

	   --=====ตัดชำระ ตามลำดับ
		-- ✅ แก้: คุม PayableAmount ของ Principal ไม่ให้เกิน PrincipalTotal ที่เหลือ (@Principal)
		SELECT 
			ROW_NUMBER() OVER (ORDER BY sd.Seq) AS RowNum,
			sd.Seq,
			sd.PaymentSeqTypeId,
			l.KeyName,
			l.LookUpValue,

			CAST(
				CASE 
					WHEN l.KeyName = 'Principal'
						THEN CASE WHEN x.RawPayable > ISNULL(@Principal,0) THEN ISNULL(@Principal,0) ELSE x.RawPayable END
					ELSE x.RawPayable
				END
			AS DECIMAL(20,6)) AS PayableAmount,

			CAST(0.0 AS DECIMAL(20,6)) AS BFAmount,
			CAST(0.0 AS DECIMAL(20,6)) AS UpdateAmount
		INTO #tmp
		FROM SystemPaymentSeqDetailMaster sd
		LEFT JOIN SystemPaymentSeqMaster s ON s.PaymentSeqId = sd.PaymentSeqId
		LEFT JOIN SystemLookupMaster l ON l.LookupId = sd.PaymentSeqTypeId
		CROSS APPLY (
			SELECT CAST(
				CASE WHEN sd.UnitValuesId = 94 
					 THEN dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) * (sd.[Values]/100)
					 ELSE dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName)
				END
			AS DECIMAL(20,6)) AS RawPayable
		) x
		WHERE s.PaymentSeqId = @PaymentSeq;

		-- วนลูปเพื่อคำนวณและอัปเดต UpdateAmount
		DECLARE @Row INT = 1, @MaxRow INT;
		SELECT @MaxRow = MAX(RowNum) FROM #tmp;

		WHILE @Row <= @MaxRow
		BEGIN
			DECLARE @Payable DECIMAL(20,6), @Update DECIMAL(20,6), @PrevUpdate DECIMAL(20,6);
			SELECT @Payable = PayableAmount FROM #tmp WHERE RowNum = @Row;

			IF @Row = 1
			BEGIN
				UPDATE #tmp SET BFAmount = @Amount WHERE RowNum = 1;
				SET @Update = CASE WHEN @Amount >= @Payable THEN @Amount - @Payable ELSE 0 END;
			END
			ELSE
			BEGIN
				SELECT @PrevUpdate = UpdateAmount FROM #tmp WHERE RowNum = @Row - 1;
				UPDATE #tmp SET BFAmount = @PrevUpdate WHERE RowNum = @Row;
				SET @Update = CASE WHEN @PrevUpdate >= @Payable THEN @PrevUpdate - @Payable ELSE 0 END;
			END

			UPDATE #tmp SET UpdateAmount = @Update WHERE RowNum = @Row;
			SET @Row += 1;
		END

		-- ✅ เพิ่ม: เงินเหลือหลังตัดตามลำดับทั้งหมด -> เก็บเป็น OverPayment
		SELECT @OverPayment = UpdateAmount
		FROM #tmp
		WHERE RowNum = (SELECT MAX(RowNum) FROM #tmp);

		-- debug 
		select * from #tmp;

		SELECT *
		, PayableAmount - (CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END) AS Used
		, CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END AS Total
		INTO #tmpFinal
		FROM #tmp;

		declare @PrincipalPay decimal(20,4);
		declare @PrincipalTotal decimal(20,4);

		declare @DefaultInterestPay decimal(20,4);
		declare @DefaultInterestTotal decimal(20,4);

		declare @AccruedInterestPay decimal(20,4); 
		--declare @AccruedInterestTotal decimal(20,4); 

		declare @PlannedInterestPay decimal(20,4);
		declare @PlannedInterestTotal decimal(20,4);
		declare @SuspendIntTotal decimal(20,4) = 0;
		declare @DeferredInterestTotal decimal(20,4) = 0;
		declare @SuspendedDefaultInterestTotal decimal(20,4) = 0;

		--ดึงเงินต้น
		SELECT @PrincipalPay = [Used],
			   @PrincipalTotal = Total
		FROM #tmpFinal WHERE KeyName = 'Principal';

		--ดึงดอกเบี้ยผิดนัด
		SELECT @DefaultInterestPay = [Used],
			   @DefaultInterestTotal = Total
		FROM #tmpFinal WHERE KeyName = 'DefaultInterest';

		--ดึงดอกเบี้ยตามแผน
		SELECT @PlannedInterestPay = [Used],
			   @PlannedInterestTotal = Total
		FROM #tmpFinal WHERE KeyName = 'PlannedInterest';

		--ค่าธรรมเนียมศาล
		DECLARE @CourtFee DECIMAL(20,4);
		DECLARE @CourtFeePay DECIMAL(20,4);
		DECLARE @CourtFeeTotal DECIMAL(20,4);

		SELECT @CourtFee = Total,
			   @CourtFeePay = [Used],
			   @CourtFeeTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'CourtFee';

		--ค่าทนาย
		DECLARE @LawyerFee DECIMAL(20,4);
		DECLARE @LawyerFeePay DECIMAL(20,4);
		DECLARE @LawyerFeeTotal DECIMAL(20,4);

		SELECT @LawyerFee = Total,
			   @LawyerFeePay = [Used],
			   @LawyerFeeTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'LawyerFee';
	
		--ค่าใช้จ่ายอื่น
		DECLARE @OtherExpense DECIMAL(20,4);
		DECLARE @OtherExpensePay DECIMAL(20,4);
		DECLARE @OtherExpenseTotal DECIMAL(20,4);

		SELECT @OtherExpense = Total,
			   @OtherExpensePay = [Used],
			   @OtherExpenseTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'OtherExpenses';

		--เงินวางประกัน
		DECLARE @InitialMargin DECIMAL(20,4);
		DECLARE @InitialMarginPay DECIMAL(20,4);
		DECLARE @InitialMarginTotal DECIMAL(20,4);

		SELECT @InitialMargin = Total,
			   @InitialMarginPay = [Used],
			   @InitialMarginTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'InitialMargin';

		set @AccruedInterestPay = @DefaultInterestPay + @PlannedInterestPay
		set @AccruedInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal
		--อัปเดต รายการรับชำระ
		UPDATE DCM
		SET 
			DCM.PrincipalPay = @PrincipalPay,
			DCM.PrincipalTotal = @PrincipalTotal,
			--ตามแผน
			DCM.PlannedInterestPay =  @PlannedInterestPay,
			DCM.PlannedInterestTotal =  @PlannedInterestTotal,
			--ผิดนัด
			DCM.DefaultInterestPay = @DefaultInterestPay,
			DCM.DefaultInterestTotal = @DefaultInterestTotal,
			--ค้างรับ
			DCM.AccruedInterestPay = @DefaultInterestPay + @PlannedInterestPay,
			DCM.AccruedInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
			--ค่างวด
			DCM.Installment = @PrincipalTotal,
			DCM.InstallmentPrincipal = @PrincipalTotal,
			DCM.InstallmentPrincipalTotal = @PrincipalTotal,
			DCM.InstallmentInterest = @DefaultInterestTotal + @PlannedInterestTotal,
			DCM.InstallmentInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
			--ค่าธรรมเนียมศาล
			DCM.CourtFee = @CourtFee,
			DCM.CourtFeePay = @CourtFeePay,
			DCM.CourtFeeTotal = @CourtFeeTotal,
			--ค่าทนาย
			DCM.LawyerFee = @LawyerFee,
			DCM.LawyerFeePay = @LawyerFeePay,
			DCM.LawyerFeeTotal = @LawyerFeeTotal,
			--ค่าใช้จ่ายอื่น
			DCM.OtherExpense = @OtherExpense,
			DCM.OtherExpensePay = @OtherExpensePay,
			DCM.OtherExpenseTotal = @OtherExpenseTotal,
			--เงินวางประกัน
			DCM.InitialMargin = @InitialMargin,
			DCM.InitialMarginPay = @InitialMarginPay,
			DCM.InitialMarginTotal = @InitialMarginTotal,
			-- ยอดรับชำระ
			DCM.ReceivePayment = @Amount
		FROM DataDebtorCardMovement DCM
		LEFT JOIN DataDebtorCard DDC ON DDC.DataDebtorCardId = DCM.DebtorCardId
		WHERE DCM.DebtorCardId = @DataDebtorCardId 
		  AND DCM.SeqNo = @SeqCurrent;

		UPDATE DCM2
		SET DebtBalance = DCM2.PrincipalTotal + DCM2.AccruedInterestTotal
		FROM DataDebtorCardMovement DCM2
		LEFT JOIN DataDebtorCard DDC ON DDC.DataDebtorCardId = DCM2.DebtorCardId
		WHERE DCM2.DebtorCardId = @DataDebtorCardId 
		  AND DCM2.SeqNo = @SeqCurrent;

		Update DataDebtorCard
		set InterestStartDate = @GetDate,
			CourtFeeTotal = @CourtFeeTotal,
			LawyerFeeTotal = @LawyerFeeTotal,
			OtherExpenseTotal = @OtherExpenseTotal,
			InitialMarginTotal = @InitialMarginTotal,
			DebtBalance = isnull(@PrincipalTotal,0) + isnull(@PlannedInterestTotal,0) + isnull(@DefaultInterestTotal,0),
			PrincipalTotal = @PrincipalTotal,
			PlannedInterestTotal = @PlannedInterestTotal,
			DefaultInterestTotal = @DefaultInterestTotal,
			AccruedInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal,
			InstallmentPrincipal = @PrincipalTotal,
			InstallmentPrincipalTotal = @PrincipalTotal,
			InstallmentInterest = @PlannedInterestTotal + @DefaultInterestTotal,
			InstallmentInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal
		WHERE DataDebtorCardId = @DataDebtorCardId;

		-- ✅ เพิ่ม: เก็บเงินเกินเข้า DataDebtorCard.OverPayment
		IF (@OverPayment > 0)
		BEGIN
			UPDATE DataDebtorCard
			SET OverPayment = ISNULL(OverPayment,0) + @OverPayment
			WHERE DataDebtorCardId = @DataDebtorCardId;
		END
	
		declare @DefaultDate date = cast('1900-01-01' as date)
	
		--insert  ยอดคงเหลือ
		EXEC  [dbo].[SP_DCS_Card_003_InsertBalance] @GetDate, @DataDebtorCardId ,@IsAdjust , @AdjustDate
		EXEC  [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay] @GetDate, @DataDebtorCardId ,@IsAdjust , @AdjustDate

		-- ถ้าเป็นการ์ดย่อย และ จ่ายเงินต้น ให้นำเงินไปตัดการ์ดหลัก
		if (@PrincipalPay > 0 and @DebtorTypeId != 1)
		begin
			EXEC [SP_DCS_Card_008_UpdateDataDebtorCardSubToMain] @GetDate, @PrincipalPay , @DataDebtorCardId, @LGNo;
		end

		-- ✳✳✳ จุดที่ 1 ที่แก้: เติม SELECT ให้ Insert into CalDataDebtorCard ✳✳✳
		INSERT INTO CalDataDebtorCard(
			UpdateDate,
			DataDebtorCardId,
			EStatementId,
			PaymentDate,
			AmountEStatement,
			PrincipalPay,
			RowNum,
			Seq,
			PaymentSeqTypeId,
			KeyName,
			LookUpValue,
			BFAmount,
			PayableAmount,
			UpdateAmount,
			Used,
			Total
		)
		SELECT 
			GETDATE()               AS UpdateDate,
			@DataDebtorCardId       AS DataDebtorCardId,
			@EStatementId           AS EStatementId,
			@GetDate                AS PaymentDate,
			@Amount                 AS AmountEStatement,
			@PrincipalPay           AS PrincipalPay,
			RowNum,
			Seq,
			PaymentSeqTypeId,
			KeyName,
			LookUpValue,
			BFAmount,
			PayableAmount,
			UpdateAmount,
			Used,
			Total
		FROM #tmpFinal;

		-- ✳✳✳ จุดที่ 2 ที่แก้: เรียก 039 แบบส่ง @CallerHandlesTxn = 1 ✳✳✳
		IF(@IsAdjust = 0)
		BEGIN
		EXEC dbo.SP_DCS_039_InsertReceipt
			 @SystemId                      = 4,
			 @DocumentId                    = 9,
			 @DebtorCardId                  = @DataDebtorCardId,
			 @ReceiptDate                   = @GetDate,
			 @CreateBy                      = 1,
			 @AccountUserId                 = 1,
			 @DebtorPaymentName             = @DebtorPaymentName,
			 @PaymentAmount                 = @Amount,
			 @PrincipalPay                  = @PrincipalPay,
			 @AccruedInterestPay            = @AccruedInterestPay,
			 @CourtFeePay                   = @CourtFeePay,
			 @LawyerFeePay                  = @LawyerFeePay,
			 @OtherExpensePay               = @OtherExpensePay,
			 @InitialMarginPay              = @InitialMarginPay,
			 @CourtFeeTotal                 = @CourtFeeTotal,
			 @LawyerFeeTotal                = @LawyerFeeTotal,
			 @OtherExpenseTotal             = @OtherExpenseTotal,
			 @InitialMarginTotal            = @InitialMarginTotal,
			 @SuspendIntTotal               = @SuspendIntTotal,
			 @DeferredInterestTotal         = @DeferredInterestTotal,
			 @SuspendedDefaultInterestTotal = @SuspendedDefaultInterestTotal,
			 @PlannedInterestTotal          = @PlannedInterestTotal,
			 @DefaultInterestTotal          = @DefaultInterestTotal,
			 @EStatementId                  = @EStatementId,
			 @AccruedInterestTotal          = @AccruedInterestTotal,
			 @SeqCurrent                    = @SeqCurrent;
		--     @CallerHandlesTxn              = 1; -- บอก 039 ว่าตัวนี้คุม txn เอง
		END
		-- ✅ เพิ่ม: ถ้าต้อง “รันสโตตัวต่อไป” เมื่อมีเงินเกิน ให้ใส่ EXEC ตรงนี้ (เปลี่ยนชื่อสโตเอง)
		/*
		IF (@OverPayment > 0)
		BEGIN
			EXEC dbo.SP_DCS_Card_XXX_NextProcess
				 @DataDebtorCardId = @DataDebtorCardId,
				 @PaymentDate      = @GetDate,
				 @OverPayment      = @OverPayment;
		END
		*/

		-- select เดิมของคุณ เอาไว้ดูผล
		SELECT 
			GETDATE() as UpdateDate,
			@DataDebtorCardId as DataDebtorCardId,
			@EStatementId as EStatementId,
			@GetDate as PaymentDate,
			@Amount as AmountEStatement,
			@PrincipalPay as PrincipalPay,
			RowNum,
			Seq,
			PaymentSeqTypeId,
			KeyName,
			LookUpValue,
			BFAmount,
			PayableAmount,
			UpdateAmount,
			Used,
			Total
		FROM #tmpFinal;

		
	Update DataEStatement
	set IsConfirm = 1
	, IsCheck = 1
	where EStatementId = @EStatementId;

	end


	else if (@CheckDefaultMeasureId !=1)
	begin
		exec dbo.[SP_DCS_Card_006_InsertDebtorCard_Horizontal] 
		@DataDebtorCardId
		,@EStatementId
	end
END

Create PROCEDURE [dbo].[SP_DCS_Card_006_InsertDebtorCard_backup]
	@DataDebtorCardId nvarchar(150) = '650F1D67-CAF2-4A91-AC8A-12C49498CFFC',
	@EStatementId nvarchar(150)  =  'a38066e0-0d7d-43cc-bca2-51e12110f494',
	@IsUpfront bit = 0 --0= มาตการทั่วไป, 1=Upfront
AS
BEGIN
    --SET NOCOUNT ON;

	DECLARE @Amount DECIMAL(20,6);
	DECLARE @GetDate datetime;
    DECLARE @SeqCurrent INT;
    DECLARE @IDCard NVARCHAR(20);
    DECLARE @LGNo NVARCHAR(20);
	DECLARE @AccruedInterestTotal DECIMAL(20,4) = (select AccruedInterestTotal from DataDebtorCardMovement where DebtorCardId = @DataDebtorCardId and SeqNo=@SeqCurrent-1)
	DECLARE @DebtorTypeId INT;
	DECLARE @DebtorId nvarchar(150);
	DECLARE @PaymentDate DATETIME;
	DECLARE @MeasureId INT;
	DECLARE @UpfrontPaymentSeq int = 737
	DECLARE @DebtorPaymentName NVARCHAR(200) = N''
	DECLARE @CompromiseContractId nvarchar(150) 
	DECLARE @Principal DECIMAL(20,6) = 0
    DECLARE @InterestRate DECIMAL(20,6) = 0

	DECLARE @AccruedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยค้างรับ งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendInt DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพักใหม่(แขวน) งวดปัจจุบัน + งวดค้าง
	DECLARE @DeferredInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพัก งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendedDefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยแขวนผิดนัด งวดปัจจุบัน + งวดค้าง
	DECLARE @PlannedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตามแผน งวดปัจจุบัน + งวดค้าง
	DECLARE @DefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยผิดนัด งวดปัจจุบัน + งวดค้าง


	--=====ดึงข้อมูลจาก DataEStatement
	SELECT
		@Amount = Amount,
		@GetDate = PaymentDate,
		@IDCard = Reference1,
		@LGNo = Reference2,
		@DebtorPaymentName = CustomerName
	FROM DataEStatement WHERE EStatementId = @EStatementId;


    

	--=====ดึงข้อมูลจาก DataDebtorCard
	SELECT
		@SeqCurrent = SeqCurrent
		,@DebtorTypeId = DebtorRelateTypeId
		,@DebtorId = DebtorId
		,@MeasureId = MeasureId --มาตรการ
		,@CompromiseContractId = CompromiseContractId
		,@Principal = PrincipalTotal 
	, @InterestRate = InterestRate / 100
	FROM DataDebtorCard WHERE DataDebtorCardId = @DataDebtorCardId;

	select top 1 Interest
	from TDRDataCompromiseContractInstallmentPlanPayment p
	where p.CompromiseContractId = @CompromiseContractId
	and IsPayment = 0
	order by Seq asc




    DECLARE @DebtorCardMovementIdMax nvarchar(150) = (
        SELECT TOP 1 DebtorCardMovementId
        FROM DataDebtorCardMovement
        WHERE DebtorId = @DebtorId
        ORDER BY SeqNo DESC
    );

	--=====ดึง ประเภทรายการรับชำระ
    DECLARE @TypeId INT = 2;
    DECLARE @TypeCode NVARCHAR(2);
    DECLARE @TypeName NVARCHAR(50);

	SELECT
		@TypeCode = PaymentTypeCode,
		@TypeName = PaymentTypeName
	FROM SystemPaymentType WHERE PaymentTypeId = @TypeId;

   --=====ดึงลำดับการตัดชำระ

    
	--ลำดับตัดชำระ ของมาตรการในการ์ด
    DECLARE @PaymentSeq INT = 
	(case when @IsUpfront = 1 then @UpfrontPaymentSeq else 
	( SELECT TOP 1 m.ConditionItemMapingValue
        FROM SystemConditionItemMappingValueMaster m
        LEFT JOIN SystemConditionMaster c ON m.ConditionId = c.ConditionId
        LEFT JOIN SystemCampaignConditionMaster cc ON cc.ConditionId = c.ConditionId
        LEFT JOIN SystemMeasureCampaignMaster cm ON cm.CampaignId = cc.CampaignId
        LEFT JOIN SystemMeasureMaster mm ON mm.MeasureId = cm.MeasureId
        WHERE mm.IsDefault = 1 AND m.ConditionItemId = 20
    )
	end);
   --ประเภทการรับชำระ 1=แนวตั้ง, 15=แนวนอน
	DECLARE @PaymentSeqType INT = (select top 1 PaymentMethodId from SystemPaymentSeqMaster where PaymentSeqId = @PaymentSeq)
  
   --=====หาจำนวนวัน ในปีที่คิดดอกเบี้ย (365 วัน หรือ 366 วัน)
    DECLARE @InterestDate INT = DATEDIFF(
        DAY,
        (SELECT InterestStartDate FROM DataDebtorCardMovement WHERE DebtorCardMovementId = @DebtorCardMovementIdMax),
        DATEADD(DAY, -1, @PaymentDate)
    ) + 1;
    DECLARE @DaysInYear INT = DATEDIFF(DAY, '2024-01-01', '2024-12-31') + 1;

    DECLARE @Interest DECIMAL(20,6) = @Principal * @InterestRate * @InterestDate / @DaysInYear;

    -- เตรียม temp table
    IF OBJECT_ID('tempdb..#tmp') IS NOT NULL DROP TABLE #tmp;

   --=====ตัดชำระ ตามลำดับ
    SELECT 
        ROW_NUMBER() OVER (ORDER BY sd.Seq) AS RowNum,
        sd.Seq,
        sd.PaymentSeqTypeId,
        l.KeyName,
        l.LookUpValue,

        CAST(
		--94 = เปอร์เซ็นต์ (%)
		--95 = บาท
            CASE WHEN sd.UnitValuesId = 94 
                 THEN dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) * (sd.[Values]/100)
                 ELSE dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName)
            END AS DECIMAL(20,6)
        ) AS PayableAmount,
		--dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) as P1, 
		--dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) * (sd.[Values]/100) as P2,
        CAST(0.0 AS DECIMAL(20,6)) AS BFAmount,
        CAST(0.0 AS DECIMAL(20,6)) AS UpdateAmount
    INTO #tmp
    FROM SystemPaymentSeqDetailMaster sd
    LEFT JOIN SystemPaymentSeqMaster s ON s.PaymentSeqId = sd.PaymentSeqId
    LEFT JOIN SystemLookupMaster l ON l.LookupId = sd.PaymentSeqTypeId
    WHERE s.PaymentSeqId = @PaymentSeq;

    -- วนลูปเพื่อคำนวณและอัปเดต UpdateAmount
    DECLARE @Row INT = 1, @MaxRow INT;
    SELECT @MaxRow = MAX(RowNum) FROM #tmp;

    WHILE @Row <= @MaxRow
    BEGIN
        DECLARE @Payable DECIMAL(20,6), @Update DECIMAL(20,6), @PrevUpdate DECIMAL(20,6);
        SELECT @Payable = PayableAmount FROM #tmp WHERE RowNum = @Row;

        IF @Row = 1
        BEGIN
            UPDATE #tmp SET BFAmount = @Amount WHERE RowNum = 1;
            SET @Update = CASE WHEN @Amount >= @Payable THEN @Amount - @Payable ELSE 0 END;
        END
        ELSE
        BEGIN
            SELECT @PrevUpdate = UpdateAmount FROM #tmp WHERE RowNum = @Row - 1;
            UPDATE #tmp SET BFAmount = @PrevUpdate WHERE RowNum = @Row;
            SET @Update = CASE WHEN @PrevUpdate >= @Payable THEN @PrevUpdate - @Payable ELSE 0 END;
        END

        UPDATE #tmp SET UpdateAmount = @Update WHERE RowNum = @Row;
        SET @Row += 1;
    END

	-- debug 
	select * from #tmp;

    SELECT *
    , PayableAmount - (CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END) AS Used
    , CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END AS Total
    INTO #tmpFinal
    FROM #tmp;

	declare @PrincipalPay decimal(20,4);
	declare @PrincipalTotal decimal(20,4);

	declare @DefaultInterestPay decimal(20,4);
	declare @DefaultInterestTotal decimal(20,4);

	declare @PlannedInterestPay decimal(20,4);
	declare @PlannedInterestTotal decimal(20,4);
	declare @SuspendIntTotal decimal(20,4) = 0;
	declare @DeferredInterestTotal decimal(20,4) = 0;
	declare @SuspendedDefaultInterestTotal decimal(20,4) = 0;

	--ดึงเงินต้น
	SELECT @PrincipalPay = [Used],
		   @PrincipalTotal = Total
	FROM #tmpFinal WHERE KeyName = 'Principal';

	--ดึงดอกเบี้ยผิดนัด
	SELECT @DefaultInterestPay = [Used],
		   @DefaultInterestTotal = Total
	FROM #tmpFinal WHERE KeyName = 'DefaultInterest';

	--ดึงดอกเบี้ยตามแผน
	SELECT @PlannedInterestPay = [Used],
		   @PlannedInterestTotal = Total
	FROM #tmpFinal WHERE KeyName = 'PlannedInterest';

	--ค่าธรรมเนียมศาล
	DECLARE @CourtFee DECIMAL(20,4);
	DECLARE @CourtFeePay DECIMAL(20,4);
	DECLARE @CourtFeeTotal DECIMAL(20,4);

	SELECT @CourtFee = Total,
		   @CourtFeePay = [Used],
		   @CourtFeeTotal= Total
	FROM #tmpFinal 
	WHERE KeyName = 'CourtFee';

	--ค่าทนาย
	DECLARE @LawyerFee DECIMAL(20,4);
	DECLARE @LawyerFeePay DECIMAL(20,4);
	DECLARE @LawyerFeeTotal DECIMAL(20,4);

	SELECT @LawyerFee = Total,
		   @LawyerFeePay = [Used],
		   @LawyerFeeTotal= Total
	FROM #tmpFinal 
	WHERE KeyName = 'LawyerFee';
	
	--ค่าใช้จ่ายอื่น
	DECLARE @OtherExpense DECIMAL(20,4);
	DECLARE @OtherExpensePay DECIMAL(20,4);
	DECLARE @OtherExpenseTotal DECIMAL(20,4);

	SELECT @OtherExpense = Total,
		   @OtherExpensePay = [Used],
		   @OtherExpenseTotal= Total
	FROM #tmpFinal 
	WHERE KeyName = 'OtherExpenses';

	--เงินวางประกัน
	DECLARE @InitialMargin DECIMAL(20,4);
	DECLARE @InitialMarginPay DECIMAL(20,4);
	DECLARE @InitialMarginTotal DECIMAL(20,4);

	SELECT @InitialMargin = Total,
		   @InitialMarginPay = [Used],
		   @InitialMarginTotal= Total
	FROM #tmpFinal 
	WHERE KeyName = 'InitialMargin';


	--อัปเดต รายการรับชำระ
    UPDATE DCM
    SET 
        DCM.PrincipalPay = @PrincipalPay,
        DCM.PrincipalTotal = @PrincipalTotal,
        --ตามแผน
        DCM.PlannedInterestPay =  @PlannedInterestPay,
        DCM.PlannedInterestTotal =  @PlannedInterestTotal,
        --ผิดนัด
		DCM.DefaultInterestPay = @DefaultInterestPay,
		DCM.DefaultInterestTotal = @DefaultInterestTotal,
		--ค้างรับ
		DCM.AccruedInterestPay = @DefaultInterestPay + @PlannedInterestPay,
		DCM.AccruedInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
		--ค่างวด
		DCM.Installment = @PrincipalTotal,
		DCM.InstallmentPrincipal = @PrincipalTotal,
		DCM.InstallmentPrincipalTotal = @PrincipalTotal,
		DCM.InstallmentInterest = @DefaultInterestTotal + @PlannedInterestTotal,
		DCM.InstallmentInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
		--ค่าธรรมเนียมศาล
		DCM.CourtFee = @CourtFee,
		DCM.CourtFeePay = @CourtFeePay,
        DCM.CourtFeeTotal = @CourtFeeTotal,
		--ค่าทนาย
		DCM.LawyerFee = @LawyerFee,
		DCM.LawyerFeePay = @LawyerFeePay,
        DCM.LawyerFeeTotal = @LawyerFeeTotal,
		--ค่าใช้จ่ายอื่น
		DCM.OtherExpense = @OtherExpense,
		DCM.OtherExpensePay = @OtherExpensePay,
        DCM.OtherExpenseTotal = @OtherExpenseTotal,
		--เงินวางประกัน
		DCM.InitialMargin = @InitialMargin,
		DCM.InitialMarginPay = @InitialMarginPay,
        DCM.InitialMarginTotal = @InitialMarginTotal,
        -- ยอดรับชำระ
        DCM.ReceivePayment = @Amount
    FROM DataDebtorCardMovement DCM
    LEFT JOIN DataDebtorCard DDC ON DDC.DataDebtorCardId = DCM.DebtorCardId
    WHERE DCM.DebtorCardId = @DataDebtorCardId 
	  AND DCM.SeqNo = @SeqCurrent;

	UPDATE DCM2
    SET DebtBalance = DCM2.PrincipalTotal + DCM2.AccruedInterestTotal
	FROM DataDebtorCardMovement DCM2
    LEFT JOIN DataDebtorCard DDC ON DDC.DataDebtorCardId = DCM2.DebtorCardId
    WHERE DCM2.DebtorCardId = @DataDebtorCardId 
	  AND DCM2.SeqNo = @SeqCurrent;

	Update DataDebtorCard
	set InterestStartDate = @GetDate,
		CourtFeeTotal = @CourtFeeTotal,
		LawyerFeeTotal = @LawyerFeeTotal,
		OtherExpenseTotal = @OtherExpenseTotal,
		InitialMarginTotal = @InitialMarginTotal,
		DebtBalance = isnull(@PrincipalTotal,0) + isnull(@PlannedInterestTotal,0) + isnull(@DefaultInterestTotal,0),
		PrincipalTotal = @PrincipalTotal,
		PlannedInterestTotal = @PlannedInterestTotal,
		DefaultInterestTotal = @DefaultInterestTotal,
		AccruedInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal,
		InstallmentPrincipal = @PrincipalTotal,
		InstallmentPrincipalTotal = @PrincipalTotal,
		InstallmentInterest = @PlannedInterestTotal + @DefaultInterestTotal,
		InstallmentInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal
    WHERE DataDebtorCardId = @DataDebtorCardId;

	--insert  ยอดคงเหลือ
	EXEC  [dbo].[SP_DCS_Card_003_InsertBalance] @GetDate, @DataDebtorCardId

	-- ถ้าเป็นการ์ดย่อย และ จ่ายเงินต้น ให้นำเงินไปตัดการ์ดหลัก
	if (@PrincipalPay > 0 and @DebtorTypeId != 1)
	begin
		EXEC [SP_DCS_Card_008_UpdateDataDebtorCardSubToMain] @GetDate, @PrincipalPay , @DataDebtorCardId, @LGNo;
	end

	-- ✳✳✳ จุดที่ 1 ที่แก้: เติม SELECT ให้ Insert into CalDataDebtorCard ✳✳✳
    INSERT INTO CalDataDebtorCard(
        UpdateDate,
        DataDebtorCardId,
        EStatementId,
        PaymentDate,
        AmountEStatement,
        PrincipalPay,
        RowNum,
        Seq,
        PaymentSeqTypeId,
        KeyName,
        LookUpValue,
        BFAmount,
        PayableAmount,
        UpdateAmount,
        Used,
        Total
    )
    SELECT 
        GETDATE()               AS UpdateDate,
        @DataDebtorCardId       AS DataDebtorCardId,
        @EStatementId           AS EStatementId,
        @GetDate                AS PaymentDate,
        @Amount                 AS AmountEStatement,
        @PrincipalPay           AS PrincipalPay,
        RowNum,
        Seq,
        PaymentSeqTypeId,
        KeyName,
        LookUpValue,
        BFAmount,
        PayableAmount,
        UpdateAmount,
        Used,
        Total
    FROM #tmpFinal;

	-- ✳✳✳ จุดที่ 2 ที่แก้: เรียก 039 แบบส่ง @CallerHandlesTxn = 1 ✳✳✳
    --EXEC dbo.SP_DCS_039_InsertReceipt
    --     @SystemId                      = 4,
    --     @DocumentId                    = 9,
    --     @DebtorCardId                  = @DataDebtorCardId,
    --     @ReceiptDate                   = @GetDate,
    --     @CreateBy                      = 1,
    --     @AccountUserId                 = 1,
    --     @DebtorPaymentName             = @DebtorPaymentName,
    --     @PaymentAmount                 = @Amount,
    --     @PrincipalPay                  = @PrincipalPay,
    --     @CourtFeePay                   = @CourtFeePay,
    --     @LawyerFeePay                  = @LawyerFeePay,
    --     @OtherExpensePay               = @OtherExpensePay,
    --     @InitialMarginPay              = @InitialMarginPay,
    --     @CourtFeeTotal                 = @CourtFeeTotal,
    --     @LawyerFeeTotal                = @LawyerFeeTotal,
    --     @OtherExpenseTotal             = @OtherExpenseTotal,
    --     @InitialMarginTotal            = @InitialMarginTotal,
    --     @SuspendIntTotal               = @SuspendIntTotal,
    --     @DeferredInterestTotal         = @DeferredInterestTotal,
    --     @SuspendedDefaultInterestTotal = @SuspendedDefaultInterestTotal,
    --     @PlannedInterestTotal          = @PlannedInterestTotal,
    --     @DefaultInterestTotal          = @DefaultInterestTotal,
    --     @EStatementId                  = @EStatementId,
    --     @CallerHandlesTxn              = 1; -- บอก 039 ว่าตัวนี้คุม txn เอง

    -- select เดิมของคุณ เอาไว้ดูผล
    SELECT 
        GETDATE() as UpdateDate,
        @DataDebtorCardId as DataDebtorCardId,
        @EStatementId as EStatementId,
        @GetDate as PaymentDate,
        @Amount as AmountEStatement,
        @PrincipalPay as PrincipalPay,
        RowNum,
        Seq,
        PaymentSeqTypeId,
        KeyName,
        LookUpValue,
        BFAmount,
        PayableAmount,
        UpdateAmount,
        Used,
        Total
    FROM #tmpFinal;
END

CREATE PROCEDURE [dbo].[SP_DCS_Card_006_InsertDebtorCard_backup2]
	@DataDebtorCardId nvarchar(150) = '8AAD3095-DEBE-4790-83E0-651F3B49788C',
	@EStatementId nvarchar(150) = '66620684-34C9-4A49-9FDF-02AF1E9C659F',
	@IsUpfront bit = 1, --0= มาตการทั่วไป, 1=Upfront
	@IsAdjust int = 1, --0 = รายการปกติ, 1=รายการที่ต้องปรับปรุง
	@AdjustDate date = '2025-06-01' --วันที่ปรับปรุง
AS
BEGIN
    --SET NOCOUNT ON;

	DECLARE @Amount DECIMAL(20,6);
	DECLARE @GetDate datetime;
    DECLARE @SeqCurrent INT;
    DECLARE @IDCard NVARCHAR(20);
    DECLARE @LGNo NVARCHAR(20);
	DECLARE @AccruedInterestTotal DECIMAL(20,4) = (select AccruedInterestTotal from DataDebtorCardMovement where DebtorCardId = @DataDebtorCardId and SeqNo=@SeqCurrent-1)
	DECLARE @DebtorTypeId INT;
	DECLARE @DebtorId nvarchar(150);
	DECLARE @PaymentDate DATETIME;
	DECLARE @MeasureId INT;
	DECLARE @UpfrontPaymentSeq int = 737
	DECLARE @DebtorPaymentName NVARCHAR(200) = N''
	DECLARE @CompromiseContractId nvarchar(150) 
	DECLARE @Principal DECIMAL(20,6) = 0
    DECLARE @InterestRate DECIMAL(20,6) = 0

	DECLARE @AccruedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยค้างรับ งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendInt DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพักใหม่(แขวน) งวดปัจจุบัน + งวดค้าง
	DECLARE @DeferredInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพัก งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendedDefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยแขวนผิดนัด งวดปัจจุบัน + งวดค้าง
	DECLARE @PlannedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตามแผน งวดปัจจุบัน + งวดค้าง
	DECLARE @DefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยผิดนัด งวดปัจจุบัน + งวดค้าง
	DECLARE @CheckDefaultMeasureId int = 0 

	select 
@MeasureId= MeasureId
--,@InterestRate = InterestRate
--,@InterestPlannedRate = InterestPlannedRate
--,@InterestDefaultRate = InterestDefaultRate
--,@ClaimDate = ClaimPayDate
--,@DFD = dateadd(day, 30, ClaimPayDate)
from DataDebtorCard where DataDebtorCardId = @DataDebtorCardId

	set @CheckDefaultMeasureId = (select top 1 IsDefault from SystemMeasureMaster where MeasureId = @MeasureId)

if(@CheckDefaultMeasureId = 1)
begin
	--=====ดึงข้อมูลจาก DataEStatement
		SELECT
			@Amount = Amount,
			@GetDate = PaymentDate,
			@IDCard = Reference1,
			@LGNo = Reference2,
			@DebtorPaymentName = CustomerName
		FROM DataEStatement WHERE EStatementId = @EStatementId;


    

		--=====ดึงข้อมูลจาก DataDebtorCard
		SELECT
			@SeqCurrent = SeqCurrent
			,@DebtorTypeId = DebtorRelateTypeId
			,@DebtorId = DebtorId
			,@MeasureId = MeasureId --มาตรการ
			,@CompromiseContractId = CompromiseContractId
			,@Principal = PrincipalTotal 
		, @InterestRate = InterestRate / 100
		FROM DataDebtorCard WHERE DataDebtorCardId = @DataDebtorCardId;

		select top 1 Interest
		from TDRDataCompromiseContractInstallmentPlanPayment p
		where p.CompromiseContractId = @CompromiseContractId
		and IsPayment = 0
		order by Seq asc




		DECLARE @DebtorCardMovementIdMax nvarchar(150) = (
			SELECT TOP 1 DebtorCardMovementId
			FROM DataDebtorCardMovement
			WHERE DebtorId = @DebtorId
			ORDER BY SeqNo DESC
		);

		--=====ดึง ประเภทรายการรับชำระ
		DECLARE @TypeId INT = 2;
		DECLARE @TypeCode NVARCHAR(2);
		DECLARE @TypeName NVARCHAR(50);

		SELECT
			@TypeCode = PaymentTypeCode,
			@TypeName = PaymentTypeName
		FROM SystemPaymentType WHERE PaymentTypeId = @TypeId;

	   --=====ดึงลำดับการตัดชำระ

    
		--ลำดับตัดชำระ ของมาตรการในการ์ด
		DECLARE @PaymentSeq INT = 
		(case when @IsUpfront = 1 then @UpfrontPaymentSeq else 
		( SELECT TOP 1 m.ConditionItemMapingValue
			FROM SystemConditionItemMappingValueMaster m
			LEFT JOIN SystemConditionMaster c ON m.ConditionId = c.ConditionId
			LEFT JOIN SystemCampaignConditionMaster cc ON cc.ConditionId = c.ConditionId
			LEFT JOIN SystemMeasureCampaignMaster cm ON cm.CampaignId = cc.CampaignId
			LEFT JOIN SystemMeasureMaster mm ON mm.MeasureId = cm.MeasureId
			WHERE mm.IsDefault = 1 AND m.ConditionItemId = 20
		)
		end);
	   --ประเภทการรับชำระ 1=แนวตั้ง, 15=แนวนอน
		DECLARE @PaymentSeqType INT = (select top 1 PaymentMethodId from SystemPaymentSeqMaster where PaymentSeqId = @PaymentSeq)
  
	   --=====หาจำนวนวัน ในปีที่คิดดอกเบี้ย (365 วัน หรือ 366 วัน)
		DECLARE @InterestDate INT = DATEDIFF(
			DAY,
			(SELECT InterestStartDate FROM DataDebtorCardMovement WHERE DebtorCardMovementId = @DebtorCardMovementIdMax),
			DATEADD(DAY, -1, @PaymentDate)
		) + 1;
		DECLARE @DaysInYear INT = DATEDIFF(DAY, '2024-01-01', '2024-12-31') + 1;

		DECLARE @Interest DECIMAL(20,6) = @Principal * @InterestRate * @InterestDate / @DaysInYear;

		-- เตรียม temp table
		IF OBJECT_ID('tempdb..#tmp') IS NOT NULL DROP TABLE #tmp;

	   --=====ตัดชำระ ตามลำดับ
		SELECT 
			ROW_NUMBER() OVER (ORDER BY sd.Seq) AS RowNum,
			sd.Seq,
			sd.PaymentSeqTypeId,
			l.KeyName,
			l.LookUpValue,

			CAST(
			--94 = เปอร์เซ็นต์ (%)
			--95 = บาท
				CASE WHEN sd.UnitValuesId = 94 
					 THEN dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) * (sd.[Values]/100)
					 ELSE dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName)
				END AS DECIMAL(20,6)
			) AS PayableAmount,
			--dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) as P1, 
			--dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) * (sd.[Values]/100) as P2,
			CAST(0.0 AS DECIMAL(20,6)) AS BFAmount,
			CAST(0.0 AS DECIMAL(20,6)) AS UpdateAmount
		INTO #tmp
		FROM SystemPaymentSeqDetailMaster sd
		LEFT JOIN SystemPaymentSeqMaster s ON s.PaymentSeqId = sd.PaymentSeqId
		LEFT JOIN SystemLookupMaster l ON l.LookupId = sd.PaymentSeqTypeId
		WHERE s.PaymentSeqId = @PaymentSeq;

		-- วนลูปเพื่อคำนวณและอัปเดต UpdateAmount
		DECLARE @Row INT = 1, @MaxRow INT;
		SELECT @MaxRow = MAX(RowNum) FROM #tmp;

		WHILE @Row <= @MaxRow
		BEGIN
			DECLARE @Payable DECIMAL(20,6), @Update DECIMAL(20,6), @PrevUpdate DECIMAL(20,6);
			SELECT @Payable = PayableAmount FROM #tmp WHERE RowNum = @Row;

			IF @Row = 1
			BEGIN
				UPDATE #tmp SET BFAmount = @Amount WHERE RowNum = 1;
				SET @Update = CASE WHEN @Amount >= @Payable THEN @Amount - @Payable ELSE 0 END;
			END
			ELSE
			BEGIN
				SELECT @PrevUpdate = UpdateAmount FROM #tmp WHERE RowNum = @Row - 1;
				UPDATE #tmp SET BFAmount = @PrevUpdate WHERE RowNum = @Row;
				SET @Update = CASE WHEN @PrevUpdate >= @Payable THEN @PrevUpdate - @Payable ELSE 0 END;
			END

			UPDATE #tmp SET UpdateAmount = @Update WHERE RowNum = @Row;
			SET @Row += 1;
		END

		-- debug 
		select * from #tmp;

		SELECT *
		, PayableAmount - (CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END) AS Used
		, CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END AS Total
		INTO #tmpFinal
		FROM #tmp;

		declare @PrincipalPay decimal(20,4);
		declare @PrincipalTotal decimal(20,4);

		declare @DefaultInterestPay decimal(20,4);
		declare @DefaultInterestTotal decimal(20,4);

		declare @AccruedInterestPay decimal(20,4); 
		--declare @AccruedInterestTotal decimal(20,4); 

		declare @PlannedInterestPay decimal(20,4);
		declare @PlannedInterestTotal decimal(20,4);
		declare @SuspendIntTotal decimal(20,4) = 0;
		declare @DeferredInterestTotal decimal(20,4) = 0;
		declare @SuspendedDefaultInterestTotal decimal(20,4) = 0;

		--ดึงเงินต้น
		SELECT @PrincipalPay = [Used],
			   @PrincipalTotal = Total
		FROM #tmpFinal WHERE KeyName = 'Principal';

		--ดึงดอกเบี้ยผิดนัด
		SELECT @DefaultInterestPay = [Used],
			   @DefaultInterestTotal = Total
		FROM #tmpFinal WHERE KeyName = 'DefaultInterest';

		--ดึงดอกเบี้ยตามแผน
		SELECT @PlannedInterestPay = [Used],
			   @PlannedInterestTotal = Total
		FROM #tmpFinal WHERE KeyName = 'PlannedInterest';

		--ค่าธรรมเนียมศาล
		DECLARE @CourtFee DECIMAL(20,4);
		DECLARE @CourtFeePay DECIMAL(20,4);
		DECLARE @CourtFeeTotal DECIMAL(20,4);

		SELECT @CourtFee = Total,
			   @CourtFeePay = [Used],
			   @CourtFeeTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'CourtFee';

		--ค่าทนาย
		DECLARE @LawyerFee DECIMAL(20,4);
		DECLARE @LawyerFeePay DECIMAL(20,4);
		DECLARE @LawyerFeeTotal DECIMAL(20,4);

		SELECT @LawyerFee = Total,
			   @LawyerFeePay = [Used],
			   @LawyerFeeTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'LawyerFee';
	
		--ค่าใช้จ่ายอื่น
		DECLARE @OtherExpense DECIMAL(20,4);
		DECLARE @OtherExpensePay DECIMAL(20,4);
		DECLARE @OtherExpenseTotal DECIMAL(20,4);

		SELECT @OtherExpense = Total,
			   @OtherExpensePay = [Used],
			   @OtherExpenseTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'OtherExpenses';

		--เงินวางประกัน
		DECLARE @InitialMargin DECIMAL(20,4);
		DECLARE @InitialMarginPay DECIMAL(20,4);
		DECLARE @InitialMarginTotal DECIMAL(20,4);

		SELECT @InitialMargin = Total,
			   @InitialMarginPay = [Used],
			   @InitialMarginTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'InitialMargin';

		set @AccruedInterestPay = @DefaultInterestPay + @PlannedInterestPay
		set @AccruedInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal
		--อัปเดต รายการรับชำระ
		UPDATE DCM
		SET 
			DCM.PrincipalPay = @PrincipalPay,
			DCM.PrincipalTotal = @PrincipalTotal,
			--ตามแผน
			DCM.PlannedInterestPay =  @PlannedInterestPay,
			DCM.PlannedInterestTotal =  @PlannedInterestTotal,
			--ผิดนัด
			DCM.DefaultInterestPay = @DefaultInterestPay,
			DCM.DefaultInterestTotal = @DefaultInterestTotal,
			--ค้างรับ
			DCM.AccruedInterestPay = @DefaultInterestPay + @PlannedInterestPay,
			DCM.AccruedInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
			--ค่างวด
			DCM.Installment = @PrincipalTotal,
			DCM.InstallmentPrincipal = @PrincipalTotal,
			DCM.InstallmentPrincipalTotal = @PrincipalTotal,
			DCM.InstallmentInterest = @DefaultInterestTotal + @PlannedInterestTotal,
			DCM.InstallmentInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
			--ค่าธรรมเนียมศาล
			DCM.CourtFee = @CourtFee,
			DCM.CourtFeePay = @CourtFeePay,
			DCM.CourtFeeTotal = @CourtFeeTotal,
			--ค่าทนาย
			DCM.LawyerFee = @LawyerFee,
			DCM.LawyerFeePay = @LawyerFeePay,
			DCM.LawyerFeeTotal = @LawyerFeeTotal,
			--ค่าใช้จ่ายอื่น
			DCM.OtherExpense = @OtherExpense,
			DCM.OtherExpensePay = @OtherExpensePay,
			DCM.OtherExpenseTotal = @OtherExpenseTotal,
			--เงินวางประกัน
			DCM.InitialMargin = @InitialMargin,
			DCM.InitialMarginPay = @InitialMarginPay,
			DCM.InitialMarginTotal = @InitialMarginTotal,
			-- ยอดรับชำระ
			DCM.ReceivePayment = @Amount
		FROM DataDebtorCardMovement DCM
		LEFT JOIN DataDebtorCard DDC ON DDC.DataDebtorCardId = DCM.DebtorCardId
		WHERE DCM.DebtorCardId = @DataDebtorCardId 
		  AND DCM.SeqNo = @SeqCurrent;

		UPDATE DCM2
		SET DebtBalance = DCM2.PrincipalTotal + DCM2.AccruedInterestTotal
		FROM DataDebtorCardMovement DCM2
		LEFT JOIN DataDebtorCard DDC ON DDC.DataDebtorCardId = DCM2.DebtorCardId
		WHERE DCM2.DebtorCardId = @DataDebtorCardId 
		  AND DCM2.SeqNo = @SeqCurrent;

		Update DataDebtorCard
		set InterestStartDate = @GetDate,
			CourtFeeTotal = @CourtFeeTotal,
			LawyerFeeTotal = @LawyerFeeTotal,
			OtherExpenseTotal = @OtherExpenseTotal,
			InitialMarginTotal = @InitialMarginTotal,
			DebtBalance = isnull(@PrincipalTotal,0) + isnull(@PlannedInterestTotal,0) + isnull(@DefaultInterestTotal,0),
			PrincipalTotal = @PrincipalTotal,
			PlannedInterestTotal = @PlannedInterestTotal,
			DefaultInterestTotal = @DefaultInterestTotal,
			AccruedInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal,
			InstallmentPrincipal = @PrincipalTotal,
			InstallmentPrincipalTotal = @PrincipalTotal,
			InstallmentInterest = @PlannedInterestTotal + @DefaultInterestTotal,
			InstallmentInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal
		WHERE DataDebtorCardId = @DataDebtorCardId;
	
		declare @DefaultDate date = cast('1900-01-01' as date)
	
		--insert  ยอดคงเหลือ
		EXEC  [dbo].[SP_DCS_Card_003_InsertBalance] @GetDate, @DataDebtorCardId ,@IsAdjust , @AdjustDate
		EXEC  [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay] @GetDate, @DataDebtorCardId ,@IsAdjust , @AdjustDate

		-- ถ้าเป็นการ์ดย่อย และ จ่ายเงินต้น ให้นำเงินไปตัดการ์ดหลัก
		if (@PrincipalPay > 0 and @DebtorTypeId != 1)
		begin
			EXEC [SP_DCS_Card_008_UpdateDataDebtorCardSubToMain] @GetDate, @PrincipalPay , @DataDebtorCardId, @LGNo;
		end

		-- ✳✳✳ จุดที่ 1 ที่แก้: เติม SELECT ให้ Insert into CalDataDebtorCard ✳✳✳
		INSERT INTO CalDataDebtorCard(
			UpdateDate,
			DataDebtorCardId,
			EStatementId,
			PaymentDate,
			AmountEStatement,
			PrincipalPay,
			RowNum,
			Seq,
			PaymentSeqTypeId,
			KeyName,
			LookUpValue,
			BFAmount,
			PayableAmount,
			UpdateAmount,
			Used,
			Total
		)
		SELECT 
			GETDATE()               AS UpdateDate,
			@DataDebtorCardId       AS DataDebtorCardId,
			@EStatementId           AS EStatementId,
			@GetDate                AS PaymentDate,
			@Amount                 AS AmountEStatement,
			@PrincipalPay           AS PrincipalPay,
			RowNum,
			Seq,
			PaymentSeqTypeId,
			KeyName,
			LookUpValue,
			BFAmount,
			PayableAmount,
			UpdateAmount,
			Used,
			Total
		FROM #tmpFinal;

		-- ✳✳✳ จุดที่ 2 ที่แก้: เรียก 039 แบบส่ง @CallerHandlesTxn = 1 ✳✳✳
		EXEC dbo.SP_DCS_039_InsertReceipt
			 @SystemId                      = 4,
			 @DocumentId                    = 9,
			 @DebtorCardId                  = @DataDebtorCardId,
			 @ReceiptDate                   = @GetDate,
			 @CreateBy                      = 1,
			 @AccountUserId                 = 1,
			 @DebtorPaymentName             = @DebtorPaymentName,
			 @PaymentAmount                 = @Amount,
			 @PrincipalPay                  = @PrincipalPay,
			 @AccruedInterestPay            = @AccruedInterestPay,
			 @CourtFeePay                   = @CourtFeePay,
			 @LawyerFeePay                  = @LawyerFeePay,
			 @OtherExpensePay               = @OtherExpensePay,
			 @InitialMarginPay              = @InitialMarginPay,
			 @CourtFeeTotal                 = @CourtFeeTotal,
			 @LawyerFeeTotal                = @LawyerFeeTotal,
			 @OtherExpenseTotal             = @OtherExpenseTotal,
			 @InitialMarginTotal            = @InitialMarginTotal,
			 @SuspendIntTotal               = @SuspendIntTotal,
			 @DeferredInterestTotal         = @DeferredInterestTotal,
			 @SuspendedDefaultInterestTotal = @SuspendedDefaultInterestTotal,
			 @PlannedInterestTotal          = @PlannedInterestTotal,
			 @DefaultInterestTotal          = @DefaultInterestTotal,
			 @EStatementId                  = @EStatementId,
			 @AccruedInterestTotal          = @AccruedInterestTotal,
			 @SeqCurrent                    = @SeqCurrent;
		--     @CallerHandlesTxn              = 1; -- บอก 039 ว่าตัวนี้คุม txn เอง

		-- select เดิมของคุณ เอาไว้ดูผล
		SELECT 
			GETDATE() as UpdateDate,
			@DataDebtorCardId as DataDebtorCardId,
			@EStatementId as EStatementId,
			@GetDate as PaymentDate,
			@Amount as AmountEStatement,
			@PrincipalPay as PrincipalPay,
			RowNum,
			Seq,
			PaymentSeqTypeId,
			KeyName,
			LookUpValue,
			BFAmount,
			PayableAmount,
			UpdateAmount,
			Used,
			Total
		FROM #tmpFinal;

		
	Update DataEStatement
	set IsConfirm = 1
	, IsCheck = 1
	where EStatementId = @EStatementId;

	end


	else if (@CheckDefaultMeasureId !=1)
	begin
		exec dbo.[SP_DCS_Card_006_InsertDebtorCard_Horizontal] 
		@DataDebtorCardId
		,@EStatementId
	end
END

create PROCEDURE [dbo].[SP_DCS_Card_006_InsertDebtorCard_ForRecal]
	@DataDebtorCardId nvarchar(150) = '3AED03CC-5299-4B48-97C4-E55F7F7A80DF',
	@EStatementId nvarchar(150) = '347634F6-C48B-4943-8A33-979BB4287147',
	@IsUpfront bit = 0, --0= มาตการทั่วไป, 1=Upfront
	@IsAdjust int = 0, --0 = รายการปกติ, 1=รายการที่ต้องปรับปรุง
	@AdjustDate date = '2025-12-01' --วันที่ปรับปรุง

	,@MeasureId int = 1
	,@InterestDate int = 0
	,@DaysInYear int = 1
	,@Principal decimal(20,2) = 0
	,@SeqCurrent int = 0
AS
BEGIN
    --SET NOCOUNT ON;

	DECLARE @Amount DECIMAL(20,6);
	DECLARE @GetDate datetime;

    DECLARE @IDCard NVARCHAR(20);
    DECLARE @LGNo NVARCHAR(20);
	DECLARE @AccruedInterestTotal DECIMAL(20,4) = 0
	DECLARE @DebtorTypeId INT;
	DECLARE @DebtorId nvarchar(150);
	DECLARE @PaymentDate DATETIME;
	DECLARE @UpfrontPaymentSeq int = 737
	DECLARE @DebtorPaymentName NVARCHAR(200) = N''
	DECLARE @CompromiseContractId nvarchar(150) 
    DECLARE @InterestRate DECIMAL(20,6) = 0

	DECLARE @AccruedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยค้างรับ งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendInt DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพักใหม่(แขวน) งวดปัจจุบัน + งวดค้าง
	DECLARE @DeferredInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตั้งพัก งวดปัจจุบัน + งวดค้าง
	DECLARE @SuspendedDefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยแขวนผิดนัด งวดปัจจุบัน + งวดค้าง
	DECLARE @PlannedInterest DECIMAL(20,6) = 0 --ดอกเบี้ยตามแผน งวดปัจจุบัน + งวดค้าง
	DECLARE @DefaultInterest DECIMAL(20,6) = 0 --ดอกเบี้ยผิดนัด งวดปัจจุบัน + งวดค้าง
	DECLARE @CheckDefaultMeasureId int = 0 

	-- ✅ เพิ่ม: ตัวแปรเก็บเงินเกิน
	DECLARE @OverPayment DECIMAL(20,6) = 0;



	set @CheckDefaultMeasureId = (select top 1 IsDefault from SystemMeasureMaster where MeasureId = @MeasureId)

if(@CheckDefaultMeasureId = 1)
begin
	--=====ดึงข้อมูลจาก DataEStatement
		SELECT
			@Amount = Amount,
			@GetDate = PaymentDate,
			@IDCard = Reference1,
			@LGNo = Reference2,
			@DebtorPaymentName = CustomerName
		FROM DataEStatement WHERE EStatementId = @EStatementId;


    

		--=====ดึงข้อมูลจาก DataDebtorCard
		--SELECT
		--	@SeqCurrent = SeqCurrent
		--	,@DebtorTypeId = DebtorRelateTypeId
		--	,@DebtorId = DebtorId
		--	,@MeasureId = MeasureId --มาตรการ
		--	,@CompromiseContractId = CompromiseContractId
		--	,@Principal = PrincipalTotal 
		--, @InterestRate = InterestRate / 100
		--FROM DataDebtorCard WHERE DataDebtorCardId = @DataDebtorCardId;





		DECLARE @DebtorCardMovementIdMax nvarchar(150) = (
			SELECT TOP 1 DebtorCardMovementId
			FROM DataDebtorCardMovement
			WHERE DebtorId = @DebtorId
			ORDER BY SeqNo DESC
		);


	   --=====ดึงลำดับการตัดชำระ

    
		--ลำดับตัดชำระ ของมาตรการในการ์ด
		DECLARE @PaymentSeq INT = 
		(case when @IsUpfront = 1 then @UpfrontPaymentSeq else 
		( SELECT TOP 1 m.ConditionItemMapingValue
			FROM SystemConditionItemMappingValueMaster m
			LEFT JOIN SystemConditionMaster c ON m.ConditionId = c.ConditionId
			LEFT JOIN SystemCampaignConditionMaster cc ON cc.ConditionId = c.ConditionId
			LEFT JOIN SystemMeasureCampaignMaster cm ON cm.CampaignId = cc.CampaignId
			LEFT JOIN SystemMeasureMaster mm ON mm.MeasureId = cm.MeasureId
			WHERE mm.IsDefault = 1 AND m.ConditionItemId = 20
		)
		end);
	   --ประเภทการรับชำระ 1=แนวตั้ง, 15=แนวนอน
		DECLARE @PaymentSeqType INT = (select top 1 PaymentMethodId from SystemPaymentSeqMaster where PaymentSeqId = @PaymentSeq)
  
	   --=====หาจำนวนวัน ในปีที่คิดดอกเบี้ย (365 วัน หรือ 366 วัน)
		

		DECLARE @Interest DECIMAL(20,6) = @Principal * @InterestRate * @InterestDate / @DaysInYear;

		-- เตรียม temp table
		IF OBJECT_ID('tempdb..#tmp') IS NOT NULL DROP TABLE #tmp;

	   --=====ตัดชำระ ตามลำดับ
		-- ✅ แก้: คุม PayableAmount ของ Principal ไม่ให้เกิน PrincipalTotal ที่เหลือ (@Principal)
		SELECT 
			ROW_NUMBER() OVER (ORDER BY sd.Seq) AS RowNum,
			sd.Seq,
			sd.PaymentSeqTypeId,
			l.KeyName,
			l.LookUpValue,

			CAST(
				CASE 
					WHEN l.KeyName = 'Principal'
						THEN CASE WHEN x.RawPayable > ISNULL(@Principal,0) THEN ISNULL(@Principal,0) ELSE x.RawPayable END
					ELSE x.RawPayable
				END
			AS DECIMAL(20,6)) AS PayableAmount,

			CAST(0.0 AS DECIMAL(20,6)) AS BFAmount,
			CAST(0.0 AS DECIMAL(20,6)) AS UpdateAmount
		INTO #tmp
		FROM SystemPaymentSeqDetailMaster sd
		LEFT JOIN SystemPaymentSeqMaster s ON s.PaymentSeqId = sd.PaymentSeqId
		LEFT JOIN SystemLookupMaster l ON l.LookupId = sd.PaymentSeqTypeId
		CROSS APPLY (
			SELECT CAST(
				CASE WHEN sd.UnitValuesId = 94 
					 THEN dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName) * (sd.[Values]/100)
					 ELSE dbo.[FN_DCS_02_PayableAmount](@DataDebtorCardId, l.KeyName)
				END
			AS DECIMAL(20,6)) AS RawPayable
		) x
		WHERE s.PaymentSeqId = @PaymentSeq;

		-- วนลูปเพื่อคำนวณและอัปเดต UpdateAmount
		DECLARE @Row INT = 1, @MaxRow INT;
		SELECT @MaxRow = MAX(RowNum) FROM #tmp;

		WHILE @Row <= @MaxRow
		BEGIN
			DECLARE @Payable DECIMAL(20,6), @Update DECIMAL(20,6), @PrevUpdate DECIMAL(20,6);
			SELECT @Payable = PayableAmount FROM #tmp WHERE RowNum = @Row;

			IF @Row = 1
			BEGIN
				UPDATE #tmp SET BFAmount = @Amount WHERE RowNum = 1;
				SET @Update = CASE WHEN @Amount >= @Payable THEN @Amount - @Payable ELSE 0 END;
			END
			ELSE
			BEGIN
				SELECT @PrevUpdate = UpdateAmount FROM #tmp WHERE RowNum = @Row - 1;
				UPDATE #tmp SET BFAmount = @PrevUpdate WHERE RowNum = @Row;
				SET @Update = CASE WHEN @PrevUpdate >= @Payable THEN @PrevUpdate - @Payable ELSE 0 END;
			END

			UPDATE #tmp SET UpdateAmount = @Update WHERE RowNum = @Row;
			SET @Row += 1;
		END

		-- ✅ เพิ่ม: เงินเหลือหลังตัดตามลำดับทั้งหมด -> เก็บเป็น OverPayment
		SELECT @OverPayment = UpdateAmount
		FROM #tmp
		WHERE RowNum = (SELECT MAX(RowNum) FROM #tmp);

		-- debug 
		select * from #tmp;

		SELECT *
		, PayableAmount - (CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END) AS Used
		, CASE WHEN PayableAmount <= BFAmount THEN 0 ELSE PayableAmount - BFAmount END AS Total
		INTO #tmpFinal
		FROM #tmp;

		declare @PrincipalPay decimal(20,4);
		declare @PrincipalTotal decimal(20,4);

		declare @DefaultInterestPay decimal(20,4);
		declare @DefaultInterestTotal decimal(20,4);

		declare @AccruedInterestPay decimal(20,4); 
		--declare @AccruedInterestTotal decimal(20,4); 

		declare @PlannedInterestPay decimal(20,4);
		declare @PlannedInterestTotal decimal(20,4);
		declare @SuspendIntTotal decimal(20,4) = 0;
		declare @DeferredInterestTotal decimal(20,4) = 0;
		declare @SuspendedDefaultInterestTotal decimal(20,4) = 0;

		--ดึงเงินต้น
		SELECT @PrincipalPay = [Used],
			   @PrincipalTotal = Total
		FROM #tmpFinal WHERE KeyName = 'Principal';

		--ดึงดอกเบี้ยผิดนัด
		SELECT @DefaultInterestPay = [Used],
			   @DefaultInterestTotal = Total
		FROM #tmpFinal WHERE KeyName = 'DefaultInterest';

		--ดึงดอกเบี้ยตามแผน
		SELECT @PlannedInterestPay = [Used],
			   @PlannedInterestTotal = Total
		FROM #tmpFinal WHERE KeyName = 'PlannedInterest';

		--ค่าธรรมเนียมศาล
		DECLARE @CourtFee DECIMAL(20,4);
		DECLARE @CourtFeePay DECIMAL(20,4);
		DECLARE @CourtFeeTotal DECIMAL(20,4);

		SELECT @CourtFee = Total,
			   @CourtFeePay = [Used],
			   @CourtFeeTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'CourtFee';

		--ค่าทนาย
		DECLARE @LawyerFee DECIMAL(20,4);
		DECLARE @LawyerFeePay DECIMAL(20,4);
		DECLARE @LawyerFeeTotal DECIMAL(20,4);

		SELECT @LawyerFee = Total,
			   @LawyerFeePay = [Used],
			   @LawyerFeeTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'LawyerFee';
	
		--ค่าใช้จ่ายอื่น
		DECLARE @OtherExpense DECIMAL(20,4);
		DECLARE @OtherExpensePay DECIMAL(20,4);
		DECLARE @OtherExpenseTotal DECIMAL(20,4);

		SELECT @OtherExpense = Total,
			   @OtherExpensePay = [Used],
			   @OtherExpenseTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'OtherExpenses';

		--เงินวางประกัน
		DECLARE @InitialMargin DECIMAL(20,4);
		DECLARE @InitialMarginPay DECIMAL(20,4);
		DECLARE @InitialMarginTotal DECIMAL(20,4);

		SELECT @InitialMargin = Total,
			   @InitialMarginPay = [Used],
			   @InitialMarginTotal= Total
		FROM #tmpFinal 
		WHERE KeyName = 'InitialMargin';

		set @AccruedInterestPay = @DefaultInterestPay + @PlannedInterestPay
		set @AccruedInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal
		--อัปเดต รายการรับชำระ
		UPDATE DCM
		SET 
			DCM.PrincipalPay = @PrincipalPay,
			DCM.PrincipalTotal = @PrincipalTotal,
			--ตามแผน
			DCM.PlannedInterestPay =  @PlannedInterestPay,
			DCM.PlannedInterestTotal =  @PlannedInterestTotal,
			--ผิดนัด
			DCM.DefaultInterestPay = @DefaultInterestPay,
			DCM.DefaultInterestTotal = @DefaultInterestTotal,
			--ค้างรับ
			DCM.AccruedInterestPay = @DefaultInterestPay + @PlannedInterestPay,
			DCM.AccruedInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
			--ค่างวด
			DCM.Installment = @PrincipalTotal,
			DCM.InstallmentPrincipal = @PrincipalTotal,
			DCM.InstallmentPrincipalTotal = @PrincipalTotal,
			DCM.InstallmentInterest = @DefaultInterestTotal + @PlannedInterestTotal,
			DCM.InstallmentInterestTotal = @DefaultInterestTotal + @PlannedInterestTotal,
			--ค่าธรรมเนียมศาล
			DCM.CourtFee = @CourtFee,
			DCM.CourtFeePay = @CourtFeePay,
			DCM.CourtFeeTotal = @CourtFeeTotal,
			--ค่าทนาย
			DCM.LawyerFee = @LawyerFee,
			DCM.LawyerFeePay = @LawyerFeePay,
			DCM.LawyerFeeTotal = @LawyerFeeTotal,
			--ค่าใช้จ่ายอื่น
			DCM.OtherExpense = @OtherExpense,
			DCM.OtherExpensePay = @OtherExpensePay,
			DCM.OtherExpenseTotal = @OtherExpenseTotal,
			--เงินวางประกัน
			DCM.InitialMargin = @InitialMargin,
			DCM.InitialMarginPay = @InitialMarginPay,
			DCM.InitialMarginTotal = @InitialMarginTotal,
			-- ยอดรับชำระ
			DCM.ReceivePayment = @Amount
		FROM TDRDataCompromiseContractRecalCard DCM
		WHERE DCM.DebtorCardId = @DataDebtorCardId 
		  AND DCM.SeqNo = @SeqCurrent;

		UPDATE DCM2
		SET DebtBalance = DCM2.PrincipalTotal + DCM2.AccruedInterestTotal
		FROM TDRDataCompromiseContractRecalCard DCM2
		LEFT JOIN DataDebtorCard DDC ON DDC.DataDebtorCardId = DCM2.DebtorCardId
		WHERE DCM2.DebtorCardId = @DataDebtorCardId 
		  AND DCM2.SeqNo = @SeqCurrent;

		--Update DataDebtorCard
		--set InterestStartDate = @GetDate,
		--	CourtFeeTotal = @CourtFeeTotal,
		--	LawyerFeeTotal = @LawyerFeeTotal,
		--	OtherExpenseTotal = @OtherExpenseTotal,
		--	InitialMarginTotal = @InitialMarginTotal,
		--	DebtBalance = isnull(@PrincipalTotal,0) + isnull(@PlannedInterestTotal,0) + isnull(@DefaultInterestTotal,0),
		--	PrincipalTotal = @PrincipalTotal,
		--	PlannedInterestTotal = @PlannedInterestTotal,
		--	DefaultInterestTotal = @DefaultInterestTotal,
		--	AccruedInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal,
		--	InstallmentPrincipal = @PrincipalTotal,
		--	InstallmentPrincipalTotal = @PrincipalTotal,
		--	InstallmentInterest = @PlannedInterestTotal + @DefaultInterestTotal,
		--	InstallmentInterestTotal = @PlannedInterestTotal + @DefaultInterestTotal
		--WHERE DataDebtorCardId = @DataDebtorCardId;

		-- ✅ เพิ่ม: เก็บเงินเกินเข้า DataDebtorCard.OverPayment
		--IF (@OverPayment > 0)
		--BEGIN
		--	UPDATE DataDebtorCard
		--	SET OverPayment = ISNULL(OverPayment,0) + @OverPayment
		--	WHERE DataDebtorCardId = @DataDebtorCardId;
		--END
	
		declare @DefaultDate date = cast('1900-01-01' as date)
	
		--insert  ยอดคงเหลือ
		--EXEC  [dbo].[SP_DCS_Card_003_InsertBalance] @GetDate, @DataDebtorCardId ,@IsAdjust , @AdjustDate
		--EXEC  [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay] @GetDate, @DataDebtorCardId ,@IsAdjust , @AdjustDate

		-- ถ้าเป็นการ์ดย่อย และ จ่ายเงินต้น ให้นำเงินไปตัดการ์ดหลัก
		--if (@PrincipalPay > 0 and @DebtorTypeId != 1)
		--begin
		--	EXEC [SP_DCS_Card_008_UpdateDataDebtorCardSubToMain] @GetDate, @PrincipalPay , @DataDebtorCardId, @LGNo;
		--end

		-- ✳✳✳ จุดที่ 1 ที่แก้: เติม SELECT ให้ Insert into CalDataDebtorCard ✳✳✳
		--INSERT INTO CalDataDebtorCard(
		--	UpdateDate,
		--	DataDebtorCardId,
		--	EStatementId,
		--	PaymentDate,
		--	AmountEStatement,
		--	PrincipalPay,
		--	RowNum,
		--	Seq,
		--	PaymentSeqTypeId,
		--	KeyName,
		--	LookUpValue,
		--	BFAmount,
		--	PayableAmount,
		--	UpdateAmount,
		--	Used,
		--	Total
		--)
		--SELECT 
		--	GETDATE()               AS UpdateDate,
		--	@DataDebtorCardId       AS DataDebtorCardId,
		--	@EStatementId           AS EStatementId,
		--	@GetDate                AS PaymentDate,
		--	@Amount                 AS AmountEStatement,
		--	@PrincipalPay           AS PrincipalPay,
		--	RowNum,
		--	Seq,
		--	PaymentSeqTypeId,
		--	KeyName,
		--	LookUpValue,
		--	BFAmount,
		--	PayableAmount,
		--	UpdateAmount,
		--	Used,
		--	Total
		--FROM #tmpFinal;

		-- ✳✳✳ จุดที่ 2 ที่แก้: เรียก 039 แบบส่ง @CallerHandlesTxn = 1 ✳✳✳
		EXEC dbo.SP_DCS_039_InsertReceipt
			 @SystemId                      = 4,
			 @DocumentId                    = 9,
			 @DebtorCardId                  = @DataDebtorCardId,
			 @ReceiptDate                   = @GetDate,
			 @CreateBy                      = 1,
			 @AccountUserId                 = 1,
			 @DebtorPaymentName             = @DebtorPaymentName,
			 @PaymentAmount                 = @Amount,
			 @PrincipalPay                  = @PrincipalPay,
			 @AccruedInterestPay            = @AccruedInterestPay,
			 @CourtFeePay                   = @CourtFeePay,
			 @LawyerFeePay                  = @LawyerFeePay,
			 @OtherExpensePay               = @OtherExpensePay,
			 @InitialMarginPay              = @InitialMarginPay,
			 @CourtFeeTotal                 = @CourtFeeTotal,
			 @LawyerFeeTotal                = @LawyerFeeTotal,
			 @OtherExpenseTotal             = @OtherExpenseTotal,
			 @InitialMarginTotal            = @InitialMarginTotal,
			 @SuspendIntTotal               = @SuspendIntTotal,
			 @DeferredInterestTotal         = @DeferredInterestTotal,
			 @SuspendedDefaultInterestTotal = @SuspendedDefaultInterestTotal,
			 @PlannedInterestTotal          = @PlannedInterestTotal,
			 @DefaultInterestTotal          = @DefaultInterestTotal,
			 @EStatementId                  = @EStatementId,
			 @AccruedInterestTotal          = @AccruedInterestTotal,
			 @SeqCurrent                    = @SeqCurrent;
		--     @CallerHandlesTxn              = 1; -- บอก 039 ว่าตัวนี้คุม txn เอง

		-- ✅ เพิ่ม: ถ้าต้อง “รันสโตตัวต่อไป” เมื่อมีเงินเกิน ให้ใส่ EXEC ตรงนี้ (เปลี่ยนชื่อสโตเอง)
		/*
		IF (@OverPayment > 0)
		BEGIN
			EXEC dbo.SP_DCS_Card_XXX_NextProcess
				 @DataDebtorCardId = @DataDebtorCardId,
				 @PaymentDate      = @GetDate,
				 @OverPayment      = @OverPayment;
		END
		*/

		-- select เดิมของคุณ เอาไว้ดูผล
		SELECT 
			GETDATE() as UpdateDate,
			@DataDebtorCardId as DataDebtorCardId,
			@EStatementId as EStatementId,
			@GetDate as PaymentDate,
			@Amount as AmountEStatement,
			@PrincipalPay as PrincipalPay,
			RowNum,
			Seq,
			PaymentSeqTypeId,
			KeyName,
			LookUpValue,
			BFAmount,
			PayableAmount,
			UpdateAmount,
			Used,
			Total
		FROM #tmpFinal;

		
	--Update DataEStatement
	--set IsConfirm = 1
	--, IsCheck = 1
	--where EStatementId = @EStatementId;

	end


	else if (@CheckDefaultMeasureId !=1)
	begin
		exec dbo.[SP_DCS_Card_006_InsertDebtorCard_Horizontal] 
		@DataDebtorCardId
		,@EStatementId
	end
END

CREATE PROCEDURE [dbo].[SP_DCS_Card_007_RunPaymentDebtorCardManual]
    @DataDebtorCardId NVARCHAR(150),
    @EStatementId NVARCHAR(150),
		@UserId int
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @GetDate DATE = cast(getdate() as date);
        DECLARE @Today DATE = @GetDate;
        DECLARE @Yesterday DATE = DATEADD(DAY, -1, @GetDate);
				DECLARE @MainCardId nvarchar(150)


        DECLARE @PaymentDate DATE;
        DECLARE @SeqCurrent INT;
        DECLARE @InterestEndDate DATE;

        SELECT
            @PaymentDate = CAST(e.PaymentDate AS DATE)
        FROM DataEStatement e WITH (UPDLOCK, HOLDLOCK)
        WHERE e.EStatementId = @EStatementId
          AND e.DebtorCardId = @DataDebtorCardId;

        SELECT
            @SeqCurrent = dc.SeqCurrent,
            @InterestEndDate = CAST(dc.InterestEndDate AS DATE),
						@MainCardId = dc.DataMainCardId
        FROM DataDebtorCard dc WITH (UPDLOCK, HOLDLOCK)
        WHERE dc.DataDebtorCardId = @DataDebtorCardId;

        ----------------------------------------------------------------------
        -- CASE 1: รับชำระตรงวัน
        ----------------------------------------------------------------------
        IF @PaymentDate = @GetDate
        BEGIN
            EXEC [dbo].[SP_DCS_Card_005_eStatement]
                @PaymentDate,
                @DataDebtorCardId,
                @EStatementId,
								@UserId

            EXEC [dbo].[SP_DCS_Card_006_InsertDebtorCard]
                @DataDebtorCardId,
                @EStatementId,
                0,
                0,
                @GetDate,
								@UserId
								
						 EXEC [dbo].SP_DCS_046_MergeDebtorMainCardMovement
						 2,
						 @MainCardId
				
        END

        ----------------------------------------------------------------------
        -- CASE 2: รับชำระย้อนหลัง
        ----------------------------------------------------------------------
        ELSE IF @PaymentDate < @GetDate
        BEGIN
            ------------------------------------------------------------------
            -- CASE 2.1: PaymentDate อยู่เดือนเดียวกับ InterestEndDate
            ------------------------------------------------------------------
            IF (
                MONTH(@PaymentDate) = MONTH(@InterestEndDate)
                AND YEAR(@PaymentDate) = YEAR(@InterestEndDate)
            )
            BEGIN
                DECLARE @PaymentBefore DATE = DATEADD(DAY, -1, @PaymentDate);

                EXEC [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay]
                    @PaymentBefore,
                    @DataDebtorCardId,
                    1,
                    @Today;

                EXEC [dbo].[SP_DCS_Card_005_eStatement]
                    @PaymentDate,
                    @DataDebtorCardId,
                    @EStatementId,
										@UserId;

                EXEC [dbo].[SP_DCS_Card_006_InsertDebtorCard]
                    @DataDebtorCardId,
                    @EStatementId,
                    0,
										0,
										@UserId;
									

                EXEC [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay]
                    @Yesterday,
                    @DataDebtorCardId;
										
								EXEC [dbo].SP_DCS_046_MergeDebtorMainCardMovement
                    2,
                    @MainCardId
            END

            ------------------------------------------------------------------
            -- CASE 2.2: PaymentDate เป็นเดือนก่อนหน้า InterestEndDate
            ------------------------------------------------------------------
            ELSE IF DATEDIFF(MONTH, @PaymentDate, @InterestEndDate) >= 1
            BEGIN
                DECLARE @EOEnd DATE = EOMONTH(@PaymentDate);
                DECLARE @FirstDateOfMonth DATE = DATEADD(DAY, 1, @EOEnd);
                DECLARE @SeqNoLast INT = 0;
                DECLARE @PaymentBefore2 DATE = DATEADD(DAY, -1, @PaymentDate);

                DELETE FROM DataDebtorCardMovement
                WHERE DebtorCardId = @DataDebtorCardId
                  AND SeqNo = @SeqCurrent;

                SELECT TOP 1
                    @SeqNoLast = cm.SeqNo
                FROM DataDebtorCardMovement cm
                WHERE cm.DebtorCardId = @DataDebtorCardId
                ORDER BY cm.SeqNo DESC;

                UPDATE cd
                SET
                    cd.PrincipalTotal = cm.PrincipalTotal,
                    cd.PlannedInterestTotal = cm.PlannedInterestTotal,
                    cd.DefaultInterestTotal = cm.DefaultInterestTotal,
                    cd.AccruedInterestTotal = cm.AccruedInterestTotal,
                    cd.DebtBalance = cm.DebtBalance,
                    cd.SeqCurrent = cm.SeqNo,
                    cd.SeqNext = cm.SeqNo + 1,
                    cd.InterestStartDate = cm.InterestStartDate,
                    cd.InterestEndDate = cm.InterestEndDate,
                    cd.InterestRate = cm.InterestRate,
                    cd.InterestPlannedRate = cm.InterestPlannedRate,
                    cd.InterestDefaultRate = cm.InterestDefaultRate
                FROM DataDebtorCard cd
                INNER JOIN DataDebtorCardMovement cm
                    ON cd.DataDebtorCardId = cm.DebtorCardId
                WHERE cm.DebtorCardId = @DataDebtorCardId
                  AND cm.SeqNo = @SeqNoLast;

                UPDATE cm
                SET
                    cm.TypeId = 8,
                    cm.TypeCode = '08',
                    cm.TypeName = N'ยอดคงเหลือ'
                FROM DataDebtorCardMovement cm
                INNER JOIN DataDebtorCard cd
                    ON cd.DataDebtorCardId = cm.DebtorCardId
                WHERE cm.DebtorCardId = @DataDebtorCardId
                  AND cm.SeqNo = cd.SeqCurrent;

                EXEC [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay]
                    @PaymentBefore2,
                    @DataDebtorCardId,
                    1,
                    @Today;

                EXEC [dbo].[SP_DCS_Card_005_eStatement]
                    @PaymentDate,
                    @DataDebtorCardId,
                    @EStatementId,
										@UserId;

                EXEC [dbo].[SP_DCS_Card_006_InsertDebtorCard]
                    @DataDebtorCardId,
                    @EStatementId,
                    0,
										0,
										@UserId;

                EXEC [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay]
                    @EOEnd,
                    @DataDebtorCardId;

                EXEC [dbo].[SP_DCS_Card_003_InsertBalance]
                    @FirstDateOfMonth,
                    @DataDebtorCardId,
                    1,
                    @GetDate;

                EXEC [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay]
                    @FirstDateOfMonth,
                    @DataDebtorCardId;

                EXEC [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay]
                    @Yesterday,
                    @DataDebtorCardId;
										
								EXEC [dbo].SP_DCS_046_MergeDebtorMainCardMovement
                    2,
                    @MainCardId;
            END
        END

        UPDATE DataEStatement
        SET IsConfirm = 1
        WHERE EStatementId = @EStatementId
          AND DebtorCardId = @DataDebtorCardId;

        COMMIT TRANSACTION;

        SELECT
            1 AS Result,
            N'ประมวลผลรับชำระแบบ Manual สำเร็จ' AS Message,
            @DataDebtorCardId AS DataDebtorCardId,
            @EStatementId AS EStatementId,
            @PaymentDate AS PaymentDate,
            @GetDate AS ProcessDate;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SELECT
            0 AS Result,
            ERROR_MESSAGE() AS Message,
            @DataDebtorCardId AS DataDebtorCardId,
            @EStatementId AS EStatementId,
            NULL AS PaymentDate,
            CAST(GETDATE() AS DATE) AS ProcessDate;
    END CATCH
END;

CREATE PROCEDURE [dbo].[SP_DCS_Card_008_RunPaymentDebtorCard_Horizontal]
(
      @GetDate      date          = NULL
    , @EStatementId nvarchar(150) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /*
        ปรับให้ประมวลผลทีละ 1 รายการต่อการ EXEC

        วิธีใช้งาน
        1) ให้ระบบหยิบรายการค้างรายการแรก:
           EXEC dbo.SP_DCS_Card_008_RunPaymentDebtorCard_Horizontal;

        2) ระบุวันที่ประมวลผล:
           EXEC dbo.SP_DCS_Card_008_RunPaymentDebtorCard_Horizontal
                @GetDate = '2026-08-02';

        3) ระบุ EStatement ที่ต้องการ:
           EXEC dbo.SP_DCS_Card_008_RunPaymentDebtorCard_Horizontal
                @GetDate = '2026-08-02',
                @EStatementId = N'ระบุ EStatementId';
    */

    SET @GetDate = ISNULL(@GetDate, CONVERT(date, GETDATE()));

    DECLARE @Yesterday date = DATEADD(day, -1, @GetDate);

    DECLARE
          @SelectedEStatementId nvarchar(150)
        , @DataDebtorCardId     nvarchar(150)
        , @PaymentDate          date
        , @Amount               decimal(20, 2)
        , @PaymentAmount        decimal(20, 2)
        , @InterestEndDate      date
        , @CountDPD             int
        , @CountUpfront         int
        , @PrincipalPay         decimal(20, 2) = 0
        , @AccruedInterestPay   decimal(20, 2) = 0
        , @PaymentBefore        date
        , @EOEnd                date
        , @FirstDateOfMonth     date
        , @SeqNoLast            int
        , @CurrentInstallmentId nvarchar(150)
        , @MinEndDate           date
        , @ResultMessage        nvarchar(500);

    BEGIN TRY
        BEGIN TRANSACTION;

        /*
            ล็อกรายการที่เลือกไว้จนกว่าจะประมวลผลเสร็จ
            READPAST ทำให้การรันพร้อมกันข้ามรายการที่ถูกล็อกอยู่
        */
        SELECT TOP (1)
              @SelectedEStatementId = CONVERT(nvarchar(150), ds.EStatementId)
            , @DataDebtorCardId     = CONVERT(nvarchar(150), ds.DebtorCardId)
            , @PaymentDate          = CONVERT(date, ds.PaymentDate)
            , @Amount               = ISNULL(ds.Amount, 0)
            , @PaymentAmount        = ISNULL(ds.Amount, 0)
        FROM DataEStatement ds WITH (UPDLOCK, READPAST, ROWLOCK)
        INNER JOIN DataDebtorCard ddc
            ON ddc.DataDebtorCardId = ds.DebtorCardId
        INNER JOIN SystemMeasureMaster smm
            ON smm.MeasureId = ddc.MeasureId
        WHERE CONVERT(date, ds.PaymentDate) <= @GetDate
          AND ds.IsConfirm = 0
          AND ds.IsCheck = 1
          AND smm.IsDefault = 0
          AND (
                @EStatementId IS NULL
                OR CONVERT(nvarchar(150), ds.EStatementId) = @EStatementId
              )
        ORDER BY
              CASE
                  WHEN CONVERT(date, ds.PaymentDate) = @GetDate THEN 0
                  ELSE 1
              END
            , CONVERT(date, ds.PaymentDate) ASC
            , ds.EStatementId ASC;

        IF @SelectedEStatementId IS NULL
        BEGIN
            COMMIT TRANSACTION;

            SELECT
                  CAST(0 AS bit) AS IsProcessed
                , N'ไม่พบรายการ DataEStatement ที่รอประมวลผล' AS Message
                , @EStatementId AS RequestedEStatementId
                , @GetDate AS ProcessDate;

            RETURN;
        END;

        SELECT
            @InterestEndDate = CONVERT(date, InterestEndDate)
        FROM DataDebtorCard
        WHERE DataDebtorCardId = @DataDebtorCardId;

        IF @InterestEndDate IS NULL
        BEGIN
            THROW 50001, N'ไม่พบ InterestEndDate ของ DataDebtorCard ที่เลือก', 1;
        END;

        /* งวดค้าง/งวดปกติที่ถึงวันชำระแล้ว */
        SELECT
              ROW_NUMBER() OVER (ORDER BY a.Seq ASC) AS RowId
            , a.*
        INTO #TempInstallment
        FROM TDRDataCompromiseContractInstallmentPlanPayment a
        WHERE a.IsPayment = 0
          AND a.DataDebtorCardId = @DataDebtorCardId
          AND CONVERT(date, a.StartDate) <= @PaymentDate
          AND a.IsUpfront = 0;

        SET @CountDPD = (SELECT COUNT(1) FROM #TempInstallment);

        /* งวดเงิน Upfront */
        SELECT
              ROW_NUMBER() OVER (ORDER BY a.Seq ASC) AS RowId
            , a.*
            , b.UpfrontAmount
        INTO #TempUpfront
        FROM TDRDataCompromiseContractInstallmentPlanPayment a
        INNER JOIN TDRDataCompromiseContract b
            ON b.CompromiseContractId = a.CompromiseContractId
        WHERE a.DataDebtorCardId = @DataDebtorCardId
          AND a.IsPayment = 0
          AND a.IsUpfront = 1;

        SET @CountUpfront = (SELECT COUNT(1) FROM #TempUpfront);

        /*
            เดิมใช้ DAY <= แล้วตามด้วย DAY = ทำให้เงื่อนไข DAY = ไม่มีทางเข้า
            ปรับเป็นเปรียบเทียบวันที่ชัดเจน
        */
        IF EOMONTH(@PaymentDate) = EOMONTH(@InterestEndDate)
           AND @PaymentDate < @InterestEndDate
        BEGIN
            SET @PaymentBefore = DATEADD(day, -1, @PaymentDate);

            EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
                  @PaymentBefore
                , @DataDebtorCardId
                , 1
                , @GetDate;

            EXEC dbo.SP_DCS_Card_005_eStatement
                  @PaymentDate
                , @DataDebtorCardId
                , @SelectedEStatementId;

            EXEC dbo.SP_DCS_Card_006_InsertDebtorCard_Horizontal
                  @DataDebtorCardId
                , @SelectedEStatementId
                , 0
                , 0
                , @GetDate
                , 1
                , 0;

            EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
                  @Yesterday
                , @DataDebtorCardId;
        END
        ELSE IF @PaymentDate = @InterestEndDate
        BEGIN
            EXEC dbo.SP_DCS_Card_005_eStatement
                  @GetDate
                , @DataDebtorCardId
                , @SelectedEStatementId;

            EXEC dbo.SP_DCS_Card_006_InsertDebtorCard_Horizontal
                  @DataDebtorCardId
                , @SelectedEStatementId
                , 0
                , 0
                , @GetDate
                , 1
                , 0;

            EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
                  @Yesterday
                , @DataDebtorCardId;
        END
        ELSE IF EOMONTH(@PaymentDate) < EOMONTH(@InterestEndDate)
        BEGIN
            SET @EOEnd = EOMONTH(@PaymentDate);
            SET @FirstDateOfMonth = DATEADD(day, 1, @EOEnd);

            DELETE ddcm
            FROM DataDebtorCardMovement ddcm
            INNER JOIN DataDebtorCard ddc
                ON ddc.DataDebtorCardId = ddcm.DebtorCardId
            WHERE ddcm.DebtorCardId = @DataDebtorCardId
              AND ddcm.SeqNo = ddc.SeqCurrent;

            SET @SeqNoLast = NULL;

            SELECT TOP (1)
                @SeqNoLast = cm.SeqNo
            FROM DataDebtorCardMovement cm
            WHERE cm.DebtorCardId = @DataDebtorCardId
            ORDER BY cm.SeqNo DESC;

            IF @SeqNoLast IS NULL
            BEGIN
                THROW 50002, N'ไม่พบ DataDebtorCardMovement สำหรับย้อนยอดก่อนรับชำระ', 1;
            END;

            UPDATE cd
            SET
                  cd.PrincipalTotal        = cm.PrincipalTotal
                , cd.PlannedInterestTotal  = cm.PlannedInterestTotal
                , cd.DefaultInterestTotal  = cm.DefaultInterestTotal
                , cd.AccruedInterestTotal  = cm.AccruedInterestTotal
                , cd.DebtBalance           = cm.DebtBalance
                , cd.SeqCurrent            = cm.SeqNo
                , cd.SeqNext               = cm.SeqNo + 1
                , cd.InterestStartDate     = cm.InterestStartDate
                , cd.InterestEndDate       = cm.InterestEndDate
                , cd.InterestRate          = cm.InterestRate
                , cd.InterestPlannedRate   = cm.InterestPlannedRate
                , cd.InterestDefaultRate   = cm.InterestDefaultRate
            FROM DataDebtorCard cd
            INNER JOIN DataDebtorCardMovement cm
                ON cm.DebtorCardId = cd.DataDebtorCardId
               AND cm.SeqNo = @SeqNoLast
            WHERE cd.DataDebtorCardId = @DataDebtorCardId;

            UPDATE cm
            SET
                  cm.TypeId   = 8
                , cm.TypeCode = '08'
                , cm.TypeName = N'ยอดคงเหลือ'
            FROM DataDebtorCardMovement cm
            INNER JOIN DataDebtorCard cd
                ON cd.DataDebtorCardId = cm.DebtorCardId
               AND cd.SeqCurrent = cm.SeqNo
            WHERE cm.DebtorCardId = @DataDebtorCardId;

            SET @PaymentBefore = DATEADD(day, -1, @PaymentDate);

            EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
                  @PaymentBefore
                , @DataDebtorCardId
                , 1
                , @GetDate;

            EXEC dbo.SP_DCS_Card_005_eStatement
                  @PaymentDate
                , @DataDebtorCardId
                , @SelectedEStatementId;

            EXEC dbo.SP_DCS_Card_006_InsertDebtorCard_Horizontal
                  @DataDebtorCardId
                , @SelectedEStatementId
                , 0;

            EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
                  @EOEnd
                , @DataDebtorCardId;

            EXEC dbo.SP_DCS_Card_003_InsertBalance
                  @FirstDateOfMonth
                , @DataDebtorCardId
                , 1
                , @GetDate;

            EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
                  @FirstDateOfMonth
                , @DataDebtorCardId;

            EXEC dbo.SP_DCS_Card_002_UpdateInterestEveryDay_Horizontal
                  @Yesterday
                , @DataDebtorCardId;
        END
        ELSE
        BEGIN
            EXEC dbo.SP_DCS_Card_005_eStatement
                  @GetDate
                , @DataDebtorCardId
                , @SelectedEStatementId;

            IF @CountUpfront > 0
            BEGIN
                EXEC dbo.SP_DCS_Card_006_InsertDebtorCard_Horizontal
                      @DataDebtorCardId
                    , @SelectedEStatementId
                    , 1
                    , 0
                    , @GetDate
                    , 1
                    , 0;
            END
            ELSE
            BEGIN
                EXEC dbo.SP_DCS_Card_006_InsertDebtorCard_Horizontal
                      @DataDebtorCardId
                    , @SelectedEStatementId
                    , 0
                    , 0
                    , @GetDate
                    , 1
                    , 0;
            END;
        END;

        SELECT TOP (1)
              @PrincipalPay       = ISNULL(PrincipalPay, 0)
            , @AccruedInterestPay = ISNULL(AccruedInterestPay, 0)
        FROM DataDebtorCardMovement
        WHERE DebtorCardId = @DataDebtorCardId
          AND TypeId = 2
          AND IsAdjust = 0
        ORDER BY SeqNo DESC;

        /* บันทึกยอดชำระลงงวดที่ครอบคลุม PaymentDate เพียง 1 งวด */
        SELECT TOP (1)
            @CurrentInstallmentId =
                CONVERT(nvarchar(150), CompromiseContractInstallmentPlanPaymentId)
        FROM #TempInstallment
        WHERE CONVERT(date, StartDate) <= @PaymentDate
          AND CONVERT(date, EndDate) >= @PaymentDate
        ORDER BY Seq ASC;

        IF @CurrentInstallmentId IS NOT NULL
        BEGIN
            UPDATE TDRDataCompromiseContractInstallmentPlanPayment
            SET
                  PrincipalPay       = @PrincipalPay
                , AccruedInterestPay = @AccruedInterestPay
                , PaymentAmount      = @PaymentAmount
                , PaymentDate        = @PaymentDate
            WHERE CompromiseContractInstallmentPlanPaymentId = @CurrentInstallmentId;
        END;

        /* ตัดชำระงวดค้างทีละงวดตาม Seq */
        IF @CountDPD > 0
        BEGIN
            DECLARE
                  @j                   int = 1
                , @InstallmentId       nvarchar(150)
                , @OverdueAmount       decimal(20, 2)
                , @Total               decimal(20, 2)
                , @AmountRequired      decimal(20, 2);

            WHILE @j <= @CountDPD AND @Amount > 0
            BEGIN
                SELECT
                      @InstallmentId = CONVERT(nvarchar(150), CompromiseContractInstallmentPlanPaymentId)
                    , @OverdueAmount = ISNULL(OverdueAmount, 0)
                    , @Total         = ISNULL(Total, 0)
                FROM #TempInstallment
                WHERE RowId = @j;

                SET @AmountRequired =
                    CASE
                        WHEN @OverdueAmount > 0 THEN @OverdueAmount
                        ELSE @Total
                    END;

                IF @Amount >= @AmountRequired
                BEGIN
                    UPDATE TDRDataCompromiseContractInstallmentPlanPayment
                    SET
                          IsPayment    = 1
                        , OverdueAmount = 0
                    WHERE CompromiseContractInstallmentPlanPaymentId = @InstallmentId;

                    SET @Amount = @Amount - @AmountRequired;
                END
                ELSE
                BEGIN
                    UPDATE TDRDataCompromiseContractInstallmentPlanPayment
                    SET
                          IsPayment     = 0
                        , OverdueAmount = @AmountRequired - @Amount
                    WHERE CompromiseContractInstallmentPlanPaymentId = @InstallmentId;

                    SET @Amount = 0;
                END;

                SET @j += 1;
            END;

            /*
                ประเมิน DPD หลังตัดชำระครบแล้วเพียงครั้งเดียว
                ใช้เฉพาะงวดที่เริ่มแล้ว ณ PaymentDate เพื่อไม่ให้เอางวดอนาคตมาตั้ง DPD
            */
            SET @MinEndDate = NULL;

            SELECT TOP (1)
                @MinEndDate = CONVERT(date, EndDate)
            FROM TDRDataCompromiseContractInstallmentPlanPayment
            WHERE IsPayment = 0
              AND DataDebtorCardId = @DataDebtorCardId
              AND IsUpfront = 0
              AND CONVERT(date, StartDate) <= @PaymentDate
            ORDER BY Seq ASC;

            IF @MinEndDate IS NOT NULL
            BEGIN
                UPDATE DataDebtorCard
                SET
                      DPD     = 1
                    , DFDDate = DATEADD(day, 1, @MinEndDate)
                WHERE DataDebtorCardId = @DataDebtorCardId;
            END
            ELSE
            BEGIN
                UPDATE DataDebtorCard
                SET
                      DPD     = 0
                    , DFDDate = CONVERT(date, '19000101')
                WHERE DataDebtorCardId = @DataDebtorCardId;
            END;
        END
        ELSE IF @CountUpfront > 0
        BEGIN
            DECLARE
                  @UpfrontInstallmentId nvarchar(150)
                , @UpfrontAmount        decimal(20, 2)
                , @SumPaymentAmount     decimal(20, 2);

            SELECT TOP (1)
                  @UpfrontInstallmentId =
                      CONVERT(nvarchar(150), CompromiseContractInstallmentPlanPaymentId)
                , @UpfrontAmount = ISNULL(UpfrontAmount, 0)
            FROM #TempUpfront
            WHERE CONVERT(date, StartDate) <= @PaymentDate
              AND CONVERT(date, EndDate) >= @PaymentDate
            ORDER BY Seq ASC;

            IF @UpfrontInstallmentId IS NOT NULL
            BEGIN
                UPDATE TDRDataCompromiseContractInstallmentPlanPayment
                SET
                      PaymentAmount = ISNULL(PaymentAmount, 0) + @PaymentAmount
                    , PaymentDate   = @PaymentDate
                WHERE CompromiseContractInstallmentPlanPaymentId = @UpfrontInstallmentId;
            END;

            SELECT
                @SumPaymentAmount = ISNULL(SUM(ISNULL(PaymentAmount, 0)), 0)
            FROM TDRDataCompromiseContractInstallmentPlanPayment
            WHERE DataDebtorCardId = @DataDebtorCardId
              AND IsUpfront = 1;

            IF @SumPaymentAmount >= ISNULL(@UpfrontAmount, 0)
               AND ISNULL(@UpfrontAmount, 0) > 0
            BEGIN
                UPDATE TDRDataCompromiseContractInstallmentPlanPayment
                SET IsPayment = 1
                WHERE DataDebtorCardId = @DataDebtorCardId
                  AND IsUpfront = 1;
            END;
        END
        ELSE
        BEGIN
            DECLARE @NextInstallmentId nvarchar(150);

            SELECT TOP (1)
                @NextInstallmentId =
                    CONVERT(nvarchar(150), CompromiseContractInstallmentPlanPaymentId)
            FROM TDRDataCompromiseContractInstallmentPlanPayment
            WHERE DataDebtorCardId = @DataDebtorCardId
              AND IsPayment = 0
            ORDER BY Seq ASC;

            IF @NextInstallmentId IS NOT NULL
            BEGIN
                UPDATE TDRDataCompromiseContractInstallmentPlanPayment
                SET
                      IsPayment          = 1
                    , PaymentAmount      = @PaymentAmount
                    , PaymentDate        = @PaymentDate
                    , PrincipalPay       = @PrincipalPay
                    , AccruedInterestPay = @AccruedInterestPay
                WHERE CompromiseContractInstallmentPlanPaymentId = @NextInstallmentId;
            END;
        END;

        /* ยืนยันเฉพาะเมื่อทุกขั้นตอนของรายการนี้สำเร็จ */
        UPDATE DataEStatement
        SET IsConfirm = 1
        WHERE EStatementId = @SelectedEStatementId
          AND IsConfirm = 0;

        IF @@ROWCOUNT = 0
        BEGIN
            THROW 50003, N'ไม่สามารถอัปเดต IsConfirm ของ DataEStatement ได้', 1;
        END;

        COMMIT TRANSACTION;

        SELECT
              CAST(1 AS bit) AS IsProcessed
            , N'ประมวลผลสำเร็จ 1 รายการ' AS Message
            , @SelectedEStatementId AS EStatementId
            , @DataDebtorCardId AS DataDebtorCardId
            , @PaymentDate AS PaymentDate
            , @PaymentAmount AS PaymentAmount
            , @GetDate AS ProcessDate;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
        BEGIN
            ROLLBACK TRANSACTION;
        END;

        DECLARE
              @ErrorNumber    int            = ERROR_NUMBER()
            , @ErrorLine      int            = ERROR_LINE()
            , @ErrorProcedure nvarchar(128)  = ERROR_PROCEDURE()
            , @ErrorMessage   nvarchar(4000) = ERROR_MESSAGE();

        SELECT
              CAST(0 AS bit) AS IsProcessed
            , @SelectedEStatementId AS EStatementId
            , @DataDebtorCardId AS DataDebtorCardId
            , @ErrorNumber AS ErrorNumber
            , @ErrorLine AS ErrorLine
            , @ErrorProcedure AS ErrorProcedure
            , @ErrorMessage AS ErrorMessage;

        THROW;
    END CATCH;
END;

