CREATE PROCEDURE [dbo].[SP_DCS_Card_013_RunUpdateMainCardMovement]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @CurrentDate DATETIME = GETDATE(),
        @MainCardId UNIQUEIDENTIFIER,
        @DebtorCardId UNIQUEIDENTIFIER,
        @MeasureId INT,
        @InterestRate DECIMAL(20,4),
        @LGNo nvarchar(20);

    PRINT 'เริ่มรัน SP_DCS_Card_011_UpdateMainCardMovement สำหรับทุกการ์ด เวลา: '
        + CONVERT(VARCHAR(19), @CurrentDate, 120);

    -- ✅ เอาข้อมูลทั้งหมดจาก DataDebtorCard มาวน
    DECLARE cur CURSOR FAST_FORWARD FOR
        SELECT 
             DataMainCardId,
             DataDebtorCardId,
             MeasureId,
             InterestRate,
             LGNo
        FROM dbo.DataDebtorCard
        WHERE IsActive = 1
          AND DebtorRelateTypeId = 1;

    OPEN cur;
    FETCH NEXT FROM cur INTO @MainCardId, @DebtorCardId, @MeasureId, @InterestRate, @LGNo;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        BEGIN TRY
            -- ✅ รัน Update ทุกวัน
            EXEC dbo.SP_DCS_Card_011_UpdateMainCardMovement
                @CurrentDate = @CurrentDate,
                @MainCardId = @MainCardId,
                @DebtorCardId = @DebtorCardId,
                @MeasureId = @MeasureId,
                @InterestRate = @InterestRate,
                @LGNo = @LGNo;

        END TRY
        BEGIN CATCH
            PRINT '❌ Error DataDebtorCardId : ' + CAST(@DebtorCardId AS NVARCHAR(50))
                + ' | ' + ERROR_MESSAGE();
        END CATCH;

        FETCH NEXT FROM cur INTO @MainCardId, @DebtorCardId, @MeasureId, @InterestRate, @LGNo;
    END

    CLOSE cur;
    DEALLOCATE cur;

    PRINT ' เสร็จสิ้นการรันทั้งหมด เวลา: ' + CONVERT(VARCHAR(19), GETDATE(), 120);
END;

