create   PROCEDURE [dbo].[SP_DCS_Card_038_RevertCartApproved]
    @DebtorCardId NVARCHAR(150) = 'AD7ED4AA-22B9-4BAB-A114-D6ECE3B460FD-XXX',
    @RequestAdjustStatusId INT = 185 -- 185 = ส่งกลับแก้ไข, 190 = อยู่ระหว่างปรับปรุงการ์ด
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @AdjustStatusIdSendEdit INT = 185;
    DECLARE @AdjustStatusIdInProgress INT = 190;

    DECLARE @Today     DATE = CAST(GETDATE() AS DATE);
    DECLARE @Yesterday DATE = DATEADD(DAY, -1, @Today);

    -- ============================================================
    -- Block A: RequestAdjustStatusId = 185
    -- ============================================================
    IF @RequestAdjustStatusId = @AdjustStatusIdSendEdit
    BEGIN
        -- เก็บ AdjustDate จาก InterestStartDate แรกของแถวที่ CompromiseContractGroup = 1
        -- (ก่อน Delete เพื่อใช้ใน loop ภายหลัง)
        DECLARE @AdjustDate DATE;

        SELECT TOP 1
               @AdjustDate = InterestStartDate
        FROM   DataDebtorCardMovement
        WHERE  DebtorCardId        = @DebtorCardId
          AND  CompromiseContractGroup = 1
        ORDER BY SeqNo ASC;

        -- Step 1: ลบ DataDebtorCardMovement ที่ CompromiseContractGroup = 1
        --         โดย Join กับ ACCDataRequestAdjustCard ตาม DebtorCardId
        DELETE m
        FROM   DataDebtorCardMovement    m
        INNER JOIN ACCDataRequestAdjustCard a
               ON a.DebtorCardId = m.DebtorCardId
        WHERE  m.CompromiseContractGroup = 1
          AND  a.DebtorCardId            = @DebtorCardId;

        -- Step 2: หาบรรทัดสุดท้ายของ DataDebtorCardMovement (ORDER BY SeqNo DESC)
        --         แล้ว Update DataDebtorCard
        DECLARE @LastSeqNo             INT;
        DECLARE @LastInterestStartDate DATE;
        DECLARE @LastInterestEndDate   DATE;

        SELECT TOP 1
               @LastSeqNo             = SeqNo,
               @LastInterestStartDate = InterestStartDate,
               @LastInterestEndDate   = InterestEndDate
        FROM   DataDebtorCardMovement
        WHERE  DebtorCardId = @DebtorCardId
        ORDER BY SeqNo DESC;

        UPDATE DataDebtorCard
        SET    SeqCurrent        = @LastSeqNo,
               SeqNext           = @LastSeqNo + 1,
               InterestStartDate = @LastInterestStartDate,
               InterestEndDate   = @LastInterestEndDate
        WHERE  DataDebtorCardId  = @DebtorCardId;

        -- Step 3: รัน SP_ACC_Adjust_002_13_UpdateAdjust
        EXEC [dbo].[SP_ACC_Adjust_002_13_UpdateAdjust]
             @GetDate      = @Today,
             @DebtorCardId = @DebtorCardId,
             @CreateBy     = 1;

        -- Step 4: Loop รัน SP_DCS_Card_002_UpdateInterestEveryDay
        --         และ SP_DCS_Card_003_InsertBalance
        --         ทีละวัน จนกว่า InterestEndDate จะถึง (วันนี้ - 1 วัน)
        DECLARE @LoopDate DATE = DATEADD(DAY, 1, @LastInterestEndDate);

        WHILE @LoopDate <= @Yesterday
        BEGIN
            EXEC [dbo].[SP_DCS_Card_002_UpdateInterestEveryDay]
                 @CurrentDate      = @LoopDate,
                 @DataDebtorCardId = @DebtorCardId,
                 @IsAdjust         = 1,
                 @AdjustDate       = @AdjustDate;

            EXEC [dbo].[SP_DCS_Card_003_InsertBalance]
                 @CurrentDate      = @LoopDate,
                 @DataDebtorCardId = @DebtorCardId,
                 @IsAdjust         = 1,
                 @AdjustDate       = @AdjustDate;

            SET @LoopDate = DATEADD(DAY, 1, @LoopDate);
        END;

        -- Step 5: หา MainCardId จาก DataDebtorCard
        --         แล้วรัน SP_DCS_Card_011_UpdateMainCardMovement
        DECLARE @MainCardId NVARCHAR(150);

        SELECT @MainCardId = DataMainCardId
        FROM   DataDebtorCard
        WHERE  DataDebtorCardId = @DebtorCardId;

        EXEC [dbo].[SP_DCS_Card_011_UpdateMainCardMovement]
             @CurrentDate  = @Today,
             @MainCardId   = @MainCardId,
             @DebtorCardId = @DebtorCardId,
             @MeasureId    = 0,
             @InterestRate = 0,
             @LGNo         = N'';
    END

    -- ============================================================
    -- Block B: RequestAdjustStatusId = 190
    -- ============================================================
    ELSE IF @RequestAdjustStatusId = @AdjustStatusIdInProgress
    BEGIN
        UPDATE DataDebtorCardMovement
        SET    CompromiseContractGroup = NULL
        WHERE  DebtorCardId = @DebtorCardId;
    END

END;

/* REAL INSERT UAT CANDIDATE. Execute in UAT first. Requires *_Stage procedures
   installed from accompanying scripts. Not certified for all measures.
   @Commit=0 => full rollback after preview; @Commit=1 => actual INSERT/UPDATE.
   Important: this uses 041/042 staged calculations and master-driven receipt allocation.
*/
CREATE   PROCEDURE [dbo].[SP_DCS_Card_044_PostPayment_Real]
 @DataDebtorCardId NVARCHAR(150),
 @EStatementId NVARCHAR(150),
 @CreateBy INT = 1,
 @AccountUserId INT,
 @DebtorPaymentName NVARCHAR(200),
 @Commit BIT = 0
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @RunDocDate DATETIME = GETDATE();
 DECLARE
    @BaseSeq INT,
    @AdjustDate DATE,
    @ActualPayDate DATE,
    @ActualAmount DECIMAL(20,4),
    @ReceiptSeqCurrent INT;
 DECLARE @LockResult INT;
 DECLARE @ESDateColumn SYSNAME, @ESAmountColumn SYSNAME, @MapValueColumn SYSNAME;
 DECLARE @ESQuery NVARCHAR(MAX), @MapQuery NVARCHAR(MAX), @MapCount INT;
 -- Resolve actual schema names before using dynamic SQL; no silent fallback.
 SELECT TOP (1) @ESDateColumn=name FROM sys.columns
 WHERE object_id=OBJECT_ID(N'dbo.DataEStatement')
   AND name IN (N'PaymentDate',N'PayDate',N'DatePayment',N'TransactionDate',N'ValueDate')
 ORDER BY CASE name WHEN N'PaymentDate' THEN 1 WHEN N'PayDate' THEN 2 ELSE 3 END;
 SELECT TOP (1) @ESAmountColumn=name FROM sys.columns
 WHERE object_id=OBJECT_ID(N'dbo.DataEStatement')
   AND name IN (N'Amount',N'PaymentAmount',N'TotalAmount',N'TransactionAmount')
 ORDER BY CASE name WHEN N'Amount' THEN 1 ELSE 2 END;
 SELECT TOP (1) @MapValueColumn=name FROM sys.columns
 WHERE object_id=OBJECT_ID(N'dbo.SystemConditionItemMappingValueMaster')
   AND name IN (N'ConditionItemMappingValue',N'ConditionItemMapingValue')
 ORDER BY CASE name WHEN N'ConditionItemMappingValue' THEN 1 ELSE 2 END;
 IF @ESDateColumn IS NULL OR @ESAmountColumn IS NULL OR @MapValueColumn IS NULL
 BEGIN
   SELECT N'DataEStatement' AS TableName,name AS ColumnName FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.DataEStatement')
   UNION ALL SELECT N'SystemConditionItemMappingValueMaster',name FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.SystemConditionItemMappingValueMaster');
   THROW 54011,N'Could not identify EStatement date/amount or mapping value column. See column listing.',1;
 END;

 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @LockResource NVARCHAR(255);

SET @LockResource = N'PostPayment_' + @DataDebtorCardId;

EXEC @LockResult = sys.sp_getapplock
    @Resource = @LockResource,
    @LockMode = 'Exclusive',
    @LockOwner = 'Transaction',
    @LockTimeout = 10000;
  IF @LockResult<0 THROW 54001,N'Cannot acquire card lock',1;
  IF NOT EXISTS (SELECT 1 FROM dbo.DataDebtorCard WITH(UPDLOCK,HOLDLOCK) WHERE DataDebtorCardId=@DataDebtorCardId)
   THROW 54002,N'Card not found',1;
  IF EXISTS(SELECT 1 FROM dbo.DataDebtorCardMovement WHERE DebtorCardId=@DataDebtorCardId AND EStatementRef=@EStatementId AND TypeId=2)
   THROW 54003,N'eStatement already posted',1;
  SET @ESQuery=N'SELECT @d=TRY_CONVERT(DATE,'+QUOTENAME(@ESDateColumn)+N'),@a=TRY_CONVERT(DECIMAL(20,4),'+QUOTENAME(@ESAmountColumn)+N') FROM dbo.DataEStatement WHERE EStatementId=@id';
  EXEC sys.sp_executesql @ESQuery,N'@id NVARCHAR(150),@d DATE OUTPUT,@a DECIMAL(20,4) OUTPUT',@id=@EStatementId,@d=@ActualPayDate OUTPUT,@a=@ActualAmount OUTPUT;
  IF @ActualPayDate IS NULL OR @ActualAmount<=0 THROW 54004,N'Invalid EStatement',1;
  SELECT @BaseSeq=ISNULL(MAX(TRY_CONVERT(INT,SeqNo)),0) FROM dbo.DataDebtorCardMovement WITH(UPDLOCK,HOLDLOCK) WHERE DebtorCardId=@DataDebtorCardId;
  SELECT TOP(1) @AdjustDate=CONVERT(DATE,PayDate)
  FROM dbo.DataDebtorCardMovement WHERE DebtorCardId=@DataDebtorCardId AND TypeId=2
  ORDER BY TRY_CONVERT(INT,SeqNo) DESC;
  IF @AdjustDate IS NULL THROW 54005,N'No previous receipt movement',1;
  SELECT TOP(0) * INTO #TempMovement FROM dbo.DataDebtorCardMovement;
  -- Allow non-receipt movements after the last receipt. 041 reverses the
  -- post-receipt range, but stages its adjustment at @BaseSeq+1.
  IF EXISTS (SELECT 1 FROM dbo.DataDebtorCardMovement
             WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo) IS NULL)
     THROW 54007,N'Non-numeric movement sequence is unsupported',1;
  EXEC dbo.SP_DCS_Card_041_AdjustBeforePayment_Stage @DataDebtorCardId=@DataDebtorCardId,@CurrentDate=@AdjustDate;
  IF (SELECT COUNT(*) FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId
      AND TRY_CONVERT(INT,SeqNo)=@BaseSeq+1 AND TypeId=7)<>1
    THROW 54011,N'041 staged sequence mismatch',1;
  EXEC dbo.SP_DCS_Card_042_AdjustInterestBeforePayment_Stage @DataDebtorCardId=@DataDebtorCardId,@CurrentDate=@AdjustDate,@PaymentDate=@ActualPayDate,@CurrentPaymentAmount=@ActualAmount;
  IF (SELECT COUNT(*) FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TypeId=7)<>2
   THROW 54006,N'Expected two adjustment movements',1;
  -- Preserve accumulated DPD from the adjustment reversal; do not hardcode 78.
  UPDATE b SET DPDAccumulate=ISNULL(a.DPDAccumulate,0)*-1
  FROM #TempMovement b JOIN #TempMovement a ON a.DebtorCardId=b.DebtorCardId
  WHERE b.DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,b.SeqNo)=@BaseSeq+2 AND TRY_CONVERT(INT,a.SeqNo)=@BaseSeq+1;
  BEGIN
/* STEP 3: insert Seq61 into #TempMovement ONLY, update #TempInstallmentPlanPayment ONLY. */
SET NOCOUNT ON;
SET XACT_ABORT ON;

/*
  TEST ONLY. No permanent tables are modified.
  Execute in the SAME SSMS connection as steps 1 and 2 (#TempMovement).
  Master allocation is dynamic; interest calculation is an unverified approximation.
*/
-- @DataDebtorCardId supplied by caller
-- @EStatementId supplied by caller
DECLARE @PaymentDate DATE, @ReceiptAmount DECIMAL(19,2);
SET @PaymentDate=@ActualPayDate;
SET @ReceiptAmount=ROUND(@ActualAmount,2);
IF @PaymentDate IS NULL OR @ReceiptAmount IS NULL OR @ReceiptAmount<=0
    THROW 51020,N'EStatement not found or payment invalid',1;
DECLARE @MeasureId INT, @PaymentSeqId INT;
SELECT @MeasureId=MeasureId FROM dbo.DataDebtorCard WHERE DataDebtorCardId=@DataDebtorCardId;
SET @MapQuery=N'SELECT @val=MIN(TRY_CONVERT(INT,m.'+QUOTENAME('@PLACEHOLDER')+N')),
 @cnt=COUNT(DISTINCT TRY_CONVERT(INT,m.'+QUOTENAME('@PLACEHOLDER')+N'))
 FROM dbo.SystemConditionItemMappingValueMaster m
 JOIN dbo.SystemConditionMaster c ON c.ConditionId=m.ConditionId
 JOIN dbo.SystemCampaignConditionMaster cc ON cc.ConditionId=c.ConditionId
 JOIN dbo.SystemMeasureCampaignMaster cm ON cm.CampaignId=cc.CampaignId
 WHERE m.ConditionItemId=20 AND cm.MeasureId=@measure';
SET @MapQuery=REPLACE(@MapQuery,QUOTENAME('@PLACEHOLDER'),QUOTENAME(@MapValueColumn));
EXEC sys.sp_executesql @MapQuery,
 N'@measure INT,@val INT OUTPUT,@cnt INT OUTPUT',
 @measure=@MeasureId,@val=@PaymentSeqId OUTPUT,@cnt=@MapCount OUTPUT;
IF @PaymentSeqId IS NULL THROW 51021,N'PaymentSeqId not found for MeasureId',1;
IF @MapCount<>1 THROW 51022,N'Ambiguous PaymentSeqId mapping',1;

DECLARE @DefaultInterestPay DECIMAL(19,2)=0,@SuspendIntPay DECIMAL(19,2)=0,
        @PrincipalPay DECIMAL(19,2)=0;
DECLARE @FeeCourt DECIMAL(19,2)=0,@FeeLawyer DECIMAL(19,2)=0,
        @FeeOther DECIMAL(19,2)=0,@FeeMargin DECIMAL(19,2)=0;
DECLARE @Remaining DECIMAL(19,2)=@ReceiptAmount,@FeeBase DECIMAL(19,2),
        @Percent DECIMAL(19,4),@UnitId INT,@PaymentTypeId INT,@ParamId INT,
        @Available DECIMAL(19,2),@Limit DECIMAL(19,2),@Applied DECIMAL(19,2),
        @SeqOrder INT;
DECLARE @InterestRate DECIMAL(20,8)=0,@PrincipalBefore DECIMAL(19,2),
        @DaysInYear INT,@DayCount INT,@InterestBudget DECIMAL(19,2)=0,
        @InterestCap DECIMAL(19,2)=0,@DefaultCap DECIMAL(19,2)=0;
SELECT TOP(1) @PrincipalBefore=PrincipalTotal,@DefaultCap=CASE WHEN DefaultInterestTotal>0 THEN DefaultInterestTotal ELSE 0 END
FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId ORDER BY TRY_CONVERT(INT,SeqNo) DESC;
IF @PrincipalBefore IS NULL THROW 51023,N'No previous movement',1;

-- Allocate prior-priority buckets FIRST. The remaining receipt cash determines
-- which installments are reachable; never accrue targets on later installments.
-- Master-driven allocation: fees/default first, then SuspendInt and Principal
-- share the SAME post-fee/default base, with unused interest budget flowing to principal.
DECLARE master_cursor CURSOR LOCAL FAST_FORWARD FOR
SELECT sd.Seq,sd.PaymentSeqTypeId,sd.ParameterValuesId,sd.UnitValuesId,ISNULL(sd.[Values],0)
FROM dbo.SystemPaymentSeqDetailMaster sd WHERE sd.PaymentSeqId=@PaymentSeqId
ORDER BY sd.Seq,sd.PaymentSeqDetailId;
OPEN master_cursor;
FETCH NEXT FROM master_cursor INTO @SeqOrder,@PaymentTypeId,@ParamId,@UnitId,@Percent;
WHILE @@FETCH_STATUS=0
BEGIN
    IF @ParamId IN (102,97)
    BEGIN
        FETCH NEXT FROM master_cursor INTO @SeqOrder,@PaymentTypeId,@ParamId,@UnitId,@Percent;
        CONTINUE;
    END;
    SET @Available=CASE @ParamId
      WHEN 107 THEN ISNULL((SELECT TOP(1) CourtFeeTotal FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId ORDER BY TRY_CONVERT(INT,SeqNo) DESC),0)
      WHEN 108 THEN ISNULL((SELECT TOP(1) LawyerFeeTotal FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId ORDER BY TRY_CONVERT(INT,SeqNo) DESC),0)
      WHEN 109 THEN ISNULL((SELECT TOP(1) OtherExpenseTotal FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId ORDER BY TRY_CONVERT(INT,SeqNo) DESC),0)
      WHEN 110 THEN ISNULL((SELECT TOP(1) InitialMarginTotal FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId ORDER BY TRY_CONVERT(INT,SeqNo) DESC),0)
      WHEN 106 THEN @DefaultCap ELSE 0 END;
    IF @Available<0 SET @Available=0;
    SET @Limit=CASE WHEN @UnitId=94 THEN ROUND(@Remaining*@Percent/100.0,2)
                    WHEN @UnitId=95 THEN @Percent ELSE 0 END;
    SET @Applied=CASE WHEN @Remaining<@Available THEN @Remaining ELSE @Available END;
    IF @Applied>@Limit SET @Applied=@Limit;
    IF @Applied<0 SET @Applied=0;
    SET @Remaining-=@Applied;
    IF @ParamId=107 SET @FeeCourt+=@Applied;
    IF @ParamId=108 SET @FeeLawyer+=@Applied;
    IF @ParamId=109 SET @FeeOther+=@Applied;
    IF @ParamId=110 SET @FeeMargin+=@Applied;
    IF @ParamId=106 SET @DefaultInterestPay+=@Applied;
    FETCH NEXT FROM master_cursor INTO @SeqOrder,@PaymentTypeId,@ParamId,@UnitId,@Percent;
END;
CLOSE master_cursor; DEALLOCATE master_cursor;

-- Recalculate interest ONLY for installments the receipt can reach, oldest first.
-- The interest rate is read from latest movement, not a hardcoded amount.
SELECT TOP(1) @InterestRate=ISNULL(InterestPlannedRate,0)
FROM dbo.DataDebtorCardMovement WHERE DebtorCardId=@DataDebtorCardId ORDER BY TRY_CONVERT(INT,SeqNo) DESC;
IF OBJECT_ID('tempdb..#TempInstallmentPlanPayment') IS NOT NULL DROP TABLE #TempInstallmentPlanPayment;
SELECT * INTO #TempInstallmentPlanPayment
FROM dbo.TDRDataCompromiseContractInstallmentPlanPayment WHERE DataDebtorCardId=@DataDebtorCardId;
IF OBJECT_ID('tempdb..#InstallmentInterestTarget') IS NOT NULL DROP TABLE #InstallmentInterestTarget;
CREATE TABLE #InstallmentInterestTarget(Seq INT NOT NULL PRIMARY KEY,InterestTarget DECIMAL(19,2) NOT NULL);
-- Interest ceiling is PER INSTALLMENT: min(monthly accrued interest, 20% of installment).
-- Prior interest already paid reduces the remaining interest allowance.
-- For the first outstanding installment, use last receipt date if valid;
-- for later installments use the first day of that installment month.
DECLARE @PrevDue DATE = NULL,@Due DATE,@PlanSeq INT,@PlanTotal DECIMAL(19,2),
        @PlanInterestPaid DECIMAL(19,2),@PeriodStart DATE,@PeriodEnd DATE,
        @Days INT,@Calculated DECIMAL(19,2),@PrincipalForCalc DECIMAL(19,2),
        @LastReceiptDate DATE,@MonthlyInterest DECIMAL(19,2),
        @PerInstallmentCap DECIMAL(19,2),@InterestAllowance DECIMAL(19,2),
        @InstallmentRoom DECIMAL(19,2);
SET @PrincipalForCalc=@PrincipalBefore;
SELECT @LastReceiptDate=MAX(TRY_CONVERT(DATE,PayDate))
FROM dbo.DataDebtorCardMovement
WHERE DebtorCardId=@DataDebtorCardId AND TypeId=2
  AND TRY_CONVERT(DATE,PayDate)<@PaymentDate
  AND TRY_CONVERT(DATE,PayDate)>'19000101';
-- Reachable installments are determined by cumulative OUTSTANDING INSTALLMENT
-- AMOUNTS, not by the payment month. A partially reached installment is included.
-- @Remaining is cash after fees and default interest, before SuspendInt/Principal.
IF OBJECT_ID('tempdb..#ReachableInstallments') IS NOT NULL DROP TABLE #ReachableInstallments;
;WITH Unpaid AS
(
    SELECT p.Seq, CAST(p.DueDate AS DATE) AS DueDate,
           CAST(ISNULL(p.Total,0) AS DECIMAL(19,2)) AS Total,
           CAST(ISNULL(p.AccruedInterestPay,0) AS DECIMAL(19,2)) AS InterestPaid,
           CAST(ISNULL(p.Total,0)-ISNULL(p.PrincipalPay,0)-ISNULL(p.AccruedInterestPay,0) AS DECIMAL(19,2)) AS Room
    FROM #TempInstallmentPlanPayment p
    WHERE ISNULL(p.IsActive,1)=1 AND ISNULL(p.IsSuspend,0)=0
      -- Only genuinely unpaid installments can consume the receipt.
      -- Paid installments may have Total representing a balance, not the installment amount.
      AND ISNULL(p.IsPayment,0)=0
      AND p.DueDate<=EOMONTH(@PaymentDate)
      AND ISNULL(p.Total,0)>ISNULL(p.PrincipalPay,0)+ISNULL(p.AccruedInterestPay,0)
), Ordered AS
(
    SELECT *, COALESCE(SUM(Room) OVER
        (ORDER BY DueDate,Seq ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS PriorRoom
    FROM Unpaid
)
SELECT Seq,DueDate,Total,InterestPaid,Room,PriorRoom
INTO #ReachableInstallments
FROM Ordered
WHERE PriorRoom < @Remaining;

SELECT N'REACHABLE INSTALLMENTS (UNPAID ONLY)' AS Result,Seq,DueDate,Total,Room,PriorRoom
FROM #ReachableInstallments ORDER BY DueDate,Seq;

DECLARE target_cursor CURSOR LOCAL FAST_FORWARD FOR
SELECT Seq,DueDate,Total,InterestPaid
FROM #ReachableInstallments
ORDER BY DueDate,Seq;
OPEN target_cursor;
FETCH NEXT FROM target_cursor INTO @PlanSeq,@Due,@PlanTotal,@PlanInterestPaid;
WHILE @@FETCH_STATUS=0
BEGIN
    SET @PeriodStart=DATEFROMPARTS(YEAR(@Due),MONTH(@Due),1);
    IF @PrevDue IS NULL AND @LastReceiptDate IS NOT NULL
       AND @LastReceiptDate<=@Due
       SET @PeriodStart=@LastReceiptDate;
    SET @PeriodEnd=CASE WHEN @Due>@PaymentDate THEN @PaymentDate ELSE @Due END;
    SET @Days=CASE WHEN @PeriodEnd>=@PeriodStart
                    THEN DATEDIFF(DAY,@PeriodStart,@PeriodEnd)+1 ELSE 0 END;
    SET @DaysInYear=CASE WHEN (YEAR(@Due)%400=0 OR
                     (YEAR(@Due)%4=0 AND YEAR(@Due)%100<>0)) THEN 366 ELSE 365 END;
    SET @MonthlyInterest=ROUND(@PrincipalForCalc*@InterestRate/100.0*@Days/NULLIF(@DaysInYear,0),2);
    -- Compare ACTUAL monthly interest against 20% of THIS installment.
    SET @PerInstallmentCap=ROUND(@PlanTotal*0.20,2);
    SET @InterestAllowance=CASE WHEN @MonthlyInterest<@PerInstallmentCap
                                THEN @MonthlyInterest ELSE @PerInstallmentCap END;
    -- Do not collect the interest previously paid on this installment twice.
    SET @Calculated=@InterestAllowance-@PlanInterestPaid;
    SET @InstallmentRoom=@PlanTotal-ISNULL((SELECT TOP(1) PaymentAmount
                                           FROM #TempInstallmentPlanPayment WHERE Seq=@PlanSeq),0);
    IF @Calculated>@InstallmentRoom SET @Calculated=@InstallmentRoom;
    IF @Calculated<0 SET @Calculated=0;
    INSERT #InstallmentInterestTarget VALUES(@PlanSeq,@Calculated);
    SET @PrevDue=@Due;
    FETCH NEXT FROM target_cursor INTO @PlanSeq,@Due,@PlanTotal,@PlanInterestPaid;
END;
CLOSE target_cursor; DEALLOCATE target_cursor;
SELECT @InterestCap=ISNULL(SUM(InterestTarget),0) FROM #InstallmentInterestTarget;

SET @FeeBase=@Remaining;
SELECT @Percent=ISNULL([Values],0),@UnitId=UnitValuesId
FROM dbo.SystemPaymentSeqDetailMaster
WHERE PaymentSeqDetailId=(SELECT TOP(1) PaymentSeqDetailId FROM dbo.SystemPaymentSeqDetailMaster
WHERE PaymentSeqId=@PaymentSeqId AND ParameterValuesId=102 ORDER BY Seq);
IF @@ROWCOUNT=0 THROW 51024,N'Master missing SuspendInt rule',1;
SET @Limit=CASE WHEN @UnitId=94 THEN ROUND(@FeeBase*@Percent/100.0,2) ELSE @Percent END;
SET @SuspendIntPay=CASE WHEN @InterestCap<@Limit THEN @InterestCap ELSE @Limit END;
IF @SuspendIntPay>@Remaining SET @SuspendIntPay=@Remaining;
IF @SuspendIntPay<0 SET @SuspendIntPay=0;
SET @Remaining-=@SuspendIntPay;
IF NOT EXISTS(SELECT 1 FROM dbo.SystemPaymentSeqDetailMaster WHERE PaymentSeqId=@PaymentSeqId AND ParameterValuesId=97)
    THROW 51025,N'Master missing principal rule',1;
-- Principal takes the rest after interest; unused interest budget rolls into principal.
SET @PrincipalPay=@Remaining;
IF @PrincipalPay>@PrincipalBefore SET @PrincipalPay=@PrincipalBefore;
SET @Remaining-=@PrincipalPay;
IF @Remaining<>0 THROW 51026,N'Unallocated payment: no supported bucket',1;
IF ROUND(@FeeCourt+@FeeLawyer+@FeeOther+@FeeMargin+@DefaultInterestPay+@SuspendIntPay+@PrincipalPay,2)<>@ReceiptAmount
    THROW 51027,N'Allocation does not reconcile to EStatement',1;
SELECT N'MASTER ALLOCATION' AS Result,@PaymentSeqId PaymentSeqId,@ReceiptAmount ReceiptAmount,
 @FeeCourt CourtFeePay,@FeeLawyer LawyerFeePay,@FeeOther OtherExpensePay,@FeeMargin InitialMarginPay,
 @DefaultInterestPay DefaultInterestPay,@SuspendIntPay SuspendIntPay,@PrincipalPay PrincipalPay;
IF OBJECT_ID('tempdb..#TempMovement') IS NULL
BEGIN
    THROW 51030,N'#TempMovement does not exist',1;
END;
IF NOT EXISTS (
    SELECT 1 FROM #TempMovement
    WHERE DebtorCardId = @DataDebtorCardId AND TRY_CONVERT(INT, SeqNo) = (@BaseSeq+2)
)
BEGIN
    THROW 51031,N'Previous staged movement was not found',1;
END;
IF @ReceiptAmount <> @DefaultInterestPay + @SuspendIntPay + @PrincipalPay + @FeeCourt + @FeeLawyer + @FeeOther + @FeeMargin
BEGIN
    THROW 51032,N'Payment amounts do not reconcile',1;
END;

/* Receipt allocation based on master rules. */
SELECT
    @DataDebtorCardId AS DataDebtorCardId,
    (@BaseSeq+3) AS SeqNo,
    2 AS TypeId,
    @PaymentDate AS PaymentDate,
    @ReceiptAmount AS ReceiptAmount,
    @PaymentSeqId AS PaymentSeqId,
    @DefaultInterestPay AS DefaultInterestPay,
    @SuspendIntPay AS SuspendIntPay,
    @PrincipalPay AS PrincipalPay,
    CAST(0 AS DECIMAL(19,2)) AS UnallocatedAmount;

/* Original state, for comparison. */
SELECT N'BEFORE' AS Snapshot, Seq, DueDate, Total, IsPayment,
       PaymentAmount, PrincipalPay, AccruedInterestPay,
       OverdueAmount, PrincipalOverdueAmount, AccruedInterestOverdueAmount
FROM #TempInstallmentPlanPayment
WHERE DueDate <= EOMONTH(@PaymentDate)
ORDER BY DueDate, Seq;

/*
  ALLOCATION ASSUMPTIONS TO VERIFY:
  - oldest unpaid installments first, through the payment month;
  - distribute interest and principal from the approved receipt buckets;
  - for a partially paid installment, its remaining Total is the cash cap;
  - no future installments are paid.
  Interest targets are dynamically estimated from latest planned rate.
  Verify these against approved interest accrual before production posting.
*/
-- #InstallmentInterestTarget has already been calculated dynamically from the payment date,
-- principal and planned rate; no hardcoded installment sequence or amounts.
DECLARE @PrincipalRemaining DECIMAL(19,2) = @PrincipalPay;
DECLARE @InterestRemaining DECIMAL(19,2) = @SuspendIntPay;
DECLARE @Seq INT, @Total DECIMAL(19,2), @OldPrincipal DECIMAL(19,2),
        @OldInterest DECIMAL(19,2), @Room DECIMAL(19,2),
        @IntTarget DECIMAL(19,2), @IntAdd DECIMAL(19,2), @PrnAdd DECIMAL(19,2);

DECLARE installment_cursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT p.Seq, CAST(ISNULL(p.Total,0) AS DECIMAL(19,2)),
           CAST(ISNULL(p.PrincipalPay,0) AS DECIMAL(19,2)),
           CAST(ISNULL(p.AccruedInterestPay,0) AS DECIMAL(19,2)),
           CAST(ISNULL(t.InterestTarget,0) AS DECIMAL(19,2))
    FROM #TempInstallmentPlanPayment p
    JOIN #ReachableInstallments r ON r.Seq = p.Seq
    LEFT JOIN #InstallmentInterestTarget t ON t.Seq = p.Seq
    WHERE p.DueDate <= EOMONTH(@PaymentDate)
      AND ISNULL(p.IsPayment,0) = 0
    ORDER BY p.DueDate, p.Seq;
OPEN installment_cursor;
FETCH NEXT FROM installment_cursor INTO @Seq,@Total,@OldPrincipal,@OldInterest,@IntTarget;
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @Room = CASE WHEN @Total > @OldPrincipal + @OldInterest
                     THEN @Total - @OldPrincipal - @OldInterest ELSE 0 END;
    /* This preview only allocates into installments with verified interest
       targets. Stop rather than guess the split of a later installment. */
    IF @Room > 0 AND @PrincipalRemaining + @InterestRemaining > 0
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM #InstallmentInterestTarget WHERE Seq=@Seq)
        BEGIN
            CLOSE installment_cursor;
            DEALLOCATE installment_cursor;
            THROW 51033,N'Missing interest target for a reached installment',1;
        END;
        SET @IntAdd = CASE WHEN @InterestRemaining < @IntTarget THEN @InterestRemaining ELSE @IntTarget END;
        IF @IntAdd > @Room SET @IntAdd = @Room;
        SET @PrnAdd = CASE WHEN @PrincipalRemaining < @Room - @IntAdd
                           THEN @PrincipalRemaining ELSE @Room - @IntAdd END;
        /* Do not pretend a fully paid installment if funds cannot fill it. */
        UPDATE #TempInstallmentPlanPayment
        SET PrincipalPay = @OldPrincipal + @PrnAdd,
            AccruedInterestPay = @OldInterest + @IntAdd,
            PaymentAmount = @OldPrincipal + @OldInterest + @PrnAdd + @IntAdd,
            IsPayment = CASE WHEN @OldPrincipal + @OldInterest + @PrnAdd + @IntAdd >= @Total THEN 1 ELSE 0 END,
            OverdueAmount = CASE WHEN @Total > @OldPrincipal + @OldInterest + @PrnAdd + @IntAdd
                                 THEN @Total - @OldPrincipal - @OldInterest - @PrnAdd - @IntAdd ELSE 0 END,
            /* Interest overdue here uses the recalculated interest target,
               not the stale plan Interest column. */
            AccruedInterestOverdueAmount = CASE WHEN @IntTarget > @OldInterest + @IntAdd
                                                 THEN @IntTarget - @OldInterest - @IntAdd ELSE 0 END,
            PrincipalOverdueAmount = CASE
                WHEN @Total - @OldPrincipal - @OldInterest - @PrnAdd - @IntAdd >
                     CASE WHEN @IntTarget > @OldInterest + @IntAdd THEN @IntTarget - @OldInterest - @IntAdd ELSE 0 END
                THEN (@Total - @OldPrincipal - @OldInterest - @PrnAdd - @IntAdd)
                     - CASE WHEN @IntTarget > @OldInterest + @IntAdd THEN @IntTarget - @OldInterest - @IntAdd ELSE 0 END
                ELSE 0 END
        WHERE Seq=@Seq AND DataDebtorCardId=@DataDebtorCardId;
        SET @PrincipalRemaining -= @PrnAdd;
        SET @InterestRemaining -= @IntAdd;
    END;
    FETCH NEXT FROM installment_cursor INTO @Seq,@Total,@OldPrincipal,@OldInterest,@IntTarget;
END;
CLOSE installment_cursor;
DEALLOCATE installment_cursor;

SELECT N'AFTER' AS Snapshot, Seq, DueDate, Total, IsPayment,
       PaymentAmount, PrincipalPay, AccruedInterestPay,
       OverdueAmount, PrincipalOverdueAmount, AccruedInterestOverdueAmount
FROM #TempInstallmentPlanPayment
WHERE DueDate <= EOMONTH(@PaymentDate)
ORDER BY DueDate, Seq;

SELECT @ReceiptAmount AS ReceiptAmount,
       @DefaultInterestPay AS DefaultInterestPay,
       @SuspendIntPay-@InterestRemaining AS InterestAppliedToPlan,
       @PrincipalPay-@PrincipalRemaining AS PrincipalAppliedToPlan,
       @InterestRemaining AS InterestNotApplied,
       @PrincipalRemaining AS PrincipalPrepaymentOrUnallocated,
       @DefaultInterestPay + (@SuspendIntPay-@InterestRemaining)
          + (@PrincipalPay-@PrincipalRemaining) AS AllocatedToReceiptAndPlan;

/* Inspect temp movement columns to build the actual INSERT safely. */
SELECT c.name AS ColumnName, t.name AS DataType, c.is_nullable AS IsNullable
FROM tempdb.sys.columns c
JOIN tempdb.sys.types t ON t.user_type_id=c.user_type_id
WHERE c.object_id=OBJECT_ID('tempdb..#TempMovement')
ORDER BY c.column_id;


/* ============================================================
   STEP 3B: INSERT payment Movement Seq61 into #TempMovement ONLY.
   Do not execute if installment buckets have not reconciled.
   ============================================================ */
-- DEBUG 51040: print values immediately to Messages, even if transaction rolls back.
DECLARE @Debug51040 NVARCHAR(2000);
SET @Debug51040 = CONCAT(
      N'ReceiptAmount=', COALESCE(CONVERT(NVARCHAR(40), @ReceiptAmount), N'NULL')
    , N' | DefaultInterestPay=', COALESCE(CONVERT(NVARCHAR(40), @DefaultInterestPay), N'NULL')
    , N' | SuspendIntPay=', COALESCE(CONVERT(NVARCHAR(40), @SuspendIntPay), N'NULL')
    , N' | PrincipalPay=', COALESCE(CONVERT(NVARCHAR(40), @PrincipalPay), N'NULL')
    , N' | InterestRemaining=', COALESCE(CONVERT(NVARCHAR(40), @InterestRemaining), N'NULL')
    , N' | PrincipalRemaining=', COALESCE(CONVERT(NVARCHAR(40), @PrincipalRemaining), N'NULL')
);
RAISERROR(N'%s', 0, 1, @Debug51040) WITH NOWAIT;

IF @InterestRemaining <> 0 OR @PrincipalRemaining <> 0
    THROW 51040, N'Installment allocations did not consume approved buckets. No Movement insert.', 1;
IF EXISTS (SELECT 1 FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo)=(@BaseSeq+3))
    THROW 51041, N'Seq61 already exists in #TempMovement. No duplicate insert.', 1;
IF (SELECT COUNT(*) FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo)=(@BaseSeq+2)) <> 1
    THROW 51042, N'Expected exactly one staged Seq60 row.', 1;

DECLARE @NewMovementId NVARCHAR(150) = CONVERT(NVARCHAR(150),NEWID());
DECLARE @TypeCode NVARCHAR(200), @TypeName NVARCHAR(200);
SELECT @TypeCode=PaymentTypeCode, @TypeName=PaymentTypeName
FROM dbo.SystemPaymentType WHERE PaymentTypeId=2;

DECLARE @Cols NVARCHAR(MAX)=N'', @Vals NVARCHAR(MAX)=N'', @SQL NVARCHAR(MAX);
SELECT @Cols = STUFF((
    SELECT N','+QUOTENAME(c.name)
    FROM tempdb.sys.columns c
    WHERE c.object_id=OBJECT_ID('tempdb..#TempMovement')
      AND c.is_identity=0 AND c.is_computed=0 AND c.system_type_id<>189
    ORDER BY c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,1,N'');
SELECT @Vals = STUFF((
    SELECT N','+CASE c.name
        WHEN 'DebtorCardMovementId' THEN N'@NewMovementId'
        WHEN 'SeqNo' THEN N'(@BaseSeq+3)'
        WHEN 'DocDate' THEN N'@RunDocDate'
        WHEN 'PayDate' THEN N'@PaymentDate'
        WHEN 'TypeId' THEN N'2'
        WHEN 'TypeCode' THEN N'@TypeCode'
        WHEN 'TypeName' THEN N'@TypeName'
        WHEN 'IsAdjust' THEN N'0'
        WHEN 'TotalPay' THEN N'@ReceiptAmount'
        WHEN 'ReceivePayment' THEN N'@ReceiptAmount'
        WHEN 'IsEstatement' THEN N'1'
        WHEN 'EStatementRef' THEN N'@EStatementId'
        WHEN 'PaymentTypeId' THEN N'2'
        WHEN 'DPD' THEN N'0'
        WHEN 'DPDAccumulate' THEN N'ISNULL(m.DPDAccumulate,0)'
        WHEN 'InterimInterest' THEN N'0'
        WHEN 'InterestStartDate' THEN N'CONVERT(DATE,''19000101'')'
        WHEN 'InterestEndDate' THEN N'CONVERT(DATE,''19000101'')'
        WHEN 'SuspendInt' THEN N'0'
        WHEN 'DefaultInterest' THEN N'0'
        WHEN 'AccruedInterest' THEN N'0'
        WHEN 'PrincipalPay' THEN N'@PrincipalPay'
        WHEN 'SuspendIntPay' THEN N'@SuspendIntPay'
        WHEN 'DefaultInterestPay' THEN N'@DefaultInterestPay'
        WHEN 'AccruedInterestPay' THEN N'@SuspendIntPay+@DefaultInterestPay'
        WHEN 'PrincipalTotal' THEN N'ISNULL(m.PrincipalTotal,0)-@PrincipalPay'
        WHEN 'SuspendIntTotal' THEN N'ISNULL(m.SuspendIntTotal,0)-@SuspendIntPay'
        WHEN 'DefaultInterestTotal' THEN N'ISNULL(m.DefaultInterestTotal,0)-@DefaultInterestPay'
        WHEN 'AccruedInterestTotal' THEN N'ISNULL(m.AccruedInterestTotal,0)-@SuspendIntPay-@DefaultInterestPay'
        WHEN 'DebtBalance' THEN N'ISNULL(m.DebtBalance,0)-@PrincipalPay-@SuspendIntPay-@DefaultInterestPay'
        WHEN 'CreateDate' THEN N'GETDATE()'
        WHEN 'UpdateDate' THEN N'GETDATE()'
        ELSE N'm.'+QUOTENAME(c.name) END
    FROM tempdb.sys.columns c
    WHERE c.object_id=OBJECT_ID('tempdb..#TempMovement')
      AND c.is_identity=0 AND c.is_computed=0 AND c.system_type_id<>189
    ORDER BY c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,1,N'');
SET @SQL=N'INSERT INTO #TempMovement ('+@Cols+N') SELECT '+@Vals+
  N' FROM #TempMovement m WHERE m.DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,m.SeqNo)=(@BaseSeq+2);';
EXEC sys.sp_executesql @SQL,
 N'@BaseSeq INT,@NewMovementId NVARCHAR(150),@PaymentDate DATE,@TypeCode NVARCHAR(200),@TypeName NVARCHAR(200),@ReceiptAmount DECIMAL(19,2),@RunDocDate DATE,@EStatementId NVARCHAR(150),@PrincipalPay DECIMAL(19,2),@SuspendIntPay DECIMAL(19,2),@DefaultInterestPay DECIMAL(19,2),@DataDebtorCardId NVARCHAR(150)',
 @BaseSeq=@BaseSeq,@NewMovementId=@NewMovementId,@PaymentDate=@PaymentDate,@TypeCode=@TypeCode,@TypeName=@TypeName,
 @ReceiptAmount=@ReceiptAmount,@RunDocDate=@RunDocDate,@EStatementId=@EStatementId,@PrincipalPay=@PrincipalPay,
 @SuspendIntPay=@SuspendIntPay,@DefaultInterestPay=@DefaultInterestPay,@DataDebtorCardId=@DataDebtorCardId;

SELECT N'MOVEMENT STEP 1-3' AS Result, SeqNo,TypeId,PayDate,TotalPay,
 PrincipalPay,SuspendIntPay,DefaultInterestPay,AccruedInterestPay,PrincipalTotal
FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId ORDER BY TRY_CONVERT(INT,SeqNo);

SELECT N'INSTALLMENT AFTER' AS Result,Seq,DueDate,Total,IsPayment,PaymentAmount,
 PrincipalPay,AccruedInterestPay,OverdueAmount,PrincipalOverdueAmount,AccruedInterestOverdueAmount
FROM #TempInstallmentPlanPayment
WHERE DataDebtorCardId=@DataDebtorCardId AND DueDate<=EOMONTH(@PaymentDate)
ORDER BY DueDate,Seq;

-- Stage complete; permanent persistence follows below.


  END;
  BEGIN
/* STEP 4: staged balance Movement Seq62 */
/* STEP 4 ONLY: Run in the SAME SSMS session after Step 1-3.
   INSERT into #TempMovement ONLY. Does not execute SP 003, does not modify permanent tables.
   Assumes #TempInstallmentPlanPayment contains the POST-PAYMENT installment state.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;

-- @DataDebtorCardId supplied by caller
DECLARE @B4PaymentDate DATE;
DECLARE @B4OldDFDDate DATE = '19000101';
DECLARE @B4NewDFDDate DATE = '19000101';
DECLARE @B4EffectiveDFDDate DATE = '19000101';
DECLARE @B4DPD INT = 0, @B4DPDAccumulate INT = 0;
DECLARE @B4DPDStartDate DATE;
DECLARE @B4TypeCode NVARCHAR(200), @B4TypeName NVARCHAR(200);
DECLARE @B4NewMovementId NVARCHAR(150) = CONVERT(NVARCHAR(150), NEWID());

IF OBJECT_ID('tempdb..#TempMovement') IS NULL
    THROW 52001, N'Run Steps 1-3 first: #TempMovement is missing.', 1;
IF OBJECT_ID('tempdb..#TempInstallmentPlanPayment') IS NULL
    THROW 52002, N'Run Step 3 first: post-payment #TempInstallmentPlanPayment is missing.', 1;
IF (SELECT COUNT(*) FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo)=(@BaseSeq+3) AND TypeId=2) <> 1
    THROW 52003, N'Expected exactly one payment Movement Seq61 TypeId=2.', 1;
IF EXISTS (SELECT 1 FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo)=(@BaseSeq+4))
    THROW 52004, N'Seq62 already exists in #TempMovement. Do not insert twice.', 1;

SELECT @B4PaymentDate = CAST(PayDate AS DATE)
FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo)=(@BaseSeq+3) AND TypeId=2;
IF @B4PaymentDate IS NULL OR @B4PaymentDate='19000101'
    THROW 52005, N'Payment date on Seq61 is invalid.', 1;

SELECT @B4OldDFDDate = ISNULL(CAST(DFDDate AS DATE), '19000101')
FROM dbo.DataDebtorCard WHERE DataDebtorCardId=@DataDebtorCardId;
IF @@ROWCOUNT <> 1 THROW 52006, N'DataDebtorCard row not found.', 1;

/* Earliest outstanding installment, excluding the payment month.
   Partial principal balance still counts as overdue. */
SELECT TOP (1)
    @B4NewDFDDate = DATEADD(DAY, 1, CAST(p.DueDate AS DATE))
FROM #TempInstallmentPlanPayment p
WHERE p.DataDebtorCardId=@DataDebtorCardId
  AND ISNULL(p.IsActive,1)=1
  AND ISNULL(p.IsSuspend,0)=0
  AND CAST(p.DueDate AS DATE) < DATEFROMPARTS(YEAR(@B4PaymentDate),MONTH(@B4PaymentDate),1)
  AND ISNULL(p.PrincipalPay,0) + ISNULL(p.AccruedInterestPay,0) < ISNULL(p.Total,0)
ORDER BY p.DueDate, p.Seq;

/* No arrears: preserve existing DFDDate, but DPD and DPDAccumulate are both zero.
   Arrears: only advance DFDDate, never move it backward. */
SET @B4EffectiveDFDDate = @B4OldDFDDate;
IF @B4NewDFDDate <> '19000101'
BEGIN
    IF @B4NewDFDDate > @B4OldDFDDate SET @B4EffectiveDFDDate=@B4NewDFDDate;
    IF @B4EffectiveDFDDate <> '19000101' AND @B4EffectiveDFDDate <= @B4PaymentDate
    BEGIN
        SET @B4DPDStartDate=DATEFROMPARTS(YEAR(@B4PaymentDate),MONTH(@B4PaymentDate),1);
        IF @B4EffectiveDFDDate > @B4DPDStartDate SET @B4DPDStartDate=@B4EffectiveDFDDate;
        SET @B4DPD=DATEDIFF(DAY,@B4DPDStartDate,@B4PaymentDate)+1;
        SET @B4DPDAccumulate=DATEDIFF(DAY,@B4EffectiveDFDDate,@B4PaymentDate)+1;
    END;
END;

SELECT @B4TypeCode=PaymentTypeCode,@B4TypeName=PaymentTypeName
FROM dbo.SystemPaymentType WHERE PaymentTypeId=8;
IF @B4TypeCode IS NULL THROW 52007, N'SystemPaymentType 8 not found.', 1;

/* Build a complete row from Seq61, changing only balance-row-specific fields.
   The source schema is read from the real temp table, so columns remain aligned. */
DECLARE @B4Cols NVARCHAR(MAX), @B4Vals NVARCHAR(MAX), @B4SQL NVARCHAR(MAX);
SELECT @B4Cols = STUFF((
    SELECT N','+QUOTENAME(c.name)
    FROM tempdb.sys.columns c
    WHERE c.object_id=OBJECT_ID('tempdb..#TempMovement')
      AND c.is_identity=0 AND c.is_computed=0 AND c.system_type_id<>189
    ORDER BY c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,1,N'');
SELECT @B4Vals = STUFF((
    SELECT N','+CASE c.name
        WHEN 'DebtorCardMovementId' THEN N'@B4NewMovementId'
        WHEN 'SeqNo' THEN N'(@BaseSeq+4)'
        WHEN 'TypeId' THEN N'8'
        WHEN 'PaymentTypeId' THEN N'8'
        WHEN 'TypeCode' THEN N'@B4TypeCode'
        WHEN 'TypeName' THEN N'@B4TypeName'
        WHEN 'DocDate' THEN N'@RunDocDate'
        WHEN 'PayDate' THEN N'CONVERT(DATE,''19000101'')'
        WHEN 'DFDDate' THEN N'@B4EffectiveDFDDate'
        WHEN 'DFDStartDate' THEN N'@B4PaymentDate'
        WHEN 'DPD' THEN N'@B4DPD'
        WHEN 'DPDAccumulate' THEN N'@B4DPDAccumulate'
        WHEN 'TotalPay' THEN N'0'
        WHEN 'ReceivePayment' THEN N'0'
        WHEN 'Principal' THEN N'ISNULL(m.PrincipalTotal,0)'
        WHEN 'PrincipalPay' THEN N'0'
        WHEN 'AccruedInterest' THEN N'0'
        WHEN 'AccruedInterestPay' THEN N'0'
        WHEN 'CourtFee' THEN N'ISNULL(m.CourtFeeTotal,0)'
        WHEN 'CourtFeePay' THEN N'0'
        WHEN 'LawyerFee' THEN N'ISNULL(m.LawyerFeeTotal,0)'
        WHEN 'LawyerFeePay' THEN N'0'
        WHEN 'OtherExpense' THEN N'ISNULL(m.OtherExpenseTotal,0)'
        WHEN 'OtherExpensePay' THEN N'0'
        WHEN 'InitialMargin' THEN N'ISNULL(m.InitialMarginTotal,0)'
        WHEN 'InitialMarginPay' THEN N'0'
        WHEN 'SuspendInt' THEN N'ISNULL(m.SuspendIntTotal,0)'
        WHEN 'SuspendIntPay' THEN N'0'
        WHEN 'DeferredInterest' THEN N'0'
        WHEN 'DeferredInterestPay' THEN N'0'
        WHEN 'SuspendedDefaultInterest' THEN N'ISNULL(m.SuspendedDefaultInterestTotal,0)'
        WHEN 'SuspendedDefaultInterestPay' THEN N'0'
        WHEN 'PlannedInterest' THEN N'0'
        WHEN 'PlannedInterestPay' THEN N'0'
        WHEN 'DefaultInterest' THEN N'0'
        WHEN 'DefaultInterestPay' THEN N'0'
        WHEN 'InstallmentPay' THEN N'0'
        WHEN 'InstallmentPrincipalPay' THEN N'0'
        WHEN 'InstallmentInterestPay' THEN N'0'
        WHEN 'InterestStartDate' THEN N'CONVERT(DATE,''19000101'')'
        WHEN 'InterestEndDate' THEN N'CONVERT(DATE,''19000101'')'
        WHEN 'IsAdjust' THEN N'0'
        WHEN 'IsEstatement' THEN N'0'
        WHEN 'EStatementRef' THEN N'NULL'
        WHEN 'ReceiptNo' THEN N'NULL'
        WHEN 'CreateDate' THEN N'GETDATE()'
        WHEN 'UpdateDate' THEN N'GETDATE()'
        WHEN 'IsUpdateHistory' THEN N'0'
        ELSE N'm.'+QUOTENAME(c.name) END
    FROM tempdb.sys.columns c
    WHERE c.object_id=OBJECT_ID('tempdb..#TempMovement')
      AND c.is_identity=0 AND c.is_computed=0 AND c.system_type_id<>189
    ORDER BY c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,1,N'');
SET @B4SQL=N'INSERT INTO #TempMovement ('+@B4Cols+N') SELECT '+@B4Vals+
  N' FROM #TempMovement m WHERE m.DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,m.SeqNo)=(@BaseSeq+3) AND m.TypeId=2;';
EXEC sys.sp_executesql @B4SQL,
  N'@BaseSeq INT,@B4NewMovementId NVARCHAR(150),@B4PaymentDate DATE,@RunDocDate DATE,@B4TypeCode NVARCHAR(200),@B4TypeName NVARCHAR(200),@B4EffectiveDFDDate DATE,@B4DPD INT,@B4DPDAccumulate INT,@DataDebtorCardId NVARCHAR(150)',
  @BaseSeq=@BaseSeq,@B4NewMovementId=@B4NewMovementId,@B4PaymentDate=@B4PaymentDate,@RunDocDate=@RunDocDate,@B4TypeCode=@B4TypeCode,@B4TypeName=@B4TypeName,
  @B4EffectiveDFDDate=@B4EffectiveDFDDate,@B4DPD=@B4DPD,@B4DPDAccumulate=@B4DPDAccumulate,@DataDebtorCardId=@DataDebtorCardId;
IF (SELECT COUNT(*) FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo)=(@BaseSeq+4) AND TypeId=8)<>1
    THROW 52008, N'Failed to insert exactly one staged balance row.',1;

SELECT N'DFD / DPD CHECK' AS Result, @B4PaymentDate AS PaymentDate,
       @B4OldDFDDate AS CardDFDDate, @B4NewDFDDate AS FoundDFDDate,
       @B4EffectiveDFDDate AS EffectiveDFDDate,
       @B4DPD AS DPD, @B4DPDAccumulate AS DPDAccumulate,
       CASE WHEN @B4NewDFDDate='19000101' THEN N'NO ARREARS'
            WHEN @B4NewDFDDate>@B4OldDFDDate THEN N'ADVANCE DFD'
            ELSE N'KEEP OLD DFD' END AS DFDAction;

SELECT SeqNo,TypeId,PaymentTypeId,DocDate,PayDate,DFDDate,DPD,DPDAccumulate,
       TotalPay,PrincipalPay,SuspendIntPay,DefaultInterestPay,AccruedInterestPay,
       PrincipalTotal,SuspendIntTotal,DefaultInterestTotal,AccruedInterestTotal,DebtBalance
FROM #TempMovement
WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo) BETWEEN @BaseSeq+1 AND @BaseSeq+4
ORDER BY TRY_CONVERT(INT,SeqNo);

SELECT N'UNPAID BEFORE PAYMENT MONTH' AS Result, Seq,DueDate,Total,IsPayment,
       PrincipalPay,AccruedInterestPay,
       ISNULL(Total,0)-ISNULL(PrincipalPay,0)-ISNULL(AccruedInterestPay,0) AS Remaining
FROM #TempInstallmentPlanPayment
WHERE DataDebtorCardId=@DataDebtorCardId
  AND CAST(DueDate AS DATE)<DATEFROMPARTS(YEAR(@B4PaymentDate),MONTH(@B4PaymentDate),1)
  AND ISNULL(IsActive,1)=1 AND ISNULL(IsSuspend,0)=0
  AND ISNULL(PrincipalPay,0)+ISNULL(AccruedInterestPay,0)<ISNULL(Total,0)
ORDER BY DueDate,Seq;



  END;
  /* ================================================================
     FINAL NORMALIZATION OF FOUR STAGED MOVEMENTS
     DocDate = execution date (not historical payment date).
     AccruedInterestTotal = sum of distinct outstanding interest buckets.
     DebtBalance = principal + outstanding interest + remaining fees.
     Do not include AccruedInterestTotal itself in its own sum.
     Keep signed adjustments (Type 7); do not clamp negative values.
     ================================================================ */
  IF (SELECT COUNT(*) FROM #TempMovement
      WHERE DebtorCardId=@DataDebtorCardId
        AND TRY_CONVERT(INT,SeqNo) BETWEEN @BaseSeq+1 AND @BaseSeq+4) <> 4
      THROW 54012,N'Expected four staged movements before final normalization',1;

  /* First installment ACTUALLY paid by this receipt.
     Compare the staged POST-payment plan against the unchanged real plan.
     Do NOT filter staged IsPayment=0: the receipt may have completed that installment.
     IMPORTANT: p.Total is assumed to represent the installment amount in this
     UAT candidate; confirm its meaning for every measure before production.
  */
  DECLARE @FirstReachedSeq INT, @FirstReachedInstallment DECIMAL(19,2);
  SELECT TOP (1)
      @FirstReachedSeq = p.Seq,
      @FirstReachedInstallment = TRY_CONVERT(DECIMAL(19,2),p.Total)
  FROM #TempInstallmentPlanPayment AS p
  JOIN dbo.TDRDataCompromiseContractInstallmentPlanPayment AS original
    ON original.CompromiseContractInstallmentPlanPaymentId =
       p.CompromiseContractInstallmentPlanPaymentId
  JOIN #ReachableInstallments AS r ON r.Seq = p.Seq
  WHERE p.DataDebtorCardId = @DataDebtorCardId
    AND (
         ISNULL(p.PrincipalPay,0) > ISNULL(original.PrincipalPay,0)
      OR ISNULL(p.AccruedInterestPay,0) > ISNULL(original.AccruedInterestPay,0)
    )
  ORDER BY p.DueDate, p.Seq;

  IF @FirstReachedSeq IS NULL OR @FirstReachedInstallment IS NULL
      THROW 54013,N'No first reached installment found; cannot populate installment amount.',1;

  IF COL_LENGTH(N'dbo.DataDebtorCardMovement',N'Installment') IS NULL
      THROW 54014,N'DataDebtorCardMovement.Installment column not found; verify destination column name.',1;

  SELECT N'FIRST REACHED INSTALLMENT' AS Result,
         @FirstReachedSeq AS InstallmentSeq,
         @FirstReachedInstallment AS InstallmentAmount;

  UPDATE m
  SET m.DocDate = @RunDocDate,
      m.AccruedInterestTotal =
          ISNULL(m.SuspendIntTotal,0)
        + ISNULL(m.DeferredInterestTotal,0)
        + ISNULL(m.SuspendedDefaultInterestTotal,0)
        + ISNULL(m.PlannedInterestTotal,0)
        + ISNULL(m.DefaultInterestTotal,0),
      m.DebtBalance =
          ISNULL(m.PrincipalTotal,0)
        + ISNULL(m.SuspendIntTotal,0)
        + ISNULL(m.DeferredInterestTotal,0)
        + ISNULL(m.SuspendedDefaultInterestTotal,0)
        + ISNULL(m.PlannedInterestTotal,0)
        + ISNULL(m.DefaultInterestTotal,0)
        + ISNULL(m.OtherExpenseTotal,0)
        + ISNULL(m.InitialMarginTotal,0)
        + ISNULL(m.LawyerFeeTotal,0)
        + ISNULL(m.CourtFeeTotal,0)
  FROM #TempMovement AS m
  WHERE m.DebtorCardId=@DataDebtorCardId
    AND TRY_CONVERT(INT,m.SeqNo) BETWEEN @BaseSeq+1 AND @BaseSeq+4;

  -- All four movement rows carry the SAME first reached installment amount.
  UPDATE m
     SET m.Installment=@FirstReachedInstallment
  FROM #TempMovement m
  WHERE m.DebtorCardId=@DataDebtorCardId
    AND TRY_CONVERT(INT,m.SeqNo) BETWEEN @BaseSeq+1 AND @BaseSeq+4;

  -- TypeId=2 receipt row: clear period interest, not interest balances.
  UPDATE m
  SET m.InterimInterest=0,
      m.InterestStartDate=CONVERT(DATE,'19000101'),
      m.InterestEndDate=CONVERT(DATE,'19000101'),
      m.SuspendInt=0,
      m.DefaultInterest=0,
      m.AccruedInterest=0
  FROM #TempMovement AS m
  WHERE m.DebtorCardId=@DataDebtorCardId
    AND TRY_CONVERT(INT,m.SeqNo)=@BaseSeq+3
    AND m.TypeId=2;

  SELECT N'FINAL FOUR ROW CHECK' AS Result,
         SeqNo,TypeId,Installment,DocDate,PayDate,InterestStartDate,InterestEndDate,
         InterimInterest,SuspendInt,DefaultInterest,AccruedInterest,
         PrincipalTotal,SuspendIntTotal,DeferredInterestTotal,
         SuspendedDefaultInterestTotal,PlannedInterestTotal,DefaultInterestTotal,
         AccruedInterestTotal,OtherExpenseTotal,InitialMarginTotal,
         LawyerFeeTotal,CourtFeeTotal,DebtBalance
  FROM #TempMovement
  WHERE DebtorCardId=@DataDebtorCardId
    AND TRY_CONVERT(INT,SeqNo) BETWEEN @BaseSeq+1 AND @BaseSeq+4
  ORDER BY TRY_CONVERT(INT,SeqNo);

  -- Check no concurrent changes to plan since staged snapshot.
  -- Stage and persist exactly four movement rows, with no identity/computed columns.
  DECLARE @InsertCols NVARCHAR(MAX),@InsertSql NVARCHAR(MAX);
  SELECT @InsertCols=STUFF((SELECT N','+QUOTENAME(name) FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.DataDebtorCardMovement') AND is_identity=0 AND is_computed=0 AND system_type_id<>189 ORDER BY column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,1,N'');
  SET @InsertSql=N'INSERT dbo.DataDebtorCardMovement ('+@InsertCols+N') SELECT '+@InsertCols+N' FROM #TempMovement WHERE DebtorCardId=@id AND TRY_CONVERT(INT,SeqNo) BETWEEN @seq+1 AND @seq+4';
  EXEC sys.sp_executesql @InsertSql,N'@id NVARCHAR(150),@seq INT',@id=@DataDebtorCardId,@seq=@BaseSeq;
  IF (SELECT COUNT(*) FROM dbo.DataDebtorCardMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo) BETWEEN @BaseSeq+1 AND @BaseSeq+4)<>4 THROW 54008,N'Movement persistence failed',1;
  -- Update only modified installment records (primary key, not Seq).
  UPDATE p SET p.PaymentDate=CASE WHEN ISNULL(t.PaymentAmount,0)>ISNULL(p.PaymentAmount,0) THEN @ActualPayDate ELSE p.PaymentDate END,
    p.PaymentAmount=t.PaymentAmount,p.PrincipalPay=t.PrincipalPay,p.AccruedInterestPay=t.AccruedInterestPay,
    p.IsPayment=t.IsPayment,p.OverdueAmount=t.OverdueAmount,
    p.PrincipalOverdueAmount=t.PrincipalOverdueAmount,p.AccruedInterestOverdueAmount=t.AccruedInterestOverdueAmount,
    p.UpdateDate=GETDATE(),p.UpdateBy=@CreateBy
  FROM dbo.TDRDataCompromiseContractInstallmentPlanPayment p
  JOIN #TempInstallmentPlanPayment t ON t.CompromiseContractInstallmentPlanPaymentId=p.CompromiseContractInstallmentPlanPaymentId
  WHERE p.DataDebtorCardId=@DataDebtorCardId AND
    (ISNULL(p.PaymentAmount,0)<>ISNULL(t.PaymentAmount,0) OR ISNULL(p.PrincipalPay,0)<>ISNULL(t.PrincipalPay,0) OR ISNULL(p.AccruedInterestPay,0)<>ISNULL(t.AccruedInterestPay,0));
  UPDATE c SET c.DFDDate=CASE WHEN m.DFDDate>'19000101' AND (c.DFDDate IS NULL OR m.DFDDate>c.DFDDate) THEN m.DFDDate ELSE c.DFDDate END,
    c.SeqCurrent=@BaseSeq+4,c.SeqNext=@BaseSeq+5,
    c.InterestStartDate=@ActualPayDate,c.InterestEndDate=@ActualPayDate
  FROM dbo.DataDebtorCard c JOIN #TempMovement m ON m.DebtorCardId=c.DataDebtorCardId AND TRY_CONVERT(INT,m.SeqNo)=@BaseSeq+4
  WHERE c.DataDebtorCardId=@DataDebtorCardId;
  -- Sync card ledger totals before SP039, which reads card totals from permanent data.
  UPDATE c SET c.PrincipalTotal=m.PrincipalTotal,
    c.CourtFeeTotal=m.CourtFeeTotal,c.LawyerFeeTotal=m.LawyerFeeTotal,
    c.OtherExpenseTotal=m.OtherExpenseTotal,c.InitialMarginTotal=m.InitialMarginTotal,
    c.SuspendIntTotal=m.SuspendIntTotal,c.DeferredInterestTotal=m.DeferredInterestTotal,
    c.SuspendedDefaultInterestTotal=m.SuspendedDefaultInterestTotal,
    c.PlannedInterestTotal=m.PlannedInterestTotal,c.DefaultInterestTotal=m.DefaultInterestTotal,
    c.AccruedInterestTotal=m.AccruedInterestTotal
  FROM dbo.DataDebtorCard c JOIN #TempMovement m ON m.DebtorCardId=c.DataDebtorCardId AND TRY_CONVERT(INT,m.SeqNo)=@BaseSeq+4
  WHERE c.DataDebtorCardId=@DataDebtorCardId;
  IF OBJECT_ID(N'dbo.SP_DCS_039_InsertReceipt',N'P') IS NULL THROW 54010,N'SP039 not found',1;
  IF @AccountUserId IS NULL OR NULLIF(LTRIM(RTRIM(@DebtorPaymentName)),N'') IS NULL
   THROW 54009,N'AccountUserId and DebtorPaymentName are required for receipt',1;
  DECLARE @ReceiptDate DATETIME, @PaymentAmount DECIMAL(20,4),@PrincipalPayFinal DECIMAL(20,4),
   @AccruedPayFinal DECIMAL(20,4),@CourtFeePayFinal DECIMAL(20,4),@LawyerFeePayFinal DECIMAL(20,4),
   @OtherExpensePayFinal DECIMAL(20,4),@InitialMarginPayFinal DECIMAL(20,4),
   @CourtFeeTotalFinal DECIMAL(20,4),@LawyerFeeTotalFinal DECIMAL(20,4),
   @OtherExpenseTotalFinal DECIMAL(20,4),@InitialMarginTotalFinal DECIMAL(20,4),
   @SuspendIntTotalFinal DECIMAL(20,4),@DeferredInterestTotalFinal DECIMAL(20,4),
   @SuspendedDefaultInterestTotalFinal DECIMAL(20,4),@PlannedInterestTotalFinal DECIMAL(20,4),
   @DefaultInterestTotalFinal DECIMAL(20,4),@AccruedInterestTotalFinal DECIMAL(20,4);
  SELECT @ReceiptDate=DocDate,@PaymentAmount=TotalPay,@PrincipalPayFinal=PrincipalPay,
   @AccruedPayFinal=AccruedInterestPay,@CourtFeePayFinal=CourtFeePay,@LawyerFeePayFinal=LawyerFeePay,
   @OtherExpensePayFinal=OtherExpensePay,@InitialMarginPayFinal=InitialMarginPay,
   @CourtFeeTotalFinal=CourtFeeTotal,@LawyerFeeTotalFinal=LawyerFeeTotal,
   @OtherExpenseTotalFinal=OtherExpenseTotal,@InitialMarginTotalFinal=InitialMarginTotal,
   @SuspendIntTotalFinal=SuspendIntTotal,@DeferredInterestTotalFinal=DeferredInterestTotal,
   @SuspendedDefaultInterestTotalFinal=SuspendedDefaultInterestTotal,@PlannedInterestTotalFinal=PlannedInterestTotal,
   @DefaultInterestTotalFinal=DefaultInterestTotal,@AccruedInterestTotalFinal=AccruedInterestTotal
  FROM #TempMovement WHERE DebtorCardId=@DataDebtorCardId AND TRY_CONVERT(INT,SeqNo)=@BaseSeq+3;
  SET @ReceiptSeqCurrent=@BaseSeq+3;
  EXEC dbo.SP_DCS_039_InsertReceipt
   @SystemId=4,@DocumentId=9,@DebtorCardId=@DataDebtorCardId,
   @ReceiptDate=@ReceiptDate,@CreateBy=@CreateBy,@AccountUserId=@AccountUserId,
   @DebtorPaymentName=@DebtorPaymentName,@PaymentAmount=@PaymentAmount,
   @PrincipalPay=@PrincipalPayFinal,@AccruedInterestPay=@AccruedPayFinal,
   @CourtFeePay=@CourtFeePayFinal,@LawyerFeePay=@LawyerFeePayFinal,
   @OtherExpensePay=@OtherExpensePayFinal,@InitialMarginPay=@InitialMarginPayFinal,
   @CourtFeeTotal=@CourtFeeTotalFinal,@LawyerFeeTotal=@LawyerFeeTotalFinal,
   @OtherExpenseTotal=@OtherExpenseTotalFinal,@InitialMarginTotal=@InitialMarginTotalFinal,
   @SuspendIntTotal=@SuspendIntTotalFinal,@DeferredInterestTotal=@DeferredInterestTotalFinal,
   @SuspendedDefaultInterestTotal=@SuspendedDefaultInterestTotalFinal,
   @PlannedInterestTotal=@PlannedInterestTotalFinal,@DefaultInterestTotal=@DefaultInterestTotalFinal,
   @AccruedInterestTotal=@AccruedInterestTotalFinal,
   @EStatementId = @EStatementId,
@SeqCurrent = @ReceiptSeqCurrent,
@CallerHandlesTxn = 1;
  SELECT SeqNo,TypeId,TotalPay,PrincipalPay,SuspendIntPay,DefaultInterestPay,PrincipalTotal,DFDDate,DPD,DPDAccumulate FROM #TempMovement ORDER BY TRY_CONVERT(INT,SeqNo);

  SELECT *
FROM #TempMovement
WHERE DebtorCardId = @DataDebtorCardId
ORDER BY TRY_CONVERT(INT, SeqNo);

  IF @Commit=1 COMMIT TRANSACTION; ELSE ROLLBACK TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
  THROW;
 END CATCH
END;

-- ============================================================
-- SP_DCS_GetTrackingRecord
-- Replaces the GetTrackingList LINQ query in TrackingStatusCollector.cs
-- for /TrackingCollector/GetTrackingRecord endpoint
-- ============================================================
CREATE   PROCEDURE [dbo].[SP_DCS_GetTrackingRecord]
    @CurrentPage     INT,
    @PageSize        INT,
    @SearchTypesCsv  NVARCHAR(500)  = NULL,
    @Keyword         NVARCHAR(500)  = NULL,
    @StartDPDValue   INT            = 0,
    @EndDPDValue     INT            = 0,
    @StartDate       DATETIME       = NULL,
    @EndDate         DATETIME       = NULL,
    @StartDFDDate    DATETIME       = NULL,
    @EndDFDDate      DATETIME       = NULL,
    @IsManager       INT            = NULL,
    @UserId          INT,
    @OrgSectionId    INT            = 0,
    @OrgStructureId  INT            = 0,
    @UserIdListCsv   NVARCHAR(MAX)  = NULL,
    @ProvinceId      INT            = 0,
    @DistrictId      INT            = 0,
    @DueDateType     INT            = 0,
    @StatusPort      INT            = 0,
    @StatusDebtor    INT            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    /* ── Date helpers ── */
    DECLARE @Today     DATE     = CAST(GETDATE() AS DATE);
    DECLARE @FirstDay  DATETIME = DATEFROMPARTS(YEAR(@Today), MONTH(@Today), 1);
    DECLARE @NextMonth DATETIME = DATEADD(MONTH, 1, @FirstDay);
    DECLARE @LastDay   INT      = DAY(EOMONTH(GETDATE()));

    /* ── Parse UserIdList ── */
    CREATE TABLE #UserIds (UserId INT NOT NULL PRIMARY KEY);
    IF @UserIdListCsv IS NOT NULL AND LEN(LTRIM(RTRIM(@UserIdListCsv))) > 0
        INSERT INTO #UserIds
        SELECT CAST(value AS INT)
        FROM STRING_SPLIT(@UserIdListCsv, ',')
        WHERE ISNUMERIC(value) = 1;

    /* ── Admin check ── */
    DECLARE @IsAdmin BIT = 0;
    IF EXISTS (
        SELECT 1 FROM DataUserRoles WITH (NOLOCK)
        WHERE UserId = @UserId AND RoleId IN (1, 2)
    )
        SET @IsAdmin = 1;

    IF @IsAdmin = 1 SET @IsManager = NULL;

    /* ── OA flag ── */
    DECLARE @IsOA         BIT = CASE WHEN @IsAdmin = 0 AND @OrgStructureId = 47 THEN 1 ELSE 0 END;
    DECLARE @TypeAssignId INT = CASE WHEN @IsOA = 1 THEN 2 ELSE 1 END;

    /* ── ManagerOrgSectionId ── */
    DECLARE @ManagerOrgSectionId INT = NULL;
    IF @IsAdmin = 0 AND @IsManager = 1 SET @ManagerOrgSectionId = @OrgSectionId;

    /* ══════════════════════════════════════════════════════════
       Phase 0 – Eligible assignments
       COLLATE DATABASE_DEFAULT บน NVARCHAR ทุก column
       เพื่อแก้ปัญหา collation conflict กับ tempdb
    ══════════════════════════════════════════════════════════ */
    CREATE TABLE #Eligible (
        DebtorRelateId  NVARCHAR(50) COLLATE DATABASE_DEFAULT NOT NULL,
        TypeAssignId    TINYINT      NOT NULL,
        CollectorId     INT          NULL
    );
    CREATE INDEX IX_Elig_RelId ON #Eligible (DebtorRelateId);

    IF @IsAdmin = 1
    BEGIN
        INSERT INTO #Eligible
        SELECT DebtorRelateId, TypeAssignId, MAX(CollectorId)
        FROM (
            SELECT
                DebtorRelateId,
                TypeAssignId,
                CASE WHEN TypeAssignId = 2 THEN CollectorOAUserId ELSE CollectorUserId END AS CollectorId
            FROM DataAssignment WITH (NOLOCK)
            WHERE CollectorUserId <> 0 OR CollectorOAUserId <> 0
        ) x
        GROUP BY DebtorRelateId, TypeAssignId;
    END
    ELSE
    BEGIN
        INSERT INTO #Eligible
        SELECT DebtorRelateId, @TypeAssignId, MAX(CollectorId)
        FROM (
            SELECT
                DebtorRelateId,
                CASE WHEN @IsOA = 1 THEN CollectorOAUserId ELSE CollectorUserId END AS CollectorId
            FROM DataAssignment WITH (NOLOCK)
            WHERE TypeAssignId = @TypeAssignId
              AND (
                    (@IsManager = 0 AND (CASE WHEN @IsOA = 1 THEN CollectorOAUserId ELSE CollectorUserId END) = @UserId)
                 OR (
    @IsManager = 1 
    AND (CASE WHEN @IsOA = 1 THEN CollectorOAUserId ELSE CollectorUserId END) = @UserId
)
                 OR (@IsManager = 2 AND (CASE WHEN @IsOA = 1 THEN CollectorOAUserId ELSE CollectorUserId END) IN (SELECT UserId FROM #UserIds))
              )
        ) x
        GROUP BY DebtorRelateId;
    END;

    /* ══════════════════════════════════════════════════════════
       Phase 1 – Build candidates
    ══════════════════════════════════════════════════════════ */
    CREATE TABLE #Candidates (
        LGNo           NVARCHAR(50)  COLLATE DATABASE_DEFAULT NOT NULL,
        DebtorRelateId NVARCHAR(50)  COLLATE DATABASE_DEFAULT NOT NULL,
        CIFNo          NVARCHAR(50)  COLLATE DATABASE_DEFAULT NULL,
        DebtorCode     NVARCHAR(50)  COLLATE DATABASE_DEFAULT NULL,
        DebtorId       NVARCHAR(50)  COLLATE DATABASE_DEFAULT NOT NULL,
        CollectorId    INT           NULL,
        TypeAssignId   TINYINT       NOT NULL,
        ClaimPayDate   DATETIME      NULL,
        DFDDate        DATETIME      NULL,
        DPD            INT           NOT NULL DEFAULT 0,
        DebtorName     NVARCHAR(300) COLLATE DATABASE_DEFAULT NULL,
        CntPhoneNumber NVARCHAR(100) COLLATE DATABASE_DEFAULT NULL,
        DebtorTypeName NVARCHAR(100) COLLATE DATABASE_DEFAULT NULL,
        DueDateRaw     DATETIME      NULL,
        ProvinceId     INT           NULL,
        DistrictId     INT           NULL
    );
    CREATE INDEX IX_Cand_LGNo  ON #Candidates (LGNo);
    CREATE INDEX IX_Cand_RelId ON #Candidates (DebtorRelateId);

    INSERT INTO #Candidates
    SELECT
        r.LGNo,
        r.DebtorRelateId,
        r.CIFNo,
        d.DebtorCode,
        d.DebtorId,
        e.CollectorId,
        e.TypeAssignId,
        card.ClaimPayDate,
        card.DFDDate,
        ISNULL(card.DPD, 0),
        CASE
            WHEN d.PersonGroupId = 118
                THEN LTRIM(RTRIM(ISNULL(d.DebtorName, '')))
            ELSE
                LTRIM(RTRIM(
                    ISNULL(t.TitleShortName, '') + ' '
                    + ISNULL(d.FirstName, '') + ' '
                    + ISNULL(d.LastName, '')
                ))
        END,
        d.CntPhoneNumber,
        dt.DebtorTypeName,
        cp.DueDate,
        addr.ProvinceId,
        addr.DistrictId
    FROM #Eligible e
    JOIN DataDebtorRelate r WITH (NOLOCK) ON r.DebtorRelateId = e.DebtorRelateId
                                           AND r.DebtorTypeId = 1
    JOIN DataLG lg            WITH (NOLOCK) ON lg.LGNo = r.LGNo AND lg.Grade = 'F1'
    JOIN DataDebtor d          WITH (NOLOCK) ON d.DebtorId = r.DebtorId
    LEFT JOIN SystemTitleMaster t  WITH (NOLOCK) ON t.TitleId = d.TitleId
    LEFT JOIN SystemDebtorType dt  WITH (NOLOCK) ON dt.DebtorTypeId = r.DebtorTypeId
    CROSS APPLY (
        SELECT TOP 1 ClaimPayDate, DFDDate, DPD, DebtorCardCode
        FROM DataDebtorCard WITH (NOLOCK)
        WHERE DebtorRelateId = r.DebtorRelateId
        ORDER BY ClaimPayDate DESC
    ) card
    OUTER APPLY (
        SELECT TOP 1 ProvinceId, DistrictId
        FROM DataDebtorAddress WITH (NOLOCK)
        WHERE DebtorId = d.DebtorId AND DebtorAddressTypeId = 7
        ORDER BY ProvinceId
    ) addr
    OUTER APPLY (
        SELECT TOP 1 p.DueDate
        FROM TDRDataCompromiseContractInstallmentPlan p WITH (NOLOCK)
        WHERE p.LGNo = r.LGNo
          AND p.DueDate >= @FirstDay
          AND p.DueDate <  @NextMonth
        ORDER BY p.DueDate DESC
    ) cp
    WHERE EXISTS (
        SELECT 1 FROM DataDebtorStatusUpdate WITH (NOLOCK)
        WHERE DebtorRelateId = r.DebtorRelateId
          AND DebtorTypeId   = 1
          --AND StatusSubTrackingId IS NOT NULL
          --AND StatusSubTrackingId <> 0
    );

    /* ══════════════════════════════════════════════════════════
       Phase 2 – Apply filters
    ══════════════════════════════════════════════════════════ */
    IF @StartDate IS NOT NULL AND @EndDate IS NOT NULL
        DELETE FROM #Candidates WHERE ClaimPayDate < @StartDate OR ClaimPayDate > @EndDate;

    IF @StartDFDDate IS NOT NULL AND @EndDFDDate IS NOT NULL
        DELETE FROM #Candidates WHERE DFDDate < @StartDFDDate OR DFDDate > @EndDFDDate;

    IF @StartDPDValue > 0 AND @EndDPDValue > 0
        DELETE FROM #Candidates WHERE DPD < @StartDPDValue OR DPD > @EndDPDValue;
    ELSE IF @StartDPDValue > 0
        DELETE FROM #Candidates WHERE DPD < @StartDPDValue;
    ELSE IF @EndDPDValue > 0
        DELETE FROM #Candidates WHERE DPD > @EndDPDValue;

    IF @ProvinceId <> 0
    BEGIN
        DELETE FROM #Candidates WHERE ProvinceId <> @ProvinceId;
        IF @DistrictId <> 0
            DELETE FROM #Candidates WHERE DistrictId <> @DistrictId;
    END;

    IF @DueDateType = 1 DELETE FROM #Candidates WHERE DueDateRaw IS NULL OR DAY(DueDateRaw) <> 5;
    ELSE IF @DueDateType = 2 DELETE FROM #Candidates WHERE DueDateRaw IS NULL OR DAY(DueDateRaw) <> 15;
    ELSE IF @DueDateType = 3 DELETE FROM #Candidates WHERE DueDateRaw IS NULL OR DAY(DueDateRaw) <> 25;
    ELSE IF @DueDateType = 4 DELETE FROM #Candidates WHERE DueDateRaw IS NULL OR DAY(DueDateRaw) <> @LastDay;

    IF @SearchTypesCsv IS NOT NULL AND @SearchTypesCsv LIKE N'%ครบกำหนดชำระ%'
        DELETE FROM #Candidates
        WHERE DueDateRaw IS NULL
           OR CAST(DueDateRaw AS DATE) > @Today
           OR CAST(DueDateRaw AS DATE) < DATEADD(DAY, -5, @Today);

    IF @Keyword IS NOT NULL AND LEN(LTRIM(@Keyword)) > 0
       AND @SearchTypesCsv IS NOT NULL AND LEN(LTRIM(@SearchTypesCsv)) > 0
    BEGIN
        DECLARE @Like          NVARCHAR(502) = N'%' + @Keyword + N'%';
        DECLARE @SrchLgNo      BIT = 0, @SrchCifNo   BIT = 0, @SrchCode  BIT = 0,
                @SrchName      BIT = 0, @SrchPhone    BIT = 0, @SrchType  BIT = 0,
                @SrchJobStatus BIT = 0, @SrchPort     BIT = 0;

        SELECT
            @SrchLgNo      = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'lgNo'           THEN 1 ELSE 0 END),
            @SrchCifNo     = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'cifNo'          THEN 1 ELSE 0 END),
            @SrchCode      = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'debtorCode'     THEN 1 ELSE 0 END),
            @SrchName      = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'debtorName'     THEN 1 ELSE 0 END),
            @SrchPhone     = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'debtorPhone'    THEN 1 ELSE 0 END),
            @SrchType      = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'debtorTypeName' THEN 1 ELSE 0 END),
            @SrchJobStatus = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'jobstatus'      THEN 1 ELSE 0 END),
            @SrchPort      = MAX(CASE WHEN LTRIM(RTRIM(value)) = 'port'           THEN 1 ELSE 0 END)
        FROM STRING_SPLIT(@SearchTypesCsv, ',');

        DELETE FROM #Candidates
        WHERE NOT (
            (@SrchLgNo  = 1 AND LGNo          LIKE @Like)
         OR (@SrchCifNo = 1 AND CIFNo          LIKE @Like)
         OR (@SrchCode  = 1 AND DebtorCode     LIKE @Like)
         OR (@SrchName  = 1 AND DebtorName     LIKE @Like)
         OR (@SrchPhone = 1 AND CntPhoneNumber LIKE @Like)
         OR (@SrchType  = 1 AND DebtorTypeName LIKE @Like)
         OR (@SrchJobStatus = 1 AND EXISTS (
                SELECT 1
                FROM DataDebtorStatusUpdate su WITH (NOLOCK)
                LEFT JOIN SystemStatusMaster sm      WITH (NOLOCK) ON sm.SystemStatusId = su.StatusSubTrackingId
                WHERE su.DebtorRelateId = #Candidates.DebtorRelateId
                  AND su.DebtorTypeId   = 1
                  --AND su.StatusSubTrackingId IS NOT NULL
                  --AND su.StatusSubTrackingId <> 0
                  AND sm.StatusName LIKE @Like
            ))
         OR (@SrchPort = 1 AND EXISTS (
                SELECT 1
                FROM DataDebtorStatusUpdate su WITH (NOLOCK)
                JOIN SystemStatusMaster sm      WITH (NOLOCK) ON sm.SystemStatusId = su.StatusPortId
                WHERE su.DebtorRelateId = #Candidates.DebtorRelateId
                  AND su.DebtorTypeId   = 1
                  AND sm.StatusName LIKE @Like
            ))
        );
    END;
    /* ════════════════════════════════════════════════════════════════════
       Phase 2.2 – StatusPort / StatusDebtor filters TotalCount ก่อน Paging
    ══════════════════════════════════════════════════════════════════════ */

    CREATE TABLE #Candidates2 (
        LGNo           NVARCHAR(50)  COLLATE DATABASE_DEFAULT NOT NULL,
        DebtorRelateId NVARCHAR(50)  COLLATE DATABASE_DEFAULT NOT NULL,
        CIFNo          NVARCHAR(50)  COLLATE DATABASE_DEFAULT NULL,
        DebtorCode     NVARCHAR(50)  COLLATE DATABASE_DEFAULT NULL,
        DebtorId       NVARCHAR(50)  COLLATE DATABASE_DEFAULT NOT NULL,
        CollectorId    INT           NULL,
        TypeAssignId   TINYINT       NOT NULL,
        ClaimPayDate   DATETIME      NULL,
        DFDDate        DATETIME      NULL,
        DPD            INT           NOT NULL DEFAULT 0,
        DebtorName     NVARCHAR(300) COLLATE DATABASE_DEFAULT NULL,
        CntPhoneNumber NVARCHAR(100) COLLATE DATABASE_DEFAULT NULL,
        DebtorTypeName NVARCHAR(100) COLLATE DATABASE_DEFAULT NULL,
        DueDateRaw     DATETIME      NULL,
        ProvinceId     INT           NULL,
        DistrictId     INT           NULL
    );

    CREATE INDEX IX_Cand2_LGNo  ON #Candidates2 (LGNo);
    CREATE INDEX IX_Cand2_RelId ON #Candidates2 (DebtorRelateId);

    IF @StatusPort = 0 AND @StatusDebtor = 0
    BEGIN
        INSERT INTO #Candidates2
        SELECT *
        FROM #Candidates;
    END
    ELSE
    BEGIN
        INSERT INTO #Candidates2
        SELECT c.*
        FROM #Candidates c
        OUTER APPLY (
            SELECT TOP 1
                su.StatusTrackingId,
                su.StatusDebtorId
            FROM DataDebtorStatusUpdate su WITH (NOLOCK)
            WHERE su.DebtorRelateId = c.DebtorRelateId
              AND su.DebtorTypeId = 1
            ORDER BY su.StatusTrackingDate DESC
        ) ddsu
        WHERE
            (
                @StatusPort = 0
                OR ISNULL(ddsu.StatusTrackingId, 0) = @StatusPort
            )
            AND
            (
                @StatusDebtor = 0
                OR ISNULL(ddsu.StatusDebtorId, 0) = @StatusDebtor
            );
    END;
    /* ══════════════════════════════════════════════════════════
       Phase 3 – Deduplicate to one row per LGNo
    ══════════════════════════════════════════════════════════ */
    CREATE TABLE #PageKeys (
        LGNo           NVARCHAR(50) COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
        MaxClaim       DATETIME     NULL,
        DebtorRelateId NVARCHAR(50) COLLATE DATABASE_DEFAULT NOT NULL,
        CollectorId    INT          NULL,
        TypeAssignId   TINYINT      NOT NULL
    );

    ;WITH MaxPerLG AS (
        SELECT LGNo, MAX(ClaimPayDate) AS MaxClaim
        FROM #Candidates2
        GROUP BY LGNo
    ),
    Ranked AS (
        SELECT
            c.LGNo, c.DebtorRelateId, c.ClaimPayDate, c.CollectorId, c.TypeAssignId,
            ROW_NUMBER() OVER (PARTITION BY c.LGNo ORDER BY c.DebtorRelateId) AS rn
        FROM #Candidates2 c
        JOIN MaxPerLG m ON m.LGNo = c.LGNo AND m.MaxClaim = c.ClaimPayDate
    )
    INSERT INTO #PageKeys
    SELECT LGNo, ClaimPayDate, DebtorRelateId, CollectorId, TypeAssignId
    FROM Ranked
    WHERE rn = 1;

    DECLARE @TotalCount INT = (SELECT COUNT(*) FROM #PageKeys);

    /* ══════════════════════════════════════════════════════════
       Phase 4 – Paging
    ══════════════════════════════════════════════════════════ */
    CREATE TABLE #Page (
        LGNo           NVARCHAR(50) COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
        MaxClaim       DATETIME     NULL,
        DebtorRelateId NVARCHAR(50) COLLATE DATABASE_DEFAULT NOT NULL,
        CollectorId    INT          NULL,
        TypeAssignId   TINYINT      NOT NULL
    );

    INSERT INTO #Page
    SELECT LGNo, MaxClaim, DebtorRelateId, CollectorId, TypeAssignId
    FROM #PageKeys
    ORDER BY ISNULL(MaxClaim, '19000101') DESC, LGNo
    OFFSET (@CurrentPage - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    IF NOT EXISTS (SELECT 1 FROM #Page)
    BEGIN
        SELECT @TotalCount AS TotalCount WHERE 1 = 0;
        RETURN;
    END;

    /* ══════════════════════════════════════════════════════════
       Phase 5 – Pre-fetch latest status for paged rows
    ══════════════════════════════════════════════════════════ */
    CREATE TABLE #LatestJob (
        DebtorRelateId      NVARCHAR(50) COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
        StatusTrackingId    INT          NULL,
        StatusSubTrackingId INT          NULL
    );
    INSERT INTO #LatestJob
    SELECT pg.DebtorRelateId, js.StatusTrackingId, js.StatusSubTrackingId
    FROM #Page pg
    CROSS APPLY (
        SELECT TOP 1 StatusTrackingId, StatusSubTrackingId
        FROM DataDebtorStatusUpdate WITH (NOLOCK)
        WHERE DebtorRelateId     = pg.DebtorRelateId
          AND DebtorTypeId       = 1
          --AND StatusSubTrackingId IS NOT NULL
          --AND StatusSubTrackingId <> 0
        ORDER BY StatusTrackingDate DESC
    ) js;

    CREATE TABLE #LatestDebtor (
        DebtorRelateId NVARCHAR(50) COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
        StatusDebtorId INT          NULL,
        StatusPortId   INT          NULL
    );
    INSERT INTO #LatestDebtor
    SELECT pg.DebtorRelateId, ds.StatusDebtorId, ds.StatusPortId
    FROM #Page pg
    CROSS APPLY (
        SELECT TOP 1 StatusDebtorId, StatusPortId
        FROM DataDebtorStatusUpdate WITH (NOLOCK)
        WHERE DebtorRelateId = pg.DebtorRelateId
        ORDER BY StatusTrackingDate DESC
    ) ds;

    /* ══════════════════════════════════════════════════════════
       Phase 6 – Final result set
    ══════════════════════════════════════════════════════════ */
    SELECT
        r.DebtorRelateId,
        r.CIFNo,
        r.LGNo,
        card.DebtorCardCode,
        d.DebtorCode,
        d.DebtorId,
        ISNULL(t.TitleShortName, '')  AS DebtorTitle,
        ISNULL(d.FirstName,      '')  AS DebtorFirstName,
        ISNULL(d.LastName,       '')  AS DebtorLastName,
        LTRIM(RTRIM(
                    ISNULL(t.TitleShortName, '') + ' '
                    + ISNULL(d.FirstName, '') + ' '
                    + ISNULL(d.LastName,  '')
                )) AS DebtorName,
        d.CntPhoneNumber              AS DebtorPhone,
        ISNULL(ram.OrgSectionId,  0)  AS OrgSectionId,
        ISNULL(dt.DebtorTypeName, '') AS DebtorTypeName,
        card.ClaimPayDate,
        card.DFDDate,
        ISNULL(card.DPD, 0)           AS DPD,
        pg.CollectorId,
        lj.StatusTrackingId           AS JobGroupStatusId,
        sm_job.StatusCode             AS JobGroupStatusCode,
        sm_job.StatusName             AS JobGroupStatusName,
        sm_sub.StatusName             AS SubJobStatus,
        ISNULL(ld.StatusDebtorId, 0)  AS DebtorGroupStatusId,
        sm_deb.StatusCode             AS DebtorGroupStatusCode,
        sm_deb.StatusName             AS DebtorGroupStatusName,
        sm_port.StatusName            AS PortStatus,
        r.IsFirstCall,
        r.IsManualCall,
        addr.ProvinceId,
        addr.DistrictId,
        prov.Name                     AS ProvinceName,
        dist.Name                     AS DistrictName,
        trk.TransactionTrackingDate,
        cp.DueDate,
        @TotalCount                   AS TotalCount
    FROM #Page pg
    JOIN  DataDebtorRelate r    WITH (NOLOCK) ON r.DebtorRelateId = pg.DebtorRelateId
    JOIN  DataDebtor d          WITH (NOLOCK) ON d.DebtorId = r.DebtorId
    LEFT  JOIN SystemTitleMaster t   WITH (NOLOCK) ON t.TitleId    = d.TitleId
    LEFT  JOIN SystemDebtorType  dt  WITH (NOLOCK) ON dt.DebtorTypeId = r.DebtorTypeId
    CROSS APPLY (
        SELECT TOP 1 DebtorCardCode, ClaimPayDate, DFDDate, DPD
        FROM DataDebtorCard WITH (NOLOCK)
        WHERE DebtorRelateId = r.DebtorRelateId
        ORDER BY ClaimPayDate DESC
    ) card
    OUTER APPLY (
        SELECT TOP 1 ProvinceId, DistrictId
        FROM DataDebtorAddress WITH (NOLOCK)
        WHERE DebtorId = d.DebtorId AND DebtorAddressTypeId = 7 AND IsDefault = 1
        ORDER BY ProvinceId
    ) addr
    OUTER APPLY (
        SELECT TOP 1 OrgSectionId
        FROM SystemResponsibleAreaMaster WITH (NOLOCK)
        WHERE ProvinceId = addr.ProvinceId
          AND (@ManagerOrgSectionId IS NULL OR OrgSectionId = @ManagerOrgSectionId)
    ) ram
    LEFT  JOIN #LatestJob lj    ON lj.DebtorRelateId = r.DebtorRelateId
    LEFT  JOIN SystemStatusMaster sm_job  WITH (NOLOCK) ON sm_job.SystemStatusId  = lj.StatusTrackingId
    LEFT  JOIN SystemStatusMaster sm_sub  WITH (NOLOCK) ON sm_sub.SystemStatusId  = lj.StatusSubTrackingId
    LEFT  JOIN #LatestDebtor ld ON ld.DebtorRelateId = r.DebtorRelateId
    LEFT  JOIN SystemStatusMaster sm_deb  WITH (NOLOCK) ON sm_deb.SystemStatusId  = ld.StatusDebtorId
    LEFT  JOIN SystemStatusMaster sm_port WITH (NOLOCK) ON sm_port.SystemStatusId = ld.StatusPortId
    LEFT  JOIN SystemProvinceMaster prov  WITH (NOLOCK) ON prov.ProvinceId = addr.ProvinceId
    LEFT  JOIN SystemDistrictMaster dist  WITH (NOLOCK) ON dist.DistrictId  = addr.DistrictId
    OUTER APPLY (
        SELECT TOP 1 TransactionTrackingDate
        FROM DEBDataTransactionTracking WITH (NOLOCK)
        WHERE DebtorId = d.DebtorId
        ORDER BY TransactionTrackingDate DESC
    ) trk
    OUTER APPLY (
        SELECT TOP 1 p.DueDate
        FROM TDRDataCompromiseContractInstallmentPlan p WITH (NOLOCK)
        JOIN TDRDataCompromiseContract c WITH (NOLOCK) ON c.CompromiseContractId = p.CompromiseContractId
        WHERE c.CompromiseContractStatusId = 58
          AND p.DueDate >= @FirstDay
          AND p.DueDate <  @NextMonth
          AND p.LGNo    =  r.LGNo
        ORDER BY p.DueDate DESC
    ) cp
    ORDER BY ISNULL(card.ClaimPayDate, '19000101') DESC, r.LGNo;

END;

CREATE PROCEDURE [dbo].[SP_DCS_RunSuspendInterest_Daily]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @CurrentDate           date = cast('2025-06-15' as date),
        @DataDebtorCardId      nvarchar(150),
        @CompromiseContractId  nvarchar(150);

    -- Cursor สำหรับวนทุกบรรทัดที่ตรงเงื่อนไขวันนี้
    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT DISTINCT
            cp.DataDebtorCardId,
            cp.CompromiseContractId
        FROM TDRDataCompromiseContractInstallmentPlanPayment cp
        LEFT JOIN TDRDataCompromiseContract c ON c.CompromiseContractId = cp.CompromiseContractId
        LEFT JOIN TDRDataCompromiseContractLG clg ON clg.CompromiseContractId = cp.CompromiseContractId
        WHERE 
            c.CompromiseContractStatusId = 58
            AND CONVERT(date, clg.StartInstallmentPeriod) = @CurrentDate;  -- เทียบแค่ date

    OPEN cur;

    FETCH NEXT FROM cur INTO @DataDebtorCardId, @CompromiseContractId;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- รัน stored ตัวหลักทีละบรรทัด
        EXEC [dbo].[SP_DCS_Card_015_SuspendInterest] 
              @DataDebtorCardId     = @DataDebtorCardId,
              @CompromiseContractId = @CompromiseContractId;

        FETCH NEXT FROM cur INTO @DataDebtorCardId, @CompromiseContractId;
    END

    CLOSE cur;
    DEALLOCATE cur;
END

CREATE   PROCEDURE dbo.SP_DEB_001_UpdateAssignmentOriginal_Batch
