CREATE   PROCEDURE dbo.SP_DEB_003_UpdateAssignmentOA_Batch
    @Items dbo.AssignmentLgContext READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- validate: กันข้อมูลไม่ครบแล้วไปพังตอน EXEC
    IF EXISTS (
        SELECT 1
        FROM @Items
        WHERE LGNo IS NULL
           OR CIFNo IS NULL
           OR DebtorCode IS NULL
           OR DebtorRelateId IS NULL
           OR OAGroupId IS NULL
    )
    BEGIN
        THROW 50010, N'AssignmentLgContext มีข้อมูลไม่ครบสำหรับ SP_DEB_003 (ต้องมี LGNo,CIFNo,DebtorCode,DebtorRelateId,OAGroupId)', 1;
