    DECLARE
        @LGNo NVARCHAR(50),
        @CIFNo NVARCHAR(50),
        @DebtorCode NVARCHAR(50),
        @DebtorRelateId NVARCHAR(150),
        @OAGroupId INT;

    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT LGNo, CIFNo, DebtorCode, DebtorRelateId, OAGroupId
        FROM @Items;

    OPEN cur;
    FETCH NEXT FROM cur INTO @LGNo, @CIFNo, @DebtorCode, @DebtorRelateId, @OAGroupId;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC dbo.SP_DEB_003_UpdateAssignmentOA
            @LGNo = @LGNo,
            @CIFNo = @CIFNo,
            @DebtorCode = @DebtorCode,
            @DebtorRelateId = @DebtorRelateId,
            @OAGroupId = @OAGroupId;

        FETCH NEXT FROM cur INTO @LGNo, @CIFNo, @DebtorCode, @DebtorRelateId, @OAGroupId;
    END

    CLOSE cur;
    DEALLOCATE cur;
END

CREATE   PROCEDURE [dbo].[SP_DEB_004_UpdateAssignmentOriginalOAByProjectType]
	-- นำเข้าข้อมูลลูกหนี้ - ที่อยู่ DataDebtorAddress
  @LGNo NVARCHAR(50),
	@CIFNo NVARCHAR(50),
	@DebtorCode NVARCHAR(50),
	@DebtorRelateId NVARCHAR(50)
	
AS
BEGIN
  SET NOCOUNT ON;
	DECLARE @DebtorId nvarchar(100);
  DECLARE @CollectorOAUserId nvarchar(100);
  DECLARE @DebtorName nvarchar(100);
  DECLARE @ClaimPay DECIMAL(18,2);
  DECLARE @ClaimPayDate DATE;
 
  --หยิบข้อมูล Debtor ที่เป็นผู้กู้หลัก
--   SELECT @DebtorRelateId = DebtorRelateId, @DebtorId = DebtorId 
--   FROM DataDebtorRelate
--   WHERE DebtorTypeId = 1 AND LGNo = @LGNo
  
  -- ดึงภาระหนี้
  SELECT 
        @DebtorId = dr.DebtorId,
        @DebtorName = d.DebtorName,
        @ClaimPay = ISNULL(lg.ClaimPayAmount, 0),
        @ClaimPayDate = mc.ClaimPayDate
    FROM DataDebtorRelate dr
    JOIN DataDebtor d ON d.DebtorId = dr.DebtorId
    JOIN DataLG lg ON dr.LGNo = lg.LGNo
    JOIN DataMainCard mc ON dr.LGNo = mc.LGNo
    WHERE lg.LGNo = @LGNo
      AND dr.DebtorRelateId = @DebtorRelateId;
  
  
  DECLARE @OAGroupId INT;
  DECLARE @EffectiveDate DATE;
  DECLARE @RoundAssign NVARCHAR(50);
  
  --หยิบข้อมูลผู้ดูแลที่เป็น OA
  SELECT TOP 1 @CollectorOAUserId = a.CollectorOAUserId, @OAGroupId = c.OAGroupId, @EffectiveDate = C.EffectiveDate
  FROM DataAssignment a
  JOIN DataDebtorRelate b on a.DebtorRelateId = b.DebtorRelateId
  JOIN DEBDataAssignOA c on b.DebtorRelateId = c.DebtorRelateId
  JOIN DataLG d on c.LGNo = d.LGNo
--   JOIN SystemStatusMaster e on d.StatusId = e.StatusId
  Where b.DebtorId = @DebtorId AND a.LGNo <> @LGNo AND d.StatusId <> 6
  --AND e.StatusCode = '06' AND e.GroupStatusId <> '1'
     IF @CollectorOAUserId IS NULL
        RETURN 0;
        
   SELECT @RoundAssign = RoundCurrent
   FROM SystemAssignOAPeriodMaster
   WHERE IsActive = 1;
        
  
      -- 📝 Insert จ่ายงาน
    INSERT INTO DEBDataAssignOA (
        AssignOAId,
        DebtorRelateId,
        CollectorOAUserId,
        DebtorName,
        DebtorTypeId,
        ClaimPay,
        ClaimPayDate,
        RoudAssign,
        Seq,
        IsAssign,
        CreateDate,
        CreateBy,
        UpdateDate,
        UpdateBy,
        DebtorId,
        CIFNo,
        LGNo,
        OAGroupId
    )
    VALUES (
        NEWID(),
        @DebtorRelateId,
        @CollectorOAUserId,
        @DebtorName,
        1,
        @ClaimPay,
        @ClaimPayDate,
        @RoundAssign,
        1,
        0,
        GETDATE(),
        1,
        GETDATE(),
        1,
        @DebtorId,
        @CIFNo,
        @LGNo,
        @OAGroupId
    );
  
 
 
	Update a Set CollectorOAUserId = @CollectorOAUserId
	, IsOriginal =1 
	, IsShow = (case when r.DebtorTypeId=1 then 1 else 0 end)
	,TypeAssignId = 2
  from DataAssignment a
	left join DataDebtorRelate r on r.DebtorRelateId = a.DebtorRelateId
	where a.LGNo=@LGNo
  
  
  Update DataDebtorStatusUpdate 
    Set StatusAssignId = 132,
        StatusAssignDate = GETDATE(),
        --StatusTrackingId = 217,
        --StatusTrackingDate = GETDATE(),
        StatusSubTrackingId = 211,
        StatusSubTrackingDate = GETDATE(),
        CollectorOAUserId= @CollectorOAUserId, 
        CollectorOAUpdateDate = GETDATE()
     Where LGNo = @LGNo

	
		-- ✅ อัปเดตสถานะ DataDebtorTransactionStatus
--         UPDATE DataDebtorTransactionStatus
--         SET SystemStatusId = 132
--         WHERE DebtorRelateId = @DebtorRelateId
-- 		and GroupStatusId = 15;

END

