CREATE   PROCEDURE dbo.SP_DEB_005_UpdateAssignmentOriginalOAByClaimPayAmount_Batch
    @Items dbo.AssignmentLgContext READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS (
        SELECT 1 FROM @Items
        WHERE LGNo IS NULL OR CIFNo IS NULL OR DebtorCode IS NULL OR DebtorRelateId IS NULL
    )
    BEGIN
        THROW 50012, N'AssignmentLgContext มีข้อมูลไม่ครบสำหรับ SP_DEB_005 (ต้องมี LGNo,CIFNo,DebtorCode,DebtorRelateId)', 1;
    END

    DECLARE
        @LGNo NVARCHAR(50),
        @CIFNo NVARCHAR(50),
        @DebtorCode NVARCHAR(50),
        @DebtorRelateId NVARCHAR(50);

    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT LGNo, CIFNo, DebtorCode, DebtorRelateId
        FROM @Items;

    OPEN cur;
    FETCH NEXT FROM cur INTO @LGNo, @CIFNo, @DebtorCode, @DebtorRelateId;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC dbo.SP_DEB_005_UpdateAssignmentOriginalOAByClaimPayAmount
            @LGNo = @LGNo,
            @CIFNo = @CIFNo,
            @DebtorCode = @DebtorCode,
            @DebtorRelateId = @DebtorRelateId;

        FETCH NEXT FROM cur INTO @LGNo, @CIFNo, @DebtorCode, @DebtorRelateId;
    END

    CLOSE cur;
    DEALLOCATE cur;
END

CREATE PROCEDURE [dbo].[SP_DEB_006_CalInterate]
    @DebtBalance    DECIMAL(20,4) = 86503.72,
    @Date           DATE          = '2026-10-01',
    @DebtorRelateId NVARCHAR(150) = '0B989C66-9F6A-4C68-B608-D5EC16777CC0'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @LGNo NVARCHAR(20);

    --SELECT @LGNo = LGNo
    --FROM dbo.DataDebtorRelate
    --WHERE DebtorRelateId = @DebtorRelateId;

    --SET @DebtorRelateId =
    --(
    --    SELECT TOP 1 DebtorRelateId
    --    FROM dbo.DataDebtorRelate
    --    WHERE LGNo = @LGNo
    --      AND DebtorTypeId = 1
    --);

    IF @Date IS NULL
        SET @Date = CONVERT(DATE, GETDATE());

    DECLARE @CalcToDate DATE = CONVERT(DATE, @Date);

    DECLARE @DebtorCardId NVARCHAR(150);
    DECLARE @InterestRate DECIMAL(20,2);
    DECLARE @PrincipalTotal DECIMAL(20,2);
    DECLARE @LastAccruedInterestTotal DECIMAL(20,2);
    DECLARE @InterestEndDate DATE;
    DECLARE @InterestStartDate DATE;
    DECLARE @InterestDay INT;
    DECLARE @InterestAmount DECIMAL(20,2);
    DECLARE @AccruedInterestTotal DECIMAL(20,2);

    DECLARE @PayDate DATETIME;
    DECLARE @DocDate DATETIME;
    DECLARE @EffectiveDate DATE;
    DECLARE @SeqNo INT;
    DECLARE @DaysInCurrentYear INT;

    --------------------------------------------------------------------
    -- เพิ่มสำหรับเช็ควันที่จ่ายเคลมจาก Movement บรรทัดแรก
    --------------------------------------------------------------------
    DECLARE @ClaimPrincipalTotal DECIMAL(20,2);
    DECLARE @ClaimAccruedInterestTotal DECIMAL(20,2);
    DECLARE @ClaimPayDate DATETIME;
    DECLARE @ClaimDocDate DATETIME;
    DECLARE @ClaimEffectiveDate DATE;
    DECLARE @ClaimSeqNo INT;

    --------------------------------------------------------------------
    -- จำนวนวันในปีของวันที่ที่ใช้คำนวณ
    --------------------------------------------------------------------
    SET @DaysInCurrentYear = DATEDIFF(
        DAY,
        DATEFROMPARTS(YEAR(@CalcToDate), 1, 1),
        DATEFROMPARTS(YEAR(@CalcToDate) + 1, 1, 1)
    );

    --------------------------------------------------------------------
    -- ดึง DebtorCardId และ InterestRate จาก DataDebtorCard
    --------------------------------------------------------------------
    SELECT TOP (1)
        @DebtorCardId = dc.DataDebtorCardId,
        @InterestRate = dc.InterestRate
    FROM dbo.DataDebtorCard dc
    WHERE dc.DebtorRelateId = @DebtorRelateId;

    IF @DebtorCardId IS NULL
    BEGIN
        THROW 50005, 'ไม่พบ DebtorCardId จาก DebtorRelateId ที่ระบุ', 1;
    END;

    IF @InterestRate IS NULL
    BEGIN
        THROW 50006, 'ไม่พบอัตราดอกเบี้ยจาก DataDebtorCard.InterestRate', 1;
    END;

	--------------------------------------------------------------------
    -- เช็ค Movement บรรทัดแรก
    -- ถ้าเลือกวันที่ <= วันที่จ่ายเคลม ให้ดึงยอดจ่ายเคลมมาเลย
    --------------------------------------------------------------------
    SELECT TOP (1)
        @ClaimPrincipalTotal = ISNULL(cm.PrincipalTotal, 0),
        @ClaimAccruedInterestTotal = ISNULL(cm.AccruedInterestTotal, 0),
        @ClaimPayDate = cm.PayDate,
        @ClaimDocDate = cm.DocDate,
        @ClaimEffectiveDate = CONVERT(
            DATE,
            CASE
                WHEN ISNULL(CONVERT(DATE, cm.PayDate), '1900-01-01') = '1900-01-01'
                    THEN cm.DocDate
                ELSE cm.PayDate
            END
        ),
        @ClaimSeqNo = cm.SeqNo
    FROM dbo.DataDebtorCardMovement cm
    WHERE cm.DebtorCardId = @DebtorCardId
    ORDER BY cm.SeqNo ASC, cm.DocDate ASC;

    IF @ClaimEffectiveDate IS NOT NULL
       AND @CalcToDate <= @ClaimEffectiveDate
    BEGIN
        SELECT
            InterestRate = @InterestRate,
            PrincipalTotal = @ClaimPrincipalTotal,

            Final_DebtBalance =
                CAST(
                    ROUND(
                        ISNULL(@ClaimPrincipalTotal, 0)
                    , 2)
                AS DECIMAL(20,2)),

            PayDate = @ClaimPayDate,
            DocDate = @ClaimDocDate,
            EffectiveDate = @ClaimEffectiveDate,
            DayInterate = 0,
            DaysInCurrentYear = @DaysInCurrentYear,
            SeqNo = @ClaimSeqNo,

            Final_AccruedInterestTotal =
                CAST(
                    ROUND(
                        ISNULL(@ClaimAccruedInterestTotal, 0)
                    , 2)
                AS DECIMAL(20,2));

        RETURN;
    END;

    --------------------------------------------------------------------
    -- ดึง PrincipalTotal ล่าสุด ณ วันที่ @Date
    --------------------------------------------------------------------
    SELECT TOP (1)
        @PrincipalTotal = cm.PrincipalTotal
    FROM dbo.DataDebtorCardMovement cm
    WHERE cm.DebtorCardId = @DebtorCardId
      AND CONVERT(DATE, cm.DocDate) <= @CalcToDate
    ORDER BY cm.DocDate DESC, cm.SeqNo DESC;

    IF @PrincipalTotal IS NULL
    BEGIN
        THROW 50007, 'ไม่พบ PrincipalTotal กรุณาตรวจสอบข้อมูล DataDebtorCardMovement', 1;
    END;

    --------------------------------------------------------------------
    -- ดึงดอกเบี้ยสะสมล่าสุด และ InterestEndDate ล่าสุด
    --------------------------------------------------------------------
    SELECT TOP (1)
        @LastAccruedInterestTotal = ISNULL(cm.AccruedInterestTotal, 0),
        @InterestEndDate = CONVERT(DATE, cm.InterestEndDate),
        @PayDate = cm.PayDate,
        @DocDate = cm.DocDate,
        @EffectiveDate = CONVERT(
            DATE,
            CASE
                WHEN ISNULL(CONVERT(DATE, cm.PayDate), '1900-01-01') = '1900-01-01'
                    THEN cm.DocDate
                ELSE cm.PayDate
            END
        ),
        @SeqNo = cm.SeqNo
    FROM dbo.DataDebtorCardMovement cm
    WHERE cm.DebtorCardId = @DebtorCardId
      AND cm.InterestEndDate IS NOT NULL
      AND CONVERT(DATE, cm.InterestEndDate) <= @CalcToDate
    ORDER BY cm.InterestEndDate DESC, cm.SeqNo DESC;

    IF @InterestEndDate IS NULL
    BEGIN
        THROW 50008, 'ไม่พบรายการ Movement ที่มี InterestEndDate น้อยกว่าหรือเท่ากับวันที่คำนวณ', 1;
    END;

    --------------------------------------------------------------------
    -- คิดดอกจากวันถัดจาก InterestEndDate ถึง @Date
    --------------------------------------------------------------------
    SET @InterestStartDate = DATEADD(DAY, 1, @InterestEndDate);

    SET @InterestDay =
        CASE
            WHEN @CalcToDate >= @InterestStartDate
                THEN DATEDIFF(DAY, @InterestStartDate, @CalcToDate) + 1
            ELSE 0
        END;

    --------------------------------------------------------------------
    -- คำนวณดอกเบี้ยเพิ่ม
    -- สูตร: PrincipalTotal * InterestRate * จำนวนวัน / 36500
    --------------------------------------------------------------------
    SET @InterestAmount =
        CAST(
            ROUND(
                CASE
                    WHEN @InterestDay > 0
                    THEN
                        CAST(@PrincipalTotal AS DECIMAL(38,10))
                        * CAST(@InterestRate AS DECIMAL(38,10))
                        * CAST(@InterestDay AS DECIMAL(38,10))
                        / CAST(36500.00 AS DECIMAL(38,10))
                    ELSE 0
                END
            , 2)
        AS DECIMAL(20,2));

    --------------------------------------------------------------------
    -- รวมดอกเบี้ยสะสมเดิม + ดอกเบี้ยที่คำนวณเพิ่ม
    --------------------------------------------------------------------
    SET @AccruedInterestTotal =
        ISNULL(@LastAccruedInterestTotal, 0)
        + ISNULL(@InterestAmount, 0);

    --------------------------------------------------------------------
    -- Return field ให้เท่าเดิม
    --------------------------------------------------------------------
    SELECT
        InterestRate = @InterestRate,
        PrincipalTotal = @PrincipalTotal,

        Final_DebtBalance =
            CAST(
                ROUND(
                    ISNULL(@PrincipalTotal, 0)
                    --+ ISNULL(@AccruedInterestTotal, 0)
                , 2)
            AS DECIMAL(20,2)),

        PayDate = @PayDate,
        DocDate = @DocDate,
        EffectiveDate = @EffectiveDate,
        DayInterate = @InterestDay,
        DaysInCurrentYear = @DaysInCurrentYear,
        SeqNo = @SeqNo,

        Final_AccruedInterestTotal =
            CAST(
                ROUND(
                    ISNULL(@AccruedInterestTotal, 0)
                , 2)
            AS DECIMAL(20,2));
END;

CREATE PROCEDURE [dbo].SP_DEB_010_GetPrincipalTotalPercentHaircut
    @DebtBalance DECIMAL(20,4) = 0,
    @Date DATE = '2025-02-23',
    @DebtorRelateId NVARCHAR(MAX) = NULL
AS
BEGIN

    SET NOCOUNT ON;
    IF @DebtorRelateId IS NULL OR LTRIM(RTRIM(@DebtorRelateId)) = ''
        THROW 50100, 'DebtorRelateId is required', 1;

    IF ISJSON(@DebtorRelateId) <> 1
    BEGIN
        IF TRY_CONVERT(UNIQUEIDENTIFIER, @DebtorRelateId) IS NULL OR LEN(@DebtorRelateId) <> 36
            THROW 50101, 'Expected a GUID or a JSON array of GUIDs', 1;
        EXEC dbo.SP_DEB_010_GetPrincipalTotalPercentHaircut_Single
            @DebtBalance = @DebtBalance, @Date = @Date, @DebtorRelateId = @DebtorRelateId;
        RETURN;
    END;
    IF LEFT(LTRIM(@DebtorRelateId), 1) <> '['
        THROW 50102, 'DebtorRelateId JSON must be an array', 1;
    IF EXISTS (SELECT 1 FROM OPENJSON(@DebtorRelateId)
               WHERE [type] <> 1 OR LEN([value]) <> 36 OR TRY_CONVERT(UNIQUEIDENTIFIER, [value]) IS NULL)
        THROW 50103, 'Every DebtorRelateId must be a GUID string', 1;

    DECLARE @Ids TABLE (Ordinal INT NOT NULL, DebtorRelateId NVARCHAR(150) NOT NULL, LGNo NVARCHAR(100) NULL);
    INSERT INTO @Ids (Ordinal, DebtorRelateId)
        SELECT CONVERT(INT, [key]), CONVERT(NVARCHAR(36), CONVERT(UNIQUEIDENTIFIER, [value]))
        FROM OPENJSON(@DebtorRelateId);
    IF NOT EXISTS (SELECT 1 FROM @Ids)
        THROW 50104, 'At least one DebtorRelateId is required', 1;
    IF EXISTS (SELECT DebtorRelateId FROM @Ids GROUP BY DebtorRelateId HAVING COUNT(*) > 1)
        THROW 50105, 'Duplicate DebtorRelateId is not allowed', 1;
    IF EXISTS (SELECT 1 FROM @Ids i WHERE
        (SELECT COUNT(*) FROM dbo.DataDebtorRelate dr WHERE dr.DebtorRelateId = i.DebtorRelateId) <> 1)
        THROW 50106, 'A DebtorRelateId is missing or ambiguous', 1;
    UPDATE i SET LGNo = dr.LGNo
        FROM @Ids i JOIN dbo.DataDebtorRelate dr ON dr.DebtorRelateId = i.DebtorRelateId;
    IF EXISTS (SELECT 1 FROM @Ids WHERE LGNo IS NULL)
        THROW 50107, 'LGNo is missing', 1;
    IF EXISTS (SELECT LGNo FROM @Ids GROUP BY LGNo HAVING COUNT(*) > 1)
        THROW 50108, 'Multiple DebtorRelateIds for the same LG are not allowed', 1;

    CREATE TABLE #Single (
        InterestRate DECIMAL(20,2), PrincipalTotal DECIMAL(20,2), Final_DebtBalance DECIMAL(20,2),
        ClaimPayAmount DECIMAL(20,4), DebtBalancePercent DECIMAL(20,2),
        PayDate DATETIME, DocDate DATETIME, EffectiveDate DATE, DayInterate INT,
        DaysInCurrentYear INT, SeqNo INT, Final_AccruedInterestTotal DECIMAL(20,2));
    CREATE TABLE #Balances (Ordinal INT, DebtorRelateId NVARCHAR(150), LGNo NVARCHAR(100),
        PrincipalTotal DECIMAL(20,2), Final_DebtBalance DECIMAL(20,2),
        ClaimPayAmount DECIMAL(20,4), Final_AccruedInterestTotal DECIMAL(20,2));
    DECLARE @Ordinal INT, @Id NVARCHAR(150), @LGNo NVARCHAR(100);
    DECLARE debtor_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT Ordinal, DebtorRelateId, LGNo FROM @Ids ORDER BY Ordinal;
    OPEN debtor_cursor;
    FETCH NEXT FROM debtor_cursor INTO @Ordinal, @Id, @LGNo;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        DELETE FROM #Single;
        INSERT INTO #Single EXEC dbo.SP_DEB_010_GetPrincipalTotalPercentHaircut_Single
            @DebtBalance = @DebtBalance, @Date = @Date, @DebtorRelateId = @Id;
        IF (SELECT COUNT(*) FROM #Single) <> 1
            THROW 50109, 'Single-LG calculation must return exactly one row', 1;
        IF EXISTS (SELECT 1 FROM #Single WHERE PrincipalTotal IS NULL OR PrincipalTotal < 0
            OR Final_DebtBalance IS NULL OR Final_DebtBalance < 0
            OR ClaimPayAmount IS NULL OR ClaimPayAmount <= 0)
            THROW 50110, 'Invalid LG principal balance or claim amount', 1;
        INSERT INTO #Balances SELECT @Ordinal, @Id, @LGNo, PrincipalTotal, Final_DebtBalance,
            ClaimPayAmount, Final_AccruedInterestTotal FROM #Single;
        FETCH NEXT FROM debtor_cursor INTO @Ordinal, @Id, @LGNo;
    END;
    CLOSE debtor_cursor;
    DEALLOCATE debtor_cursor;

    DECLARE @TotalPrincipal DECIMAL(28,2), @TotalBalance DECIMAL(28,2), @TotalClaim DECIMAL(28,4);
    SELECT @TotalPrincipal = SUM(PrincipalTotal), @TotalBalance = SUM(Final_DebtBalance),
        @TotalClaim = SUM(ClaimPayAmount) FROM #Balances;
    -- Sum first; never average or sum individual LG percentages.
    SELECT PrincipalTotal = @TotalPrincipal, Final_DebtBalance = @TotalBalance,
        ClaimPayAmount = @TotalClaim,
        DebtBalancePercent = CAST(ROUND((@TotalPrincipal / NULLIF(@TotalClaim, 0)) * 100, 2) AS DECIMAL(20,2));
    -- Same as-of balances used in the aggregate, in request order, for API allocation.
    SELECT DebtorRelateId, LGNo, PrincipalTotal, Final_DebtBalance, ClaimPayAmount
        FROM #Balances ORDER BY Ordinal;

END

-- DebtBalancePercent = Final_DebtBalance / DataLG.ClaimPayAmount * 100.
-- Returns a numeric percentage rounded to 2 decimal places (e.g. 25.00 means 25%).
-- Returns NULL when ClaimPayAmount is NULL, missing, or zero.
-- Preserves the original principal-only Final_DebtBalance calculation.
-- Example: EXEC dbo.SP_DEB_006_CalInteratePercent @Date = '2025-02-23',
--     @DebtorRelateId = '9D8EE997-0540-4FF7-B282-07C77B3FBAD6';
create  PROCEDURE [dbo].[SP_DEB_010_GetPrincipalTotalPercentHaircut_Single]
    @DebtBalance    DECIMAL(20,4) = 0,
    @Date           DATE          = '2025-02-23',
    @DebtorRelateId NVARCHAR(150) = '9D8EE997-0540-4FF7-B282-07C77B3FBAD6'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @LGNo NVARCHAR(20);

    DECLARE @ClaimPayAmount DECIMAL(20,4);

    -- Resolve the claim amount for the LG belonging to this debtor.
    -- A scalar subquery rejects ambiguous LG matches instead of picking an arbitrary row.
    SET @ClaimPayAmount =
    (
        SELECT lg.ClaimPayAmount
        FROM dbo.DataLG AS lg
        INNER JOIN dbo.DataDebtorRelate AS dr ON dr.LGNo = lg.LGNo
        WHERE dr.DebtorRelateId = @DebtorRelateId
    );

    --SELECT @LGNo = LGNo
    --FROM dbo.DataDebtorRelate
    --WHERE DebtorRelateId = @DebtorRelateId;

    --SET @DebtorRelateId =
    --(
    --    SELECT TOP 1 DebtorRelateId
    --    FROM dbo.DataDebtorRelate
    --    WHERE LGNo = @LGNo
    --      AND DebtorTypeId = 1
    --);

    IF @Date IS NULL
        SET @Date = CONVERT(DATE, GETDATE());

    DECLARE @CalcToDate DATE = CONVERT(DATE, @Date);

    DECLARE @DebtorCardId NVARCHAR(150);
    DECLARE @InterestRate DECIMAL(20,2);
    DECLARE @PrincipalTotal DECIMAL(20,2);
    DECLARE @LastAccruedInterestTotal DECIMAL(20,2);
    DECLARE @InterestEndDate DATE;
    DECLARE @InterestStartDate DATE;
    DECLARE @InterestDay INT;
    DECLARE @InterestAmount DECIMAL(20,2);
    DECLARE @AccruedInterestTotal DECIMAL(20,2);

    DECLARE @PayDate DATETIME;
    DECLARE @DocDate DATETIME;
    DECLARE @EffectiveDate DATE;
    DECLARE @SeqNo INT;
    DECLARE @DaysInCurrentYear INT;

    --------------------------------------------------------------------
    -- เพิ่มสำหรับเช็ควันที่จ่ายเคลมจาก Movement บรรทัดแรก
    --------------------------------------------------------------------
    DECLARE @ClaimPrincipalTotal DECIMAL(20,2);
    DECLARE @ClaimAccruedInterestTotal DECIMAL(20,2);
    DECLARE @ClaimPayDate DATETIME;
    DECLARE @ClaimDocDate DATETIME;
    DECLARE @ClaimEffectiveDate DATE;
    DECLARE @ClaimSeqNo INT;

    --------------------------------------------------------------------
    -- จำนวนวันในปีของวันที่ที่ใช้คำนวณ
    --------------------------------------------------------------------
    SET @DaysInCurrentYear = DATEDIFF(
        DAY,
        DATEFROMPARTS(YEAR(@CalcToDate), 1, 1),
        DATEFROMPARTS(YEAR(@CalcToDate) + 1, 1, 1)
    );

    --------------------------------------------------------------------
    -- ดึง DebtorCardId และ InterestRate จาก DataDebtorCard
    --------------------------------------------------------------------
    SELECT TOP (1)
        @DebtorCardId = dc.DataDebtorCardId,
        @InterestRate = dc.InterestRate
    FROM dbo.DataDebtorCard dc
    WHERE dc.DebtorRelateId = @DebtorRelateId;

    IF @DebtorCardId IS NULL
    BEGIN
        THROW 50005, 'ไม่พบ DebtorCardId จาก DebtorRelateId ที่ระบุ', 1;
    END;

    IF @InterestRate IS NULL
    BEGIN
        THROW 50006, 'ไม่พบอัตราดอกเบี้ยจาก DataDebtorCard.InterestRate', 1;
    END;

	--------------------------------------------------------------------
    -- เช็ค Movement บรรทัดแรก
    -- ถ้าเลือกวันที่ <= วันที่จ่ายเคลม ให้ดึงยอดจ่ายเคลมมาเลย
    --------------------------------------------------------------------
    SELECT TOP (1)
        @ClaimPrincipalTotal = ISNULL(cm.PrincipalTotal, 0),
        @ClaimAccruedInterestTotal = ISNULL(cm.AccruedInterestTotal, 0),
        @ClaimPayDate = cm.PayDate,
        @ClaimDocDate = cm.DocDate,
        @ClaimEffectiveDate = CONVERT(
            DATE,
            CASE
                WHEN ISNULL(CONVERT(DATE, cm.PayDate), '1900-01-01') = '1900-01-01'
                    THEN cm.DocDate
                ELSE cm.PayDate
            END
        ),
        @ClaimSeqNo = cm.SeqNo
    FROM dbo.DataDebtorCardMovement cm
    WHERE cm.DebtorCardId = @DebtorCardId
    ORDER BY cm.SeqNo ASC, cm.DocDate ASC;

    IF @ClaimEffectiveDate IS NOT NULL
       AND @CalcToDate <= @ClaimEffectiveDate
    BEGIN
        SELECT
            InterestRate = @InterestRate,
            PrincipalTotal = @ClaimPrincipalTotal,

            Final_DebtBalance =
                CAST(
                    ROUND(
                        ISNULL(@ClaimPrincipalTotal, 0)
                    , 2)
                AS DECIMAL(20,2)),

            ClaimPayAmount = @ClaimPayAmount,
            DebtBalancePercent = CAST(ROUND(
                (CAST(ROUND(ISNULL(@ClaimPrincipalTotal, 0), 2) AS DECIMAL(20,2))
                    / NULLIF(@ClaimPayAmount, 0)) * 100.0,
                2) AS DECIMAL(20,2)),
            PayDate = @ClaimPayDate,
            DocDate = @ClaimDocDate,
            EffectiveDate = @ClaimEffectiveDate,
            DayInterate = 0,
            DaysInCurrentYear = @DaysInCurrentYear,
            SeqNo = @ClaimSeqNo,

            Final_AccruedInterestTotal =
                CAST(
                    ROUND(
                        ISNULL(@ClaimAccruedInterestTotal, 0)
                    , 2)
                AS DECIMAL(20,2));

        RETURN;
    END;

    --------------------------------------------------------------------
    -- ดึง PrincipalTotal ล่าสุด ณ วันที่ @Date
    --------------------------------------------------------------------
    SELECT TOP (1)
        @PrincipalTotal = cm.PrincipalTotal
    FROM dbo.DataDebtorCardMovement cm
    WHERE cm.DebtorCardId = @DebtorCardId
      AND CONVERT(DATE, cm.DocDate) <= @CalcToDate
    ORDER BY cm.DocDate DESC, cm.SeqNo DESC;

    IF @PrincipalTotal IS NULL
    BEGIN
        THROW 50007, 'ไม่พบ PrincipalTotal กรุณาตรวจสอบข้อมูล DataDebtorCardMovement', 1;
    END;

    --------------------------------------------------------------------
    -- ดึงดอกเบี้ยสะสมล่าสุด และ InterestEndDate ล่าสุด
    --------------------------------------------------------------------
    SELECT TOP (1)
        @LastAccruedInterestTotal = ISNULL(cm.AccruedInterestTotal, 0),
        @InterestEndDate = CONVERT(DATE, cm.InterestEndDate),
        @PayDate = cm.PayDate,
        @DocDate = cm.DocDate,
        @EffectiveDate = CONVERT(
            DATE,
            CASE
                WHEN ISNULL(CONVERT(DATE, cm.PayDate), '1900-01-01') = '1900-01-01'
                    THEN cm.DocDate
                ELSE cm.PayDate
            END
        ),
        @SeqNo = cm.SeqNo
    FROM dbo.DataDebtorCardMovement cm
    WHERE cm.DebtorCardId = @DebtorCardId
      AND cm.InterestEndDate IS NOT NULL
      AND CONVERT(DATE, cm.InterestEndDate) <= @CalcToDate
    ORDER BY cm.InterestEndDate DESC, cm.SeqNo DESC;

    IF @InterestEndDate IS NULL
    BEGIN
        THROW 50008, 'ไม่พบรายการ Movement ที่มี InterestEndDate น้อยกว่าหรือเท่ากับวันที่คำนวณ', 1;
    END;

    --------------------------------------------------------------------
    -- คิดดอกจากวันถัดจาก InterestEndDate ถึง @Date
    --------------------------------------------------------------------
    SET @InterestStartDate = DATEADD(DAY, 1, @InterestEndDate);

    SET @InterestDay =
        CASE
            WHEN @CalcToDate >= @InterestStartDate
                THEN DATEDIFF(DAY, @InterestStartDate, @CalcToDate) + 1
            ELSE 0
        END;

    --------------------------------------------------------------------
    -- คำนวณดอกเบี้ยเพิ่ม
    -- สูตร: PrincipalTotal * InterestRate * จำนวนวัน / 36500
    --------------------------------------------------------------------
    SET @InterestAmount =
        CAST(
            ROUND(
                CASE
                    WHEN @InterestDay > 0
                    THEN
                        CAST(@PrincipalTotal AS DECIMAL(38,10))
                        * CAST(@InterestRate AS DECIMAL(38,10))
                        * CAST(@InterestDay AS DECIMAL(38,10))
                        / CAST(36500.00 AS DECIMAL(38,10))
                    ELSE 0
                END
            , 2)
        AS DECIMAL(20,2));

    --------------------------------------------------------------------
    -- รวมดอกเบี้ยสะสมเดิม + ดอกเบี้ยที่คำนวณเพิ่ม
    --------------------------------------------------------------------
    SET @AccruedInterestTotal =
        ISNULL(@LastAccruedInterestTotal, 0)
        + ISNULL(@InterestAmount, 0);

    --------------------------------------------------------------------
    -- Return field ให้เท่าเดิม
    --------------------------------------------------------------------
    SELECT
        InterestRate = @InterestRate,
        PrincipalTotal = @PrincipalTotal,

        Final_DebtBalance =
            CAST(
                ROUND(
                    ISNULL(@PrincipalTotal, 0)
                    --+ ISNULL(@AccruedInterestTotal, 0)
                , 2)
            AS DECIMAL(20,2)),

        ClaimPayAmount = @ClaimPayAmount,
        DebtBalancePercent = CAST(ROUND(
            (CAST(ROUND(ISNULL(@PrincipalTotal, 0), 2) AS DECIMAL(20,2))
                / NULLIF(@ClaimPayAmount, 0)) * 100.0,
            2) AS DECIMAL(20,2)),
        PayDate = @PayDate,
        DocDate = @DocDate,
        EffectiveDate = @EffectiveDate,
        DayInterate = @InterestDay,
        DaysInCurrentYear = @DaysInCurrentYear,
        SeqNo = @SeqNo,

        Final_AccruedInterestTotal =
            CAST(
                ROUND(
                    ISNULL(@AccruedInterestTotal, 0)
                , 2)
            AS DECIMAL(20,2));
END;

CREATE PROCEDURE dbo.sp_dropdiagram
(
	@diagramname 	sysname,
	@owner_id	int	= null
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int

	if(@diagramname is null)
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT; 
	
	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	delete from dbo.sysdiagrams where diagram_id = @DiagId;

	return 0;
END

CREATE PROCEDURE [dbo].[sp_GetTrackingStatusCollectorPageNonOA_Backup]
    @CurrentPage    INT            = 1,
    @PageSize       INT            = 50,
    @SearchTypesCsv NVARCHAR(500)  = NULL,
    @Keyword        NVARCHAR(200)  = NULL,
    @StartDate      DATETIME       = NULL,
    @EndDate        DATETIME       = NULL,
    @IsManager      INT            = NULL,   -- NULL=admin, 0=staff, 1=section-mgr, 2=org-mgr
    @UserId         INT            = NULL,
    @OrgSectionId   INT            = NULL,
    @OrgStructureId INT            = NULL,
    @UserIdListCsv  NVARCHAR(MAX)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SafeCurrentPage INT = CASE WHEN ISNULL(@CurrentPage, 0) <= 0 THEN 1 ELSE @CurrentPage END;
    DECLARE @SafePageSize    INT = CASE WHEN ISNULL(@PageSize, 0) <= 0 THEN 50 ELSE @PageSize END;

    /* ─── user-ID whitelist ──────────────────────────────────────────── */
    CREATE TABLE #UidList 
    (
        UserId INT NOT NULL PRIMARY KEY
    );

    IF ISNULL(LEN(@UserIdListCsv), 0) > 0
    BEGIN
        INSERT INTO #UidList (UserId)
        SELECT DISTINCT TRY_CAST(TRIM([value]) AS INT)
        FROM STRING_SPLIT(@UserIdListCsv, ',')
        WHERE ISNULL(TRIM([value]), '') <> ''
          AND TRY_CAST(TRIM([value]) AS INT) IS NOT NULL;
    END;

    /* ─── search-type bit flags ──────────────────────────────────────── */
    DECLARE 
        @srchRelateId BIT = 0,
        @srchCIF      BIT = 0,
        @srchLG       BIT = 0,
        @srchCardCode BIT = 0,
        @srchCode     BIT = 0,
        @srchName     BIT = 0,
        @srchClaim    BIT = 0,
        @srchCollect  BIT = 0,
        @srchProv     BIT = 0,
        @srchGroup    BIT = 0,
        @srchStatus   BIT = 0,
        @srchPort     BIT = 0;

    IF ISNULL(@SearchTypesCsv, '') <> '' 
       AND ISNULL(@Keyword, '') <> ''
    BEGIN
        IF CHARINDEX('dataDebtorRelateId',     @SearchTypesCsv) > 0 SET @srchRelateId = 1;
        IF CHARINDEX('cifNo',                  @SearchTypesCsv) > 0 SET @srchCIF      = 1;
        IF CHARINDEX('lgNo',                   @SearchTypesCsv) > 0 SET @srchLG       = 1;
        IF CHARINDEX('debtorCardCode',         @SearchTypesCsv) > 0 SET @srchCardCode = 1;
        IF CHARINDEX('debtorCode',             @SearchTypesCsv) > 0 SET @srchCode     = 1;
        IF CHARINDEX('debtorName',             @SearchTypesCsv) > 0 SET @srchName     = 1;
        IF CHARINDEX('ClaimPay',               @SearchTypesCsv) > 0 SET @srchClaim    = 1;
        IF CHARINDEX('collectorName',          @SearchTypesCsv) > 0 SET @srchCollect  = 1;
        IF CHARINDEX('provinceName',           @SearchTypesCsv) > 0 SET @srchProv     = 1;
        IF CHARINDEX('personGroupValueLookup', @SearchTypesCsv) > 0 SET @srchGroup    = 1;
        IF CHARINDEX('systemStatusName',       @SearchTypesCsv) > 0 SET @srchStatus   = 1;
        IF CHARINDEX('port',                   @SearchTypesCsv) > 0 SET @srchPort     = 1;
    END;

    /* ─── materialize base data ──────────────────────────────────────── */
    SELECT
        a.AssignmentId,
        a.CollectorUserId AS CollectorId,

        lg.LGNo,

        dr.DebtorRelateId,
        dr.CIFNo,

        d.DebtorId,
        d.DebtorCode,
        d.PersonGroupId,
        d.DebtorName AS DebtorNameGroup,

        ISNULL(td.TitleShortName, '') AS DebtorTitle,
        ISNULL(d.FirstName, '')       AS DebtorFirstName,
        ISNULL(d.LastName, '')        AS DebtorLastName,

        lm.LookupId AS PersonGroupLookupId,
        ISNULL(dty.DebtorTypeName, '') AS PersonGroupValueLookup,

        ISNULL(dc.DebtorCardCode, '') AS DebtorCardCode,
        ISNULL(dc.ClaimPay, 0)        AS ClaimPay,
        dc.ClaimPayDate,

        ISNULL(prov.ProvinceId, 0) AS ProvinceId,
        ISNULL(prov.Name, '')      AS ProvinceName,

        p.OrgStructureId AS CollectorOrgStructureId,
        area.OrgSectionId AS AreaOrgSectionId,

        RTRIM(LTRIM(
            ISNULL(tc.TitleShortName, '') + ' ' +
            ISNULL(p.FirstName, '') + ' ' +
            ISNULL(p.LastName, '')
        )) AS CollectorName,

        sdu.StatusPortId AS PortId,
        sm_port.StatusCode AS PortCode,
        ISNULL(sm_port.StatusName, '') AS PortName,

        ISNULL(sm_assign.SystemId, 0)    AS AssignStatusSystemId,
        ISNULL(sm_assign.StatusCode, '') AS AssignStatusCode,
        ISNULL(sm_assign.StatusName, '') AS AssignStatusName,

        ROW_NUMBER() OVER (
            PARTITION BY lg.LGNo
            ORDER BY 
                dc.ClaimPayDate DESC,
                dr.DebtorRelateId ASC
        ) AS RowNum

    INTO #BaseData
    FROM dbo.DataAssignment a

    INNER JOIN dbo.DataDebtorRelate dr
        ON a.DebtorRelateId = dr.DebtorRelateId
       AND dr.DebtorTypeId = 1

    INNER JOIN dbo.DataLG lg
        ON dr.LGNo = lg.LGNo
       AND lg.Grade = 'F1'

    INNER JOIN dbo.DataDebtor d
        ON dr.DebtorId = d.DebtorId

    INNER JOIN dbo.DataDebtorAddress addr
        ON d.DebtorId = addr.DebtorId
       AND addr.DebtorAddressTypeId = 7

    INNER JOIN dbo.SystemResponsibleAreaMaster area
        ON addr.ProvinceId = area.ProvinceId

    INNER JOIN dbo.DataDebtorStatusUpdate sdu
        ON dr.DebtorRelateId = sdu.DebtorRelateId
       AND sdu.DebtorTypeId = 1
       AND ISNULL(sdu.StatusSubTrackingId, 0) <> 0

    INNER JOIN dbo.SystemStatusMaster sm_port
        ON sdu.StatusPortId = sm_port.SystemStatusId

    INNER JOIN dbo.DataPersonalInfo p
        ON a.CollectorUserId = p.UserId

    INNER JOIN dbo.SystemTitleMaster tc
        ON p.TitleId = tc.TitleId

    LEFT JOIN dbo.SystemTitleMaster td
        ON d.TitleId = td.TitleId

    LEFT JOIN dbo.SystemLookupMaster lm
        ON d.StatusPersonId = lm.LookupId

    LEFT JOIN dbo.SystemDebtorType dty
        ON dr.DebtorTypeId = dty.DebtorTypeId

    OUTER APPLY (
        SELECT TOP 1
            c.DebtorCardCode,
            c.ClaimPay,
            c.ClaimPayDate
        FROM dbo.DataDebtorCard c
        WHERE c.DebtorRelateId = dr.DebtorRelateId
        ORDER BY 
            c.ClaimPayDate DESC,
            c.DataDebtorCardId DESC
    ) dc

    LEFT JOIN dbo.SystemProvinceMaster prov
        ON addr.ProvinceId = prov.ProvinceId

    LEFT JOIN dbo.SystemStatusMaster sm_assign
        ON sdu.StatusAssignId = sm_assign.SystemStatusId

    WHERE a.TypeAssignId = 1
      AND (
            @IsManager IS NULL

            OR (
                @IsManager = 2
                AND a.CollectorUserId IN (
                    SELECT UserId FROM #UidList
                )
            )

            OR (
                @IsManager = 1
                AND (
                        a.CollectorUserId = @UserId
                     OR a.CollectorUserId IN (
                            SELECT UserId FROM #UidList
                        )
                    )
                AND (
                        (
                            @OrgSectionId IS NOT NULL
                            AND @OrgSectionId > 0
                            AND area.OrgSectionId = @OrgSectionId
                        )
                     OR (
                            (@OrgSectionId IS NULL OR @OrgSectionId = 0)
                            AND p.OrgStructureId = @OrgStructureId
                        )
                    )
            )

            OR (
                @IsManager = 0
                AND a.CollectorUserId = @UserId
            )
          );

    CREATE NONCLUSTERED INDEX IX_BD_RowNum
        ON #BaseData (RowNum);

    CREATE NONCLUSTERED INDEX IX_BD_LGNo
        ON #BaseData (LGNo)
        INCLUDE (
            PortId,
            PortCode,
            PortName,
            AssignmentId,
            CollectorId,
            CollectorName,
            ClaimPayDate
        );

    /* ─── Filter กลาง: ยังไม่แบ่งหน้า ─────────────────────────────── */
    ;WITH SearchFirst AS (
    SELECT *
    FROM #BaseData
    WHERE (
            ISNULL(@Keyword, '') = ''

         OR (
                @srchRelateId = 1 
            AND CONVERT(NVARCHAR(50), DebtorRelateId) LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchCIF = 1 
            AND CIFNo LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchLG = 1 
            AND LGNo LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchCardCode = 1 
            AND DebtorCardCode LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchCode = 1 
            AND DebtorCode LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchName = 1 
            AND (
                    CASE 
                        WHEN PersonGroupId = 118
                            THEN ISNULL(DebtorNameGroup, '')
                        ELSE 
                            ISNULL(DebtorTitle, '') + 
                            ISNULL(DebtorFirstName, '') + ' ' + 
                            ISNULL(DebtorLastName, '')
                    END
                ) LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchClaim = 1 
            AND CAST(ClaimPay AS NVARCHAR(50)) LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchCollect = 1 
            AND CollectorName LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchProv = 1 
            AND ProvinceName LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchGroup = 1 
            AND PersonGroupValueLookup LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchStatus = 1 
            AND AssignStatusName LIKE '%' + @Keyword + '%'
            )

         OR (
                @srchPort = 1 
            AND PortName LIKE '%' + @Keyword + '%'
            )
    )
    AND (
            @StartDate IS NULL 
         OR ClaimPayDate >= @StartDate
    )
    AND (
            @EndDate IS NULL 
         OR ClaimPayDate <= @EndDate
    )
),
FilteredDedup AS (
    SELECT *,
        ROW_NUMBER() OVER (
            PARTITION BY 
                CASE 
                    WHEN @srchCollect = 1 THEN CollectorId
                    ELSE 0
                END,
                LGNo
            ORDER BY 
                ClaimPayDate DESC,
                DebtorRelateId ASC
        ) AS FinalRowNum
    FROM SearchFirst
    WHERE 
        @srchCollect = 1
        OR RowNum = 1
)
SELECT
    AssignmentId,
    CollectorId,
    LGNo,

    DebtorRelateId,
    CIFNo,

    DebtorId,
    DebtorCode,
    PersonGroupId,
    DebtorNameGroup,
    DebtorTitle,
    DebtorFirstName,
    DebtorLastName,

    PersonGroupLookupId,
    PersonGroupValueLookup,

    DebtorCardCode,
    ClaimPay,
    ClaimPayDate,

    ProvinceId,
    ProvinceName,

    CollectorOrgStructureId,
    AreaOrgSectionId,
    CollectorName,

    PortId,
    PortCode,
    PortName,

    AssignStatusSystemId,
    AssignStatusCode,
    AssignStatusName,

    RowNum
INTO #Filtered
FROM FilteredDedup
WHERE FinalRowNum = 1;

    /* ══════════════════════════════════════════════════════════════════
       RS1: Page items
    ══════════════════════════════════════════════════════════════════ */
    SELECT
        DebtorRelateId,
        CIFNo,
        LGNo,

        DebtorCardCode,
        DebtorCode,
        DebtorId,

        DebtorTitle,
        DebtorFirstName,
        DebtorLastName,

        PersonGroupLookupId AS PersonGroupId,
        PersonGroupValueLookup,

        ClaimPay,
        ClaimPayDate,

        CollectorId,
        AreaOrgSectionId AS OrgSectionId,
        CollectorOrgStructureId AS OrgStructureId,
        CollectorName,

        ProvinceId,
        ProvinceName,

        AssignStatusSystemId AS SystemStatusId,
        AssignStatusCode AS SystemStatusCode,
        AssignStatusName AS SystemStatusName,

        COUNT(*) OVER () AS TotalFiltered
    FROM #Filtered
    ORDER BY 
        ClaimPayDate DESC,
        DebtorRelateId ASC
   OFFSET ((@SafeCurrentPage - 1) * @SafePageSize) ROWS
   FETCH NEXT @SafePageSize ROWS ONLY;

    /* ══════════════════════════════════════════════════════════════════
       RS2: AllWork
       นับจาก #Filtered เพื่อให้ตรงกับ keyword/date filter
    ══════════════════════════════════════════════════════════════════ */
    SELECT 
        COUNT(DISTINCT LGNo) AS AllWork
    FROM #BaseData;

    /* ══════════════════════════════════════════════════════════════════
       RS3: Port summary
       นับจาก #Filtered ฐานเดียวกับ RS1/RS2
    ══════════════════════════════════════════════════════════════════ */
    SELECT
        PortCode,
        PortId,
        COUNT(*) AS Cnt
    FROM #Filtered
    WHERE RowNum = 1
    GROUP BY
        PortCode,
        PortId;

    /* ══════════════════════════════════════════════════════════════════
       RS4: Collector summary
       ถ้าต้องการให้นับตรงกับ RS1/RS3 ให้ใช้ COUNT(DISTINCT LGNo)
    ══════════════════════════════════════════════════════════════════ */
    SELECT
        CollectorId,
        CollectorName AS UserCollectorName,
        ' ' AS UserOAName,
        COUNT(DISTINCT LGNo) AS AssignmentCount
   FROM #BaseData
    --WHERE RowNum = 1
    GROUP BY
        CollectorId,
        CollectorName;

    DROP TABLE IF EXISTS #Filtered;
    DROP TABLE IF EXISTS #BaseData;
    DROP TABLE IF EXISTS #UidList;
END;

	CREATE PROCEDURE dbo.sp_helpdiagramdefinition
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
