CREATE   PROCEDURE dbo.SP_TDR_Approval_ProcessRecal
(
    @CompromiseContractId VARCHAR(36),
    @CreateBy VARCHAR(50),
    @GetDate DATE
)
AS
BEGIN
    SET NOCOUNT ON;

    ------------------------------------------------------------
    -- ตัวแปรจาก ReceiptList[0]
    ------------------------------------------------------------
    DECLARE @ReceiptDebtorCardId VARCHAR(36);
    DECLARE @PayDate DATE;
    DECLARE @MainCardId NVARCHAR(150);


    ------------------------------------------------------------
    -- หา ReceiptList[0]
    -- ให้เหมือน Script เดิม
    ------------------------------------------------------------
    SELECT TOP 1
        @ReceiptDebtorCardId = m.DataDebtorCardId,
        @PayDate = f.PayDate,
        @MainCardId = m.DataMainCardId
    FROM dbo.ACCDataReceipt a
    INNER JOIN dbo.DataDebtorRelate b
        ON a.DebtorRelateId = b.DebtorRelateId
    INNER JOIN dbo.DataDebtor c
        ON a.DebtorId = c.DebtorId
    LEFT JOIN dbo.SystemDebtorType d
        ON c.DebtorTypeId = d.DebtorTypeId
    INNER JOIN dbo.TDRDataCompromiseContractReceipt e
        ON a.ReceiptId = e.ReceiptId
    INNER JOIN dbo.TDRDataCompromiseContractRecal f
        ON e.CompromiseContractReceiptId = f.CompromiseContractReceiptId
    INNER JOIN dbo.DataDebtorCard m
        ON a.DebtorCardId = m.DataDebtorCardId
    WHERE e.CompromiseContractId = @CompromiseContractId
    ORDER BY a.ReceiptDate DESC;


    ------------------------------------------------------------
    -- ถ้าไม่พบ Receipt
    ------------------------------------------------------------
    IF @ReceiptDebtorCardId IS NULL
    BEGIN
        PRINT N'ไม่พบข้อมูล Receipt/Recal สำหรับ CompromiseContractId นี้';
        RETURN;
    END;


    DECLARE
        @DataDebtorCardId VARCHAR(36),
        @CompromiseContractLGId VARCHAR(36),
        @DebtorRelateId VARCHAR(36);


    ------------------------------------------------------------
    -- ตัวแปร Manual Recal
    ------------------------------------------------------------
    DECLARE
        @SeqNo INT,
        @TypeId INT,
        @MeasureMasterId INT,
        @InterestEndDate DATETIME,
        @IsFinal BIT,
        @IsFirst BIT,
        @PaymentTypeId INT;


    ------------------------------------------------------------
    -- LG Cursor
    ------------------------------------------------------------
    DECLARE LG_CURSOR CURSOR LOCAL FAST_FORWARD FOR
    SELECT
        a.DataDebtorCardId,
        c.CompromiseContractLGId,
        b.DebtorRelateId
    FROM dbo.DataDebtorCard a
    INNER JOIN dbo.DataDebtorRelate b
        ON a.DebtorRelateId = b.DebtorRelateId
    INNER JOIN dbo.TDRDataCompromiseContractLG c
        ON b.DebtorRelateId = c.DebtorRelateId
    WHERE c.CompromiseContractId = @CompromiseContractId;


    OPEN LG_CURSOR;

    FETCH NEXT FROM LG_CURSOR
    INTO
        @DataDebtorCardId,
        @CompromiseContractLGId,
        @DebtorRelateId;


    WHILE @@FETCH_STATUS = 0
    BEGIN

        --------------------------------------------------------
        -- 1. Installment Plan Payment
        --------------------------------------------------------
        EXEC dbo.SP_TDR_03_InsertInstallmentPlanPayment
            @ID = @CompromiseContractId,
            @CompromiseContractLGId = @CompromiseContractLGId;


        --------------------------------------------------------
        -- 2. Insert Movement
        --------------------------------------------------------
        EXEC dbo.SP_DCS_Card_032_1_InsertDataDebtorCardMovementFromTDRRecal
            @DebtorCardId = @ReceiptDebtorCardId,
            @CompromiseContractId = @CompromiseContractId,
            @PayDate = @PayDate,
            @TypeId = 1;


        --------------------------------------------------------
        -- 3. Insert Recal
        --------------------------------------------------------
        EXEC dbo.SP_DCS_Card_032_3_InsertDataDebtorCardMovementFromTDRRecal
            @DebtorCardId = @ReceiptDebtorCardId,
            @CompromiseContractId = @CompromiseContractId;


        --------------------------------------------------------
        -- 4. Recalculate ทุก SeqNo
        --------------------------------------------------------
        EXEC dbo.SP_DCS_Adjust_007_InsertAdjustRecalTDRBatch
            @DebtorCardId = @ReceiptDebtorCardId;


        --------------------------------------------------------
        -- 5. Copy ลง DataDebtorCardMovement
        --------------------------------------------------------
        EXEC dbo.SP_DCS_Card_032_4_InsertDataDebtorCardMovementFromTDRRecalBatch
            @DebtorCardId = @ReceiptDebtorCardId,
            @CreateBy = @CreateBy;


        --------------------------------------------------------
        -- 6. Update Adjust
        --------------------------------------------------------
        EXEC dbo.SP_ACC_Adjust_002_13_UpdateAdjust
            @GetDate = @GetDate,
            @DebtorCardId = @ReceiptDebtorCardId,
            @CreateBy = @CreateBy;


        --------------------------------------------------------
        -- 6.1 Manual Recal
        -- ข้าม 2 แถวแรก
        --------------------------------------------------------
        DECLARE RECAL_CURSOR CURSOR LOCAL FAST_FORWARD FOR

        SELECT
            y.SeqNo,
            y.TypeId,
            y.MeasureId,
            y.InterestEndDate,

            CASE
                WHEN y.RecalRowNo = 1
                    THEN CAST(1 AS BIT)
                ELSE CAST(0 AS BIT)
            END AS IsFirst,

            CASE
                WHEN y.RecalRowNo = y.TotalRows
                    THEN CAST(1 AS BIT)
                ELSE CAST(0 AS BIT)
            END AS IsFinal,

            y.PaymentTypeId
        FROM
        (
            SELECT
                x.SeqNo,
                x.TypeId,
                x.MeasureId,
                x.InterestEndDate,
                x.PaymentTypeId,

                ROW_NUMBER() OVER
                (
                    ORDER BY x.SeqNo ASC
                ) AS RecalRowNo,

                COUNT(*) OVER () AS TotalRows
            FROM
            (
                SELECT
                    r.SeqNo,
                    r.TypeId,
                    r.MeasureId,
                    r.InterestEndDate,
                    r.PaymentTypeId,

                    ROW_NUMBER() OVER
                    (
                        ORDER BY r.SeqNo ASC
                    ) AS RowNo
                FROM dbo.TDRDataCompromiseContractRecalCard r
                WHERE r.DebtorCardId = @ReceiptDebtorCardId
            ) x
            WHERE x.RowNo >= 3
        ) y
        ORDER BY y.SeqNo ASC;


        OPEN RECAL_CURSOR;

        FETCH NEXT FROM RECAL_CURSOR
        INTO
            @SeqNo,
            @TypeId,
            @MeasureMasterId,
            @InterestEndDate,
            @IsFirst,
            @IsFinal,
            @PaymentTypeId;


        WHILE @@FETCH_STATUS = 0
        BEGIN

            EXEC dbo.SP_DCS_Adjust_005_InsertAdjustRecalManual
                @DebtorCardId = @ReceiptDebtorCardId,
                @SeqNo = @SeqNo,
                @TypeId = @TypeId,
                @CreateBy = @CreateBy,
                @MeasureMasterId = @MeasureMasterId,
                @InterestEndDate = @InterestEndDate,
                @IsFinal = @IsFinal,
                @IsFirst = @IsFirst,
                @IsAuto = 0,
                @PaymentTypeId = 5,
                @IsMonth = 0;


            FETCH NEXT FROM RECAL_CURSOR
            INTO
                @SeqNo,
                @TypeId,
                @MeasureMasterId,
                @InterestEndDate,
                @IsFirst,
                @IsFinal,
                @PaymentTypeId;

        END;


        CLOSE RECAL_CURSOR;
        DEALLOCATE RECAL_CURSOR;


        --------------------------------------------------------
        -- 7. Suspend Interest
        --------------------------------------------------------
        EXEC dbo.SP_DCS_Card_015_SuspendInterest
            @DataDebtorCardId = @DataDebtorCardId,
            @CompromiseContractId = @CompromiseContractId;


        --------------------------------------------------------
        -- 8. Merge Main Card Movement
        --------------------------------------------------------
        EXEC dbo.SP_DCS_046_MergeDebtorMainCardMovement
            @TypeId = 2,
            @MainCardId = @MainCardId;


        --------------------------------------------------------
        -- LG ถัดไป
        --------------------------------------------------------
        FETCH NEXT FROM LG_CURSOR
        INTO
            @DataDebtorCardId,
            @CompromiseContractLGId,
            @DebtorRelateId;

    END;


    CLOSE LG_CURSOR;
    DEALLOCATE LG_CURSOR;


    ------------------------------------------------------------
    -- Result
    ------------------------------------------------------------
    SELECT
        1 AS IsSuccess,
        @CompromiseContractId AS CompromiseContractId,
        @ReceiptDebtorCardId AS ReceiptDebtorCardId,
        @MainCardId AS MainCardId,
        @PayDate AS PayDate;

END;

/*
  SQL Server UDFs cannot execute DDL. This stored procedure is the reusable
  DROP-trigger helper and is called before every CREATE TRIGGER operation.
*/
CREATE   PROCEDURE [dbo].[usp_DropDB_TCGDCS_AuditTriggers]
    @SchemaName SYSNAME,
    @TableName SYSNAME,
    @DroppedTriggerCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @ObjectId INT,
        @DropSQL NVARCHAR(MAX),
        @TargetReference NVARCHAR(776),
        @OldTargetReference NVARCHAR(776),
        @OldHistoryTableName SYSNAME,
        @UpdateTriggerName SYSNAME,
        @DeleteTriggerName SYSNAME;

    SET @DroppedTriggerCount = 0;
    SET @ObjectId = OBJECT_ID(QUOTENAME(@SchemaName) + N'.' + QUOTENAME(@TableName), N'U');

    IF @ObjectId IS NULL
        RETURN;

    SET @TargetReference =
        QUOTENAME(N'DB_TCGDCS_HIS') + N'.' + QUOTENAME(@SchemaName)
        + N'.' + QUOTENAME(@TableName);

    SET @OldHistoryTableName =
        CASE
            WHEN LEN(@TableName) <= 121 THEN @TableName + N'History'
            ELSE LEFT(@TableName, 110) + N'_'
                 + CONVERT(NVARCHAR(10), @ObjectId) + N'History'
        END;

    SET @OldTargetReference =
        QUOTENAME(N'DB_TCGDCS_HIS') + N'.' + QUOTENAME(@SchemaName)
        + N'.' + QUOTENAME(@OldHistoryTableName);

    SET @UpdateTriggerName = N'TR_HIS_U_' + CONVERT(NVARCHAR(20), @ObjectId);
    SET @DeleteTriggerName = N'TR_HIS_D_' + CONVERT(NVARCHAR(20), @ObjectId);

    SELECT
        @DropSQL = STRING_AGG
        (
            CAST
            (
                N'DROP TRIGGER ' + QUOTENAME(OBJECT_SCHEMA_NAME(TR.[object_id]))
                + N'.' + QUOTENAME(TR.[name]) + N';' AS NVARCHAR(MAX)
            ),
            N' '
        ),
        @DroppedTriggerCount = COUNT(*)
    FROM sys.triggers AS TR
    WHERE TR.[parent_id] = @ObjectId
      AND
      (
             TR.[name] IN (@UpdateTriggerName, @DeleteTriggerName)
          OR TR.[name] IN
             (
                 N'TR_' + @TableName + N'_UpdateHistory',
                 N'TR_' + @TableName + N'_DeleteHistory'
             )
          OR CHARINDEX(@TargetReference, ISNULL(OBJECT_DEFINITION(TR.[object_id]), N'')) > 0
          OR CHARINDEX(@OldTargetReference, ISNULL(OBJECT_DEFINITION(TR.[object_id]), N'')) > 0
      );

    IF @DropSQL IS NOT NULL
        EXEC sys.sp_executesql @DropSQL;
END;
